    "frontText": "你见过这样的女人吗？\n\n她一个人带孩子。\n她很久没有工作了。\n她不好意思向任何人开口。\n她觉得“困难是自己的事”。\n\n但制度不是这样想的。\n\n家庭人均收入低于当地最低生活保障标准的，\n可以向街道或乡镇申请低保。\n符合条件的单亲妈妈，同样可以申请。",
    "quote": "困难时开口，不是软弱，是在使用制度。",
    "knowledge": "最低生活保障是社会保障体系的最后一道安全网。\n按《最低生活保障审核确认办法》等规定，家庭收入和财产均需符合当地条件。\n具体标准和申请流程由各地规定。\n符合条件的家庭，可向户籍所在地街道或乡镇提出申请。",
