    "reviewNote": "2026-10-12 终审：场景由「被辞退＋律师报价」改为「借款要不回来＋咨询费比标的高」。原稿场景与第 32 天（孕期被优化）撞，且《法律援助法》第三十一条第五项本就把“请求确认劳动关系或者支付劳动报酬”列入可申请法律援助的事项、劳动仲裁也不要求请律师，原因果链会加固“维权先要有钱”的误解；新场景的“请律师不划算”正是免费咨询与调解的价值所在。标题由“12348——请不起律师不是终点”改为“哪天真出了事，先打这个号码”（原句与第 30 天的“等你”重复，且“请不起律师”在当前场景下易被读成必然指派律师）；与我有关删去“也能有律师”，改为“也能知道该怎么做”——民间借贷不在《法律援助法》第三十一条列举事项内，不宜暗示可获指派；作者定稿不加引导句，此段直接以“你交的税、缴的社保”起头；知识段把“符合条件的指派律师”与“是否适用按当地条件确定”并为一句。来源行去掉笼统的“公共法律服务与法律援助入口”，改指 12348；《法律援助法》全文回源到司法部官网；共享登记表 C22（法律援助法）由 flk 首页改为司法部全文页、ORG_12348 由 gov.cn 首页改为中国法律服务网。riskLevel 属周级字段（第 5 周 H），未逐日调整。",
    "stateChange": "你知道法律咨询可以免费",
