    "dow": "周四",
    "dimension": "organization",
    "title": "为劳动所得的工资打电话，不算小题大做",
    "frontText": "公司说资金紧张，\n上个月工资只发了一半。\n\n同事说：“忍忍，\n下个月一起发。”\n“别去闹。”\n\n你想问问，这样行不行。\n又觉得，为半个月工资\n去打个电话，\n是不是有点小题大做？\n\n你默默把手机放回兜里。",
    "quote": "要回自己的工资，不叫闹。",
    "knowledge": "12333\n人力资源社会保障服务热线。\n\n《劳动法》第50条：\n工资应当按月支付，不得克扣或者无故拖欠。\n\n《劳动合同法》第85条：\n未及时足额支付劳动报酬的，\n劳动行政部门责令限期支付；\n逾期不支付的，还要按应付金额加付赔偿金。\n\n“下个月一起发”是公司说的；\n按月发工资，是法律保障你的。",
    "related": "你不用等欠得足够多，才敢去问一句。\n\n12333 会告诉你\n这件事归谁管、怎么投诉，\n要带什么材料。",
    "action": "把12333存进通讯录。\n再把上个月的工资条\n和银行流水找出来，\n放在一起。",
    "itchTrigger": "同事那句“别去闹”，让你把手机放回了兜里",
    "contradiction": "工资按月足额支付是法定义务 vs 欠薪被说成“公司的难处”",
    "verifyTask": "把12333存进通讯录，把工资条和银行流水找出来。",
    "imaginationPrompt": "如果投诉不会让你丢工作，你会先去问哪一句？",
    "safetyNote": "是否构成拖欠、投诉管辖与所需材料以当地劳动保障监察机构口径为准；如被辞退或遭报复，先保留证据再决定，必要时咨询12348。本卡为制度认知科普，不构成法律意见。",
