    "reviewStatus": "complete",
    "draft": false,
    "reviewNote": "2026-10-13 换题并终审。① 换题：本卡原为“怀孕被辞退·三期保护”，与第 19 天（第 3 周·法律，“三期”保护——孕期不是被辞退理由）整卡重复——场景（怀孕告知公司→一周后 HR 说岗位优化）、法条（《劳动合同法》第42条）、出路（继续履行／赔偿金）、行动（存12333＋找出劳动合同）几乎一一对应，且第 19 天在前 28 天区已终审发布，故本卡让题，改讲欠薪投诉。② 法条回源：《劳动法》第五十条（工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资）已在中国人大网全文页逐字核对；《劳动合同法》第八十五条（用人单位未按劳动合同约定或国家规定及时足额支付劳动报酬等情形，由劳动行政部门责令限期支付；逾期不支付的，责令按应付金额百分之五十以上百分之一百以下加付赔偿金）已在上海市人民政府门户与国家市场监督管理总局网站公布的该法全文中逐字核对，该法在国家法律法规数据库的详情页身份亦经渲染确认（法律、2012-12-28 公布、2013-07-01 施行）。③ 来源：《劳动法》（C09）链接由 flk 首页改为该法详情页（已渲染确认：法律、2018-12-29 公布并施行）；本卡撤下《妇女权益保障法》（C01）；来源行去掉笼统条目，改列 12333，共享登记表 ORG_12333 由 gov.cn 首页改为全国人社政务服务平台（12333.gov.cn），其余引用该条目的卡片一并更新链接。④ 文案：标题由作者定为“为劳动所得的工资打电话，不算小题大做”（编辑拟稿为“为半个月工资打电话，不算小题大做”）；实发只发一半、同事劝“忍忍”“别去闹”为编辑新增，可按作者听到的原话替换；2026-10-13 终审后作者改稿：知识段末句由“「下个月一起发」是承诺，不是规定。”改为并列两句“「下个月一起发」是公司说的；／按月发工资，是法律保障你的。”（不涉及法条与来源，终审结论不变）。⑤ 本卡 riskLevel 为周级 H，未逐日调整。已可发布。",
