    "dimension": "organization",
    "title": "路灯黑了三个月，不是没人管",
    "frontText": "你每天下班走的那条路，\n路灯坏了三个月。\n\n每天晚上经过时，要打开手电筒。\n\n你跟物业说了三次，\n每次都说：“好的，会处理。”\n\n没有任何变化。\n\n你跟邻居抱怨，\n邻居说：“投诉也没用。”",
    "quote": "“投诉也没用”——\n你投诉过吗？\n还是只是听别人说的？",
    "knowledge": "12345\n政务服务便民热线。\n7×24小时全天候人工服务。\n\n受理群众对公共服务的咨询、投诉和建议，\n有编号，可以追踪。\n\n它不是“万能电话”，\n但它会把问题转给对的地方，并要求回复，\n具体受理范围和办理时限由各地规定。",
    "related": "你跟物业说了三次，\n但物业不是政府部门。\n\n12345是政府的接件口。\n你说清楚“谁、何时、何地、发生了什么、希望怎么处理”，\n它就会被记录、被转办、被要求回复。",
    "action": "打12345，说：\n“XX路XX段路灯坏了三个月，\n晚上走路不安全，请尽快处理。”\n\n然后把工单号记下来：\n有回音吗？",
    "itchTrigger": "物业说了三次“会处理”，你就不说了",
