    "title": "家丑可以外扬，安全不能等",
    "frontText": "他推了你一下，\n不是很重。\n\n你摔倒在沙发上，\n没有流血，没有淤青。\n\n他马上道歉，\n说：“我不是故意的”，\n说“你推我，我才推你的”。\n\n你看着孩子，\n想了想：“算了，没受伤。”\n“报警太夸张了。”\n“家丑不可外扬。”",
    "quote": "“不严重”和“不用报警”，\n是两件事。",
    "knowledge": "110 报警电话。\n\n家庭暴力不是“家务事”。\n《反家庭暴力法》规定：\n家庭暴力情节较轻，\n依法不给予治安管理处罚的，\n由公安机关对加害人给予批评教育或者出具告诫书。\n\n出了告诫书，它会记录在案。\n人民法院审理涉及家庭暴力的案件，\n可以根据出警记录、告诫书、伤情鉴定意见等证据，\n认定家庭暴力事实。",
    "related": "比取证更重要的事：\n先离开危险现场，\n去有人、能帮你报警的地方。\n\n生命安全排在取证和维权之前。",
    "action": "把110设成快捷拨号。\n\n先想好要说什么：\n“我在XX地址，有人对我施暴，请出警。”\n\n希望你永远用不上，\n但你需要先知道怎么说。",
    "itchTrigger": "“没有流血”让你把报警两个字收了回去",
