    "reviewNote": "2026-10-11 第5周按作者新稿重写：保留原有场景与写法，去掉案例金额与时限，补回边界与来源字段；法条已按官方全文核验（国家法律法规数据库，2026-10-12），未终审。2026-10-14 作者同日四次改稿：① 正面按新稿重排分行（前三段逗号连行，首处“说”后加冒号，“你推我，我才推你的”补逗号）；② 标题由“110——第一次就报警，不算夸张”改为“没有流血”不等于“没有发生”，该句从制度依据末尾上移为标题、正文不再重复，标题也不再带号码前缀，与第 30—33 天写法一致；③“与我有关”首句句末句号改逗号，“今日行动”末两句改为“希望你永远用不上，／但你需要知道怎么说。”（去掉“你”并逗号连行）；④“与我有关”删去“你不需要‘家丑不可外扬’，／你需要的是安全。”两句，并把“还有一件事比取证更重要：”改为“比取证更重要的事：”；“今日行动”末句补“先”字，作“但你需要先知道怎么说”。四次改动均不涉及场景、事实与来源，仍待终审。2026-10-14 作者再改稿：标题换为“家丑可以外扬，安全不能等”（按全站 365 张卡的惯例，标题不带句号），原先的标题“‘没有流血’不等于‘没有发生’”回填到制度依据末尾，内容不丢；新标题正面回应正面收尾的“家丑不可外扬”。事实与来源未变，仍待终审。2026-10-14 终审。① 法条回源：按国家法律法规数据库全文逐字核对（全文已存 .local/lawrefs/中华人民共和国反家庭暴力法.docx），第十五条「公安机关接到家庭暴力报案后应当及时出警，制止家庭暴力，按照有关规定调查取证，协助受害人就医、鉴定伤情」、第十六条「家庭暴力情节较轻，依法不给予治安管理处罚的，由公安机关对加害人给予批评教育或者出具告诫书」、第十七条「公安机关应当将告诫书送交加害人、受害人，并通知居民委员会、村民委员会」、第二十条「人民法院审理涉及家庭暴力的案件，可以根据公安机关出警记录、告诫书、伤情鉴定意见等证据，认定家庭暴力事实」。原稿把第十六条写成「公安机关可以对加害人批评教育或者出具告诫书」，与原文「由……给予」不符，已改为原文（引用法条不得软化语气）；「告诫书会记录在案，是重要证据」原无出处，已在其后补入第二十条原文作为依据；边界句「是否出具、如何认定，由公安机关依法决定」保留，与第十六条“批评教育或告诫书由公安择一”一致。② 来源维护：共享登记表 C02 的 sourceUrl 由 flk 首页改为该法详情页 detail?id=2c909fdd678bf17901678bf7f9d60889&title=中华人民共和国反家庭暴力法；该 URL 已用无头 Edge 实测打开（页面标题与元数据为：中华人民共和国反家庭暴力法、法律、全国人民代表大会常务委员会、公布 2015-12-27、施行 2016-03-01）。sourceStatus 由 local_policy_required 改为 verified_specific_source，与第 29—33 天一致；告诫书出具条件仍受地方口径影响，localNote 保留。③ 来源清理：sourceIds 原为 [C02, C03, ORG_12338]，其中 C03（民法典）与 ORG_12338（妇联/12338）在卡面正文与来源行中都没有出现，已删除，只留 C02；第 30 天 sourceRefs 里 C02 的 URL 一并刷新。④ 衔接链：carryIn「工单号记下来了；有些事比投诉更急。」承接第 33 天 carryOut，本卡 carryOut「110设成快捷拨号；这一周，你手里已经有五个号码。」接第 35 天 carryIn，已核对一致。⑤ 排版与命名：标题「家丑可以外扬，安全不能等」12 字、单行渲染（实测 26px / 行高 25.5px），正面文本容器 668/668 无截断，背面知识区滚动正常；标题按全站惯例不带句号，与 365 张卡无重名。⑥ 遗留：110 尚无独立登记项（公安部站点对抓取返回 521），「110报警服务」目前只出现在来源行文字里，未绑定 registry 条目；第 35 天仍为 draft。已可发布。2026-10-14 作者再改稿：删去制度依据末尾的““没有流血”不等于“没有发生””，卡上不再保留该句（正面原文本来就没有这一句；正面与它同题的是引语““不严重”和“不用报警”，是两件事。”，未删，待作者决定）。事实与来源未变，终审结论不变。2026-10-14 作者再改稿（二）：正面收尾两句改为“你看着孩子，／想了想：“算了，没受伤。””，事实与来源未变，终审结论不变。2026-10-14 作者指出制度依据重复，已去重：①《反家庭暴力法》原先被引入两次（“规定：”与“第二十条：”），现只引入一次；②“是重要证据”与第二十条同义，删去该短语，由第二十条自己说明；③“是否出具、如何认定，由公安机关依法决定”与第十六条“由公安机关对加害人给予批评教育或者出具告诫书”同义，删去。法条引述与来源未变，第二十条内容保留。2026-10-14 作者再改稿：“告诫书会记录在案。”改为“报警的话，告诫书会记录在案。”，把记录与报警动作连起来；法条引述与来源未变。作者随即再改稿：该句改为“出了告诫书，它会记录在案。”，避免“报了警就一定有告诫书”的误读（第十六条为批评教育或告诫书二选一）。法条引述与来源未变。",
