    "title": "当家做主的你启动流程中",
    "reviewer": "Codex 官方回源复核",
    "reviewDate": "2026-10-14",
    "frontText": "楼下那个垃圾站，两个月没人清。\n夏天味道很大，你绕路走。\n\n你先是找了物业。\n物业说：\n“这事得找环卫，我们反映过。”\n\n再要来环卫的电话，\n打了两次，\n两次都记了工单，没人回。\n\n群里有人说：\n“打12345吧，回访是打到本人的。”\n\n你想了想：\n“算了，多一事不如少一事”",
    "quote": "“多一事不如少一事”——\n所以呢？就一直臭着吗？",
    "knowledge": "12345 的流程是：\n登记 → 转办 → 承办单位办理 → 回访。\n\n你能做的三件事：\n① 记下工单号；\n② 问清承办单位和承诺时限；\n③ 超时没有回音，\n   用同一个工单号再打一次，\n   把上一次的记录接上。\n\n它不承诺一定解决，\n但每一次诉求都会留下记录。\n具体受理范围和办理时限由各地规定。",
    "related": "你找过物业，也找过环卫，\n但这两个号码之间，还缺一条路。\n\n那条路，就是 12345。\n它不一定亲自解决，\n但它会指定一个承办单位，并要求回复。\n\n打之前先想好这几句：\n谁、何时、何地、\n发生了什么、希望怎么处理。",
    "action": "打12345，说：\n“XX路XX号楼下垃圾站两个月没清运，\n夏天气味很大，请尽快处理。”\n\n然后把工单号记下来。",
    "itchTrigger": "垃圾站两个月没人管，你绕路走了两个月",
    "contradiction": "找物业、打环卫都没用 vs 12345有编号、可追踪",
    "verifyTask": "为垃圾站这件事打一次12345，记下编号。",
    "imaginationPrompt": "如果这次真的有回音，你会接着打第二次吗？",
