    "reviewNote": "2026-10-15 复核完成：①《政府信息公开条例》第二十七条已回源到中国政府网条例全文（“除行政机关主动公开的政府信息外，公民、法人或者其他组织可以向地方各级人民政府、对外以自己名义履行行政管理职能的县级以上人民政府部门……申请获取相关政府信息”）——条文不带用途要求，现行文本中亦无“特殊需要”字样（2008年版第十三条要求“根据自身生产、生活、科研等特殊需要”，2019年修订后删除），卡面上原写的“不需要说明用途”不是该条原文，已删除，改为与条文一致的表述。②《重大行政决策程序暂行条例》（国务院令第713号）第十四条已回源到国务院公报：决策承办单位应当采取便于社会公众参与的方式充分听取意见，方式包括座谈会、听证会、实地走访、书面征求意见、向社会公开征求意见、问卷调查、民意调查等——“听取公众意见是法定程序”“听证会、公开征求意见”均成立。③原来第三项写的“政府开放日”不在该条例列举之中（属各地政务公开实践），2026-10-15 已换成条例明确列举的“问卷调查”，现卡面三项均在条例方式之内；条例同时列举的座谈会、实地走访、书面征求意见、民意调查同样可用。④原 sourceIds 的 POLICY_LOCAL 与 PARTICIPATION 均指向 gov.cn 首页，已替换为两部法规的具体页与国家政务服务平台。2026-10-25 按“结论交给读者”原则改写“与我有关”结尾：陈述落在她的动作或感受上，周回顾卡改为问句收尾；法律依据未变。",
