    "frontText": "你和闺蜜约了喝咖啡。\n聊母亲与孩子，\n聊工作与新买的衣服。\n你们很开心聊了两个小时。\n\n但你们没聊过——\n小区那个坏掉的路灯，\n学校门口那个危险的路口，\n新闻里那个被家暴的女人。\n\n你觉得这些事“太远了”，\n“聊这些多沉重啊”，\n“好不容易聚一次，开心点”。",
    "quote": "那些“太远了”的事，\n其实每天都在你身边发生。",
