    "related": "那些被忽略的女性需求——夜间照明、母婴设施、社区儿童活动空间，\n不是因为“不重要”，是因为说的人太少。\n\n你开口的那一次，\n你们聊的东西，\n就不再只是老公、孩子和衣服了。",
    "action": "下次和朋友见面时，试着聊一个“身边的小事”。\n\n就聊小区门口那个路口，问问她：“你觉得危险吗？”",
