    "reviewNote": "2026-10-15 复核完成：①《中国妇女发展纲要（2021—2030年）》已回源到中国政府网纲要全文，第（四）项“妇女参与决策和管理”的主要目标第3条为“各级人大代表和常委会委员中的女性比例逐步提高。各级政协委员和常委中的女性比例逐步提高”，第4至6条为县级以上政府领导班子、部门领导班子和事业单位领导班子中女干部比例逐步提高——卡面“逐步提高各级人大代表、政协委员、领导干部中的女性比例”是这三类目标的压缩，方向一致；但章节名卡片原写“女性参与决策和管理”，纲要原文是“妇女参与决策和管理”，已按原文改正（引导内文字属引用）。②“村民委员会成员中应当有妇女成员，这是法律规定”已回源：2025-10-28修改决定（2026-01-01施行）第六条改为第八条，条文与“法律规定”的定性都成立。③原 sourceIds 的 C01（妇女权益保障法）与 PARTICIPATION（gov.cn 首页）均与正文不符，已替换为纲要页、村组法修改决定页与国家政务服务平台。④纲要属国务院印发的目标性文件（设目标、非设义务），卡面用“设了……的目标”表述准确，未与后一句的法律义务混同。2026-10-25 按“结论交给读者”原则改写“与我有关”结尾：陈述落在她的动作或感受上，周回顾卡改为问句收尾；法律依据未变。",
