    "frontText": "你和朋友一起吃饭，\n她说：“我们公司最近在裁员，\nHR找我谈话，我可能要失业了。”\n\n你问她：“打算怎么办？”\n她：“不知道，再找个班上呗。”\n\n你想跟她说点什么：\n“三期女职工不能随便辞退。”\n“可以要赔偿，也可以要求继续履行。”\n“打12333。”\n\n但你没有说，\n你怕说错了，\n怕她问你“你怎么知道”，\n怕她觉得你“多管闲事”。\n\n你低头夹菜，\n想：算了，她自己的事。",
