    "reviewNote": "2026-10-25 复核完成：正面三句逐条回源——①“三期女职工不能随便辞退”：《妇女权益保障法》（2022年修订）第四十八条规定用人单位不得因结婚、怀孕、产假、哺乳等情形降低工资福利、限制晋职晋级或辞退女职工、单方解除劳动（聘用）合同，同时保留“依法解除、终止”的但书；《劳动合同法》第四十二条另将三期列入不得依第四十条、第四十一条解除的情形——卡面用“不能随便辞退”而非“不能辞退”，与两法的限制范围一致。②“可以要赔偿，也可以要求继续履行”：《劳动合同法》第四十八条规定劳动者要求继续履行的应当继续履行，不要求继续履行或已不能继续履行的，依第八十七条按经济补偿标准的二倍支付赔偿金。③“打12333”：人社服务热线，全国口径已核。来源补上《劳动合同法》（原 source 行漏列）并把《妇女权益保障法》链接从数据库首页换成中国人大网 2022 年修订全文页。sourceStatus 由 principle_only 升为 verified_specific_source；地方受理条件仍以当地人社口径为准，见 localNote。",
