    "frontText": "楼下的路灯又坏了，\n这次你没有绕开。\n\n你先查了该谁管——\n市政、物业，还是社区；\n你拍了照，记下日期；\n打电话过去，记下工单号。\n\n一周没有回音，\n你报着工单号又追了一次。\n\n昨天，你把这件事\n讲给了楼上的阿姨。\n\n她问：“管用吗？”\n你说：“不知道，\n但这次我没当没看见。”",
    "quote": "你绕开了三个月，\n这次没有。",
    "knowledge": "把四步用一次：\n信息 → 证据 → 坚持 → 传递\n\n先知道找谁，\n再留下能证明的东西，\n没回音就追一次，\n最后告诉一个可能需要的人。\n\n四步不是四张卡，是一条路。",
    "related": "你没有一下子做成什么大事，\n只是查了一个电话，\n拍了一张照，追了一次，\n和一个阿姨说了几句。\n\n四步都小得不像“维权”。\n可你走完了一遍，\n如果下次遇到别的事，\n你就知道从哪一步开始了。",
    "action": "选一件你身边的小事，\n这周之内，把四步走一遍：\n查一次信息，留一份证据，\n追一次进展，告诉一个人。\n\n走不完也没关系，记下你停在哪一步。",
