    "frontText": "1912年3月，南京。\n\n一群女人\n站在临时参议院门口。\n她们手里拿着请愿书，\n要求一件事：\n把女子的参政权，\n写进正在起草的约法里。\n\n她们等在里面的人\n给一个答复。\n\n答复没有来。\n\n约法公布了。\n“人民”这两个字里，\n没有女人。",
    "quote": "“人民”这两个字，\n一开始\n并不包括她们。",
    "knowledge": "据公开档案与地方志记载：\n1912年3月，\n唐群英等人\n在南京向临时参议院请愿，\n要求约法写明女子参政权。\n\n请愿没有被采纳。\n\n她们没有就此停下——\n继续上书、办报、办女学，\n把这件事\n一年一年说下去。\n\n这一年，\n是中国女性第一次\n以集体身份\n站到国家议事机构门口。",
    "related": "你也许会说：\n“我又不是什么人物。”\n\n她们当时也不是。\n\n她们只是一群\n不想再等别人\n替自己决定的人。\n\n你今天能说一句\n“关我什么事”，\n也是因为\n有人当年没能说出这句话。",
