    "frontText": "六个年份，摆在你面前。\n\n1912年，\n她们站在参议院门口请愿。\n1920年代，\n女工在夜校学会看工资单。\n1931年，\n“法律前一律平等”写在苏区文件上。\n1939年，\n边区参议会里坐着女参议员。\n1949年，\n女代表坐到了桌子前。\n\n摆在一起看——\n你今天觉得\n理所当然的那些位置，\n没有一个是空的。",
