    "title": "第46条——她的人生不是“第二”",
    "frontText": "你女儿今年初三。\n她成绩很好。\n老师说她能考上重点高中。\n\n你很高兴。\n你跟他爸说：“闺女争气。”\n\n她爸说：\n“女孩子读那么多书干嘛。\n差不多就行了。\n钱留着给儿子以后买房。”\n\n你愣住了。\n你想说：“她成绩这么好，\n为什么不让她读？”\n但你张了张嘴，没说。\n\n你看着女儿房间的灯。\n她还在写作业。\n她不知道，\n她爸已经替她做了决定。",
    "quote": "“女孩子读那么多书干嘛”——\n这句话，你听过吗？\n你信了吗？",
    "knowledge": "《宪法》第46条：\n中华人民共和国公民有受教育的权利和义务。\n\n《妇女权益保障法》第35条：\n国家保障妇女享有与男子平等的文化教育权利。\n\n不分性别。\n每一个孩子。",
    "related": "你女儿的成绩是她自己考出来的。\n\n“钱留着给儿子买房”这句话里，\n女儿的人生被放在第二位。\n\n但你女儿的人生，不是“第二”。\n\n你不需要“说服”谁。\n你只需要知道：\n这句话在法律上站不住脚。",
    "action": "如果女儿正在面临\n“要不要继续读书”的问题，\n告诉她一句：\n“你想读，就读。钱的事我们一起想办法。”\n\n助学贷款、奖学金、妇联帮扶，\n都可以去问。",
