    "contradiction": "“钱留给儿子买房” vs 受教育权不分性别",
    "verifyTask": "告诉女儿一句“你想读，就读”。",
    "imaginationPrompt": "如果没有人替她做这个决定，她想读到哪里？",
    "safetyNote": "教育资助渠道与申请条件因地区和学段而异，以当地教育部门、学校资助中心口径为准；辍学劝返可联系当地教育部门或妇联。",
    "source": "中华人民共和国宪法 / 中华人民共和国妇女权益保障法 / 中华人民共和国义务教育法",
