    "dimension": "constitution",
    "title": "第47条——你有做“没用”的事的自由",
    "frontText": "你一直喜欢画画。\n小时候学过几年，\n后来“学业忙”，停了；\n工作后“没时间”，停了；\n结婚后“家里事多”，停了。\n\n最近你又想捡起来。\n你买了画笔和本子。\n晚上等孩子睡了，画了半小时。\n\n他看见了，说：\n“画这个有什么用？能赚钱吗？”\n\n你说：“就是喜欢。”\n他说：“喜欢能当饭吃？”\n\n你把画笔收起来了。\n你对自己说：“算了，确实没什么用。”",
    "quote": "“有什么用”——\n什么时候，\n“喜欢”也要有用才配存在了？",
    "knowledge": "《宪法》第47条：\n中华人民共和国公民有进行科学研究、\n文学艺术创作和其他文化活动的自由。\n\n“自由”——\n不是“如果有用就可以”。\n是“你有权利做”。",
    "related": "“有什么用？”“能赚钱吗？”\n“喜欢能当饭吃？”\n这些话你听过很多次。\n\n每次你想做一件“没用”的事，\n它们就冒出来。\n\n但宪法第47条说：\n你有文化活动的自由。\n\n画画。写字。唱歌。跳舞。\n不是所有事都要“有用”。",
    "action": "今天，做一件“没用但你喜欢”的事。\n\n画画、写字、听歌、散步、发呆。\n半小时就够。\n\n不用告诉任何人。\n给你自己。",
    "itchTrigger": "你重新拿起画笔，被问“能赚钱吗”",
    "contradiction": "“喜欢能当饭吃” vs 你有文化活动的自由",
