    "title": "第49条——孩子脸上的眼泪，不同意那句话",
    "frontText": "他打孩子。\n不是第一次。\n\n他说“男孩子不打不成器”。\n他说“我小时候也是被打大的”。\n\n你看着孩子哭。\n你想拦。\n但你说：\n“他也是为了孩子好。”\n“我要是拦，他会更生气。”\n“忍忍就过去了。”\n\n孩子不哭了。\n他回房间了。\n你坐在客厅。\n你觉得哪里不对。\n但你说不出来。",
    "quote": "“为了孩子好”——\n孩子脸上的眼泪，\n同意这句话吗？",
    "knowledge": "《宪法》第49条：\n婚姻、家庭、母亲和儿童受国家的保护。\n\n《未成年人保护法》第17条\n（2020年修订，\n2021年6月1日施行）：\n未成年人的父母或者其他监护人\n不得对未成年人实施家庭暴力。\n\n《反家庭暴力法》第12条：\n未成年人的监护人应当以文明的方式进行家庭教育，\n不得实施家庭暴力。",
    "related": "“我也是被打大的”——\n这句话不是理由，是循环。\n\n你不需要“拦得住”。\n你只需要做一件事：\n让孩子知道\n“打人是不对的，妈妈知道，妈妈会想办法”。\n\n你不是“破坏家庭”。\n你是在保护家庭里最弱的那个人。",
    "action": "如果家里正在发生这种情况，先做两件事：\n\n一是把110 存进快捷拨号；\n二是让孩子知道\n“不管是谁打你，都可以告诉妈妈”。\n\n如果危险正在发生，\n先带孩子离开现场，\n去有人、能报警的地方。\n\n不要为了留下证据而留在危险里。",
    "itchTrigger": "他打孩子，你告诉自己“忍忍就过去了”",
