    "dimension": "law",
    "title": "离婚损害赔偿——错了的一方要赔",
    "frontText": "你在谈离婚。\n\n这八年里，\n他有过别人，\n也动过手。\n你一直没有说，\n因为你说不出口。\n\n现在谈分割的时候，\n他理直气壮：\n“房子是我的名字，\n存款我出的多，\n咱们一人一半也差不多。”\n\n你坐在那儿。\n你想起这八年。\n你想：\n我受的这些，\n就白受了吗？",
    "quote": "“过去的事了，\n说这些干什么”——\n真的不用说了吗？",
    "knowledge": "《民法典》第1091条：\n有下列情形之一，\n导致离婚的，\n无过错方有权请求损害赔偿：\n\n（一）重婚；\n（二）与他人同居；\n（三）实施家庭暴力；\n（四）虐待、遗弃家庭成员；\n（五）有其他重大过错。\n\n也就是说：\n这些不是“过去的事”，\n它们是\n可以单独提出请求的\n法定情形。\n\n要主张，就需要证据——\n报警记录、病历、\n聊天记录、\n证人证言都可以。",
    "related": "“都过去了”——\n你可以不再追究，\n但那是你选择放下，\n不是你没有权利。\n\n损害赔偿\n和财产分割\n是两件事：\n一个看谁的过错，\n一个看钱怎么分。\n\n两个请求可以一起提。",
    "action": "今天做一件小事：\n\n如果这些事发生在\n你或你认识的人身上，\n先把能留下的东西收好：\n报警回执、病历、\n聊天记录、照片。\n\n不一定要用，\n但别让它消失。",
    "itchTrigger": "谈分割时他说“过去的事说这些干什么”，你差点就认了",
    "contradiction": "“都过去了” vs 1091条可以单独请求损害赔偿",
    "verifyTask": "写下你能拿得出的那几样材料，看还缺哪一样。",
    "imaginationPrompt": "如果这些话在调解室里说出来，你说的顺序会是什么？",
