    "dimension": "law",
    "title": "财产分割——先弄清家里有什么",
    "frontText": "你想离婚。\n\n但你忽然发现\n你并不清楚\n家里到底有什么：\n他不知道什么时候\n把车过户了；\n存款在哪张卡上\n你也不确定；\n公司的股份写着谁的名字\n你从来没问过。\n\n你跟朋友说。\n朋友说：\n“先把钱的事弄清楚，\n别到时候人财两空。”\n\n你打开手机银行。\n你连密码都要想一会儿。",
    "quote": "你在这段婚姻里付出了这么多年，\n却说不清\n你名下有什么。",
    "knowledge": "《民法典》第1087条：\n离婚时，\n夫妻的共同财产\n由双方协议处理；\n协议不成的，\n由人民法院\n根据财产的具体情况，\n照顾子女、女方\n和无过错方权益的原则判决。\n\n第1092条：\n一方隐藏、转移、变卖、\n毁损、挥霍夫妻共同财产，\n或者伪造夫妻共同债务\n企图侵占另一方财产的，\n在离婚分割共同财产时，\n对该方可以少分或者不分；\n离婚后另一方发现的，\n可以另行起诉\n请求再次分割。\n\n所以第一步不是吵架，\n是把财产清单列出来。",
    "related": "“我不在乎钱”——\n这句话\n在最需要底气的时候\n会变成最贵的一句话。\n\n你不需要争，\n你只需要知道：\n房子、车、存款、股权、\n公积金、保险，\n各自写着谁的名字。",
    "action": "今天做一件小事：\n\n在备忘录里\n建一个“家里的钱”清单，\n能填多少填多少：\n房产、车、存款、\n公积金、保险。\n\n填不满也没关系，\n缺口就是你要问的。",
    "itchTrigger": "车什么时候过户的你都不知道，存款密码要想一会儿",
    "contradiction": "“我不在乎钱” vs 1092条对转移财产可以少分或不分",
    "verifyTask": "写下你家的财产清单，标出你不确定的那几项。",
    "imaginationPrompt": "如果这张清单你三年前就列过，今天会少慌多少？",
