    "title": "被辞退说你“严重违纪”——要看证据",
    "frontText": "公司找你谈话。\n\nHR 说：\n“你严重违反公司规章制度，\n我们决定解除劳动合同。”\n\n你愣了。\n你想起你做了什么——\n上个月迟到了两次，\n在部门群里\n抱怨过一句流程。\n\n你问：\n“依据哪一条制度？”\nHR 说：\n“公司规定。”\n\n你说：“我没见过\n这份规定。”\nHR 说：\n“入职的时候\n都在员工手册里。”",
    "quote": "“严重违纪”——\n依据的是哪一条、\n谁证明？",
    "knowledge": "《劳动合同法》第39条：\n劳动者有下列情形之一的，\n用人单位可以解除劳动合同：\n在试用期间被证明\n不符合录用条件；\n严重违反用人单位的规章制度；\n严重失职、营私舞弊\n造成重大损害；\n同时与其他用人单位建立劳动关系\n严重影响本单位工作；\n以欺诈、胁迫等手段\n订立劳动合同；\n被依法追究刑事责任。\n\n注意两点：\n一、依39条解除，\n用人单位不需要支付经济补偿——\n所以公司爱用这一条；\n二、要用得成立，\n规章要合法有效、\n要事先告知过你、\n要有证据。\n\n拿不出证据，\n就可能是违法解除。",
    "related": "“公司规定”——\n这四个字\n不是免死金牌。\n\n你只需要问三句：\n哪一条规定？\n什么时候告诉过我？\n证据是什么？\n\n问完，\n把谈话内容\n用邮件或消息\n再确认一遍。",
    "action": "今天做一件小事：\n\n把入职时拿到过的\n员工手册、\n聊天通知、\n邮件翻一遍。\n\n如果找不到，\n就发一条消息：\n“请把解除依据的\n  制度条款发我一份。”",
