    "title": "产假返岗——岗位不是“适应适应”出来的",
    "frontText": "你休完产假回去上班。\n\n你发现——\n你原来的项目\n交给了别人。\n你原来的工位\n坐了新人。\n你被安排到了\n一个角落的位置。\n\n你去找领导。\n领导说：\n“你刚回来，\n先适应适应。”\n\n你想说：\n“我适应什么？\n我的岗位在哪？”\n\n但你没说。\n你怕说了\n显得你“不好安排”。",
    "quote": "你只是生了一个孩子。\n不是犯了一个错。",
    "knowledge": "《妇女权益保障法》：\n用人单位不得\n因女职工怀孕、生育、哺乳\n降低其工资、\n予以辞退、\n或者解除劳动（聘用）合同，\n也不得将其调整到\n不适合的岗位。\n\n《劳动合同法》第42条：\n女职工在孕期、产期、哺乳期的，\n用人单位\n不得依照第40条、第41条\n解除劳动合同。\n\n所以：\n“先适应适应”\n不是调岗的正当理由；\n岗位调整\n应该有书面依据，\n工资不应因此降低。",
    "related": "“不好安排”——\n这四个字\n让你把问题\n咽了回去。\n\n但你只是\n休了一个法定假期。\n\n你可以平静地说：\n“请给我\n  这次调整的书面依据，\n  以及原岗位的安排。”",
    "action": "今天做一件小事：\n\n把产假前的\n岗位说明、\n工资条、\n返岗后的通知\n放在一起。\n\n找不出差异，\n就先留一份\n自己的岗位记录。",
    "itchTrigger": "“先适应适应”——你的项目、工位、位置都没了",
    "contradiction": "“刚回来先忍忍” vs 不得因生育降薪或调离",
