    "frontText": "你爸生病了。\n\n你请了假回去照顾。\n你哥说：\n“我工作忙，你多担待。”\n你妈说：\n“你是女儿，\n细心，你来照顾。”\n\n你哥出了点钱。\n你出了力。\n你每天在医院陪床、\n送饭、擦身。\n\n你爸出院后，\n你哥说：\n“爸的房子，\n以后就给我吧。\n你是嫁出去的女儿。”\n\n出力的时候你是女儿。\n分东西的时候你是外人。",
