    "dimension": "law",
    "title": "这一周，家里的事每一件都有条文",
    "frontText": "六件看起来都像“家里事”的事。\n\n他外面欠的钱，\n被说成你也要还。\n他做过的那些事，\n被说成“都过去了”。\n家里的财产，\n你说不清有什么。\n被辞退还说你“严重违纪”。\n产假回来，\n工位成了别人的。\n照顾三个月，\n被说“你是外人”。\n\n这些事看起来\n都是“家里的事”。\n可它们每一件，\n都有对应的条文。",
    "quote": "“家里的事”——\n不是法律的例外，\n也不是你的例外。",
    "knowledge": "这一周的六条规则：\n\n💳 共同债务——\n共债共签，\n或用于家庭日常生活\n💔 损害赔偿——\n重婚、同居、家暴、遗弃、\n其他重大过错，\n无过错方可请求赔偿\n🏠 财产分割——\n照顾子女、女方\n和无过错方；\n隐藏转移可以少分或不分\n📄 过失性辞退——\n要有合法制度、\n事先告知和证据\n👶 产假返岗——\n不得因生育降薪或调岗\n🧾 继承——男女平等，\n尽主要扶养义务可以多分",
    "related": "这六件事\n指向同一个答案：\n\n它们都需要一样东西\n才能从“说法”\n变成“权利”——\n\n记录。\n\n签字、截图、单据、\n时间、金额。\n\n你留的不是纸，\n是你说话时的底气。",
    "action": "拍一页给她——\n家里刚休完产假的同事，\n在家照顾老人的朋友。\n\n照片发过去就行，\n一个字都不用配。",
    "itchTrigger": "六件事都被说成“家里的事”，你以前都当成只能忍",
