    "frontText": "你生病了。\n不是什么大病。\n但要去医院。\n\n要挂号。\n要看诊。\n要拿药。\n\n你排了一上午队。\n你付了钱。\n\n你看着收费单。\n你只知道“花了不少”。\n\n你不知道哪些能报销。\n不知道报销比例是多少。\n不知道起付线是什么。",
    "quote": "你交了这么多年医保——\n它到底能为你做什么？",
    "knowledge": "医保报销不是“按总花费打折”，\n它有几个关键词：\n\n目录——\n只有医保目录内的药品、\n诊疗项目和耗材\n才进入报销范围；\n起付线——\n先自己付到这个数，\n以上部分才开始按比例报；\n报销比例——\n按参保类型、医院等级不同；\n封顶线——\n一年最多报多少。\n\n在外地看病，\n多数情况要先办\n异地就医备案：\n国家医保服务平台 APP、\n12393 医保服务热线，\n或者当地医保经办窗口\n都可以问。\n\n具体比例和起付线\n各地不同，\n以参保地政策为准。",
    "related": "你不是“白交了医保”。\n\n你只是从来没有人\n教你怎么看那张单子。\n\n今天你只需要认识\n三个词：\n目录、起付线、报销比例。\n\n下次付完钱，\n你会知道该问哪一句。",
