    "frontText": "六笔钱，你都交过。\n\n生病了不知道能报多少。\n每年可能多交了税。\n公积金不买房也能用。\n下班路上被撞可能算工伤。\n养老金到底怎么算。\n老了谁来照顾。\n\n串起来看——\n那些你以为\n“交了就没了”的钱，\n其实一直在等你用它。\n只是从来没人帮你连起来。",
    "quote": "不是“运气好”，\n是你交过的钱\n本来就该为你工作。",
    "knowledge": "这一周的六个入口：\n\n🏥 医保——\n看目录、起付线、比例，\n异地就医先备案\n🧾 个税——\n3月1日到6月30日汇算，\n七项专项附加扣除\n🏦 公积金——\n租房等情形可以提取，\n先查余额\n🚧 工伤——\n非本人主要责任的\n上下班交通事故应当认定\n🕰️ 养老金——\n缴费年限满15年按月领取，\n多缴多得、长缴多得\n🤝 长护险——\n试点城市制，\n先查本地有没有",
    "related": "这六件事，\n你今天可能一件都用不上。\n\n但你已经知道\n它们各自在哪里。\n\n这就是底气——\n不是现在能用，\n而是需要的时候\n不会被别人一句\n“不行”打发。",
    "action": "截一张图，\n丢进那个\n总说“公司都交好了”的群里。\n\n不解释，\n也不用@谁。",
    "itchTrigger": "六笔钱你都在交，却一笔都没认真查过",
    "contradiction": "“交了就没了” vs 每一项都有入口和规则",
    "verifyTask": "写下这一周里和你最有关的那一笔钱，和它的查询入口。",
    "imaginationPrompt": "如果这六项里有一项今年用上，你最希望是哪一项？",
