    "title": "茶水间里说得最凶的那句",
    "frontText": "午休的茶水间，\n永远是抱怨声最大的地方。\n\n“绩效怎么算的，\n  谁知道。”\n“加班从来不打卡。”\n“请假要看脸色。”\n\n说得最凶的是老周。\n\n下午三点开会，\n主持人问：\n“大家还有意见吗？”\n\n会议室里\n一片安静。\n老周在看手机。",
