    "frontText": "你翻出工资单。\n\n基本工资、\n绩效、\n津贴、\n扣款——\n一栏一栏排得很整齐。\n\n但你想不出\n绩效那一栏\n到底按什么算。\n\n你去问人事。\n人事说：\n“这是公司的制度。”\n\n你问：\n“制度在哪儿？”\n\n她说：\n“一直在的。”",
