    "title": "“说了会不会被记上”",
    "frontText": "你把想法\n在群里打了三遍，\n又删了三遍。\n\n你怕的不是没人听。\n\n你怕的是\n有人听了，\n而且记住了是谁说的。\n\n这种担心\n不是你想多了。\n\n所以法律\n才要替“说”这件事\n修一道门。",
    "quote": "不是要你胆子大，\n是要有一条\n不怕被记名字的路。",
    "knowledge": "法律给“说”修的门\n有三处：\n\n一、集体合同草案\n应当提交职工代表大会\n或者全体职工讨论通过\n（《工会法》第二十一条）；\n\n二、用人单位单方解除\n劳动合同，\n应当事先将理由通知工会，\n工会认为违法可以要求纠正，\n用人单位要将处理结果\n书面通知工会\n（《工会法》第二十二条、\n《劳动合同法》第四十三条）；\n\n三、职工申请仲裁或者起诉，\n工会应当\n给予支持和帮助。\n\n也就是说，\n维权不是\n你一个人\n单挑。",
    "related": "你以前\n把“说”和“安全”\n放在天平两端，\n只能二选一。\n\n现在你知道\n有第三条路：\n\n把话\n变成程序里的一步。\n\n程序里的那一步，\n不叫“告状”。",
    "action": "今天做一件小事：\n\n如果你想提一件事，\n先问一句：\n\n“这件事\n  有没有\n  职工代表大会\n  或者工会的渠道？”\n\n先问渠道，\n再问结果。",
