    "title": "把一句抱怨，写成一条诉求",
    "frontText": "“凭什么这么算绩效。”\n\n这是一句抱怨。\n\n有人接不住。\n\n换成这样：\n\n“绩效里\n  客户满意度那一项，\n  占多少分、\n  由谁打分，\n  能不能\n  看一版书面说明。”\n\n这句话\n可以被回答。\n\n能被回答的话，\n才有地方去。",
    "quote": "抱怨没有错，\n只是它\n进不了门。",
    "knowledge": "一条能进会场的诉求\n通常有三段：\n\n一、事实：\n哪一件事、\n什么时间、\n涉及哪些人；\n\n二、依据：\n它和哪一条制度\n或者法律有关\n（比如\n《劳动合同法》第四条）；\n\n三、请求：\n你要的\n是一个说明、\n一次协商，\n还是\n一项修改。\n\n三段写下来，\n它就从情绪\n变成了一条\n要处理的事。",
    "related": "你不用变得\n很会说话。\n\n你只要\n把句子\n换一种写法：\n\n从“凭什么”\n换成\n“请说明一下”。\n\n一样硬，\n但有人\n非答不可。",
    "action": "今天做一件小事：\n\n把昨天写下的那句原话，\n改写成三段：\n\n事实一行、\n依据一行、\n请求一行。\n\n不用发出去。",
