    "frontText": "你跟伴侣提这件事。\n\n他说：“写了也没人看。\n那些都是走形式。”\n\n你说：“我就问问。”\n他说：“问什么，有时间不如多睡会儿。”\n\n你没再说什么。\n但你心里那句“写了也没人看”，\n跟着你进了厨房。",
