    "frontText": "这一周你做了四件小事：\n\n记下了联络站在哪，\n问清了流程，\n写下了三句话，\n走到了接待桌前。\n\n你原来的话是：\n“我算哪门子事。”\n\n现在你能说出口的是：\n“我写过，也递过。”",
