    "knowledge": "求助一般分五层，\n一层不行\n往上一层走：\n\n① 自行沟通——\n  先跟对方说清楚；\n② 求助专门机构——\n  社区、妇联、工会、\n  行业主管部门；\n③ 投诉举报——\n  12345、12315、12333 等；\n④ 法律途径——\n  调解、仲裁、复议、诉讼；\n⑤ 舆论与监督——\n  媒体、代表、\n  监察与检察。\n\n换层\n不是从头再来，\n是把同一件事\n交给更有权处理的人。\n\n你要做的第一件事\n是把这条路径\n写下来。",
