    "frontText": "你打了三次电话，\n听到三句话：\n\n“这个不归我们管。”\n“你得走程序。”\n“你先等等，\n 我们再看看。”\n\n你每次都说\n“好吧”，\n然后挂掉。",
    "quote": "“好吧”——\n这两个字\n是很多事\n停下来的地方。",
    "knowledge": "三种最常见的推回，\n可以这样接：\n\n“不归我们管”\n→ “那请问\n   归哪个单位？\n   能不能给我\n   一个电话或者窗口？”\n\n“你得走程序”\n→ “需要哪些材料、\n   多长时间、\n   有没有书面清单？”\n\n“你先等等”\n→ “大约多久？\n   我下次咨询\n   用哪个编号查？”\n\n每一次\n都记下：\n时间、\n对方单位、\n答复内容。\n\n推回来\n不等于封死，\n多数时候\n是你还没问到\n具体的那个人。",
    "related": "你以前\n把挂断电话\n当成结局。\n\n其实\n那只是\n这一格的答复。\n\n往上走一格，\n你要的只是\n一个名字、\n一个电话、\n一个期限。",
    "action": "今天做一件小事：\n\n把这三句\n抄在备忘录里：\n\n“归哪个单位？”\n“需要什么材料？”\n“大约多久？”",
    "itchTrigger": "“好吧”——你每次都用这两个字结束通话",
    "contradiction": "“又是推诿” vs 你还没问到具体的那个人",
    "verifyTask": "抄下那三句话，写下你上次听到的是哪一句。",
    "imaginationPrompt": "如果那三句你早会背，第三次电话会不会不一样？",
    "safetyNote": "沟通时保持记录与礼貌；如遇推诿，可通过12345或主管部门反映，紧急危险先拨110。",
