    "title": "1931：苏区法令里的女工产假",
    "frontText": "1931年，江西。\n\n苏区通过的劳动法令里，\n有一行字\n是关于女工的：\n\n女工生育，\n产前产后\n给予带薪休息。\n\n同一片土地上，\n上海的纱厂女工\n还在为一句话\n罢工：\n“生孩子不能被开除。”",
    "quote": "“生孩子不能被开除”——\n这句话，\n当时需要罢工才说得出口。",
    "knowledge": "据公开史料记载：\n1931年苏区通过的劳动法令\n对女工的生育待遇\n作了规定，\n产前产后\n给予带薪休息；\n并禁止\n在孕期、产期\n随意辞退女工。\n\n这些法令\n当时只在苏区实行，\n执行得也不彻底。\n\n但它第一次\n把“生孩子”\n写成用工单位的责任，\n而不是女工自己的事。",
    "related": "你今天看产假\n觉得是“单位给的”。\n\n在一百年前，\n它是女工\n用罢工和开除的代价\n换来的一行字。\n\n你今天能理直气壮\n去问人事“产假怎么算”，\n是从这里开始的。",
    "action": "今天做一件小事：\n\n想一想你妈妈\n或者你奶奶\n生完孩子休了多久。\n\n问一句，\n记下来。\n\n这就是你家版本的历史。",
    "itchTrigger": "你以为产假是单位给的福利，从没想过它是一行争来的字",
