    "frontText": "1951年。\n\n新中国第一部\n劳动保险条例公布，\n里面写着：\n\n女工人与女职员生育，\n产前产后\n共给假56天，\n产假期间工资照发。\n\n那时候\n大多数女人\n是在家里生孩子的。\n\n但“56天”\n第一次\n写在全国性的文件上。",
