    "frontText": "1992年。\n\n《中华人民共和国\n妇女权益保障法》\n公布。\n\n它是第一部\n专门为妇女\n制定的法律。\n\n其中一章，\n叫“劳动权益”。\n\n里面写的不是\n“照顾妇女”，\n而是：\n\n男女同工同酬；\n不得因结婚、怀孕、\n产假、哺乳\n降低工资或辞退。",
    "quote": "它写的不是“照顾”，\n是“不得”。",
    "knowledge": "1992年《妇女权益保障法》\n设有劳动权益专章，\n内容包括：\n男女同工同酬；\n不得因结婚、怀孕、产假、\n哺乳等情形\n降低女职工工资、\n辞退女职工\n或者解除劳动合同；\n不得安排不适合妇女从事的劳动。\n\n同一年，\n《妇女权益保障法》\n还配套出台了\n实施办法与地方条例。\n\n这部法律\n后来在2005年、\n2018年、2022年\n多次修改，\n2022年那次\n新增了就业性别歧视禁令\n和性骚扰防治机制。",
    "related": "“不得”这个词\n在法条里很轻，\n在生活里很重。\n\n因为它意味着：\n不是单位“愿不愿意”，\n是它“不能”。\n\n你下次说\n“我们公司不让……”的时候，\n可以换成：\n“法律不允许。”",
