    "title": "第41条：提意见不是“多事”",
    "frontText": "你在办事大厅\n等了一个上午。\n\n窗口只开一个，\n队伍排到门口，\n提示牌上的时间\n和实际不一样。\n\n你在大厅的意见本上\n写了一行字：\n“能不能多开一个窗口？”\n\n旁边有人说：\n“写这个有什么用，\n  多事。”\n\n你把笔放下了。",
    "quote": "“多事”——\n这个词\n是谁教给你的？",
    "knowledge": "《宪法》第41条：\n中华人民共和国公民\n对于任何国家机关\n和国家工作人员，\n有提出批评和建议的权利。\n\n它不是一句客气话，\n是写在宪法里的权利。\n\n可以提的地方：\n意见本、\n政务服务好差评、\n12345、\n部门官网的意见征集、\n人大代表联络站。\n\n提意见\n不需要先“懂政策”，\n你遇到的那件事\n就是依据。",
    "related": "你被说过“多事”，\n也被说过“较真”。\n\n这两个词\n都是用来\n让提意见的人\n闭嘴的。\n\n你不需要反驳，\n你只需要知道：\n写那一行字，\n是在行使权利，\n不是在给别人添麻烦。",
    "action": "今天做一件小事：\n\n下次去办事，\n如果遇到\n明显的流程问题，\n在意见本上\n或者好评差评里\n写一行。\n\n就一行，\n署不署名都行。",
    "itchTrigger": "“写这个有什么用，多事”——你把笔放下了",
