    "title": "申诉、控告、检举——三个动作不一样",
    "frontText": "你想反映一件事。\n\n有人说：\n“你去申诉。”\n有人说：\n“你得控告。”\n有人说：\n“直接检举啊。”\n\n你听下来\n一个词都没记住，\n只觉得\n它们好像是同一件事。",
    "quote": "同一个部门，\n三个词，\n三条不同的路。",
    "knowledge": "《宪法》第41条里的三个动作：\n\n申诉——\n你对已经生效的\n处理决定不服，\n要求重新审查；\n常见的是\n行政复议、\n行政诉讼、\n再审申诉。\n\n控告——\n你是被害人或知情人，\n指控某个具体行为\n侵犯了你的合法权益。\n\n检举——\n你发现\n违法违纪的线索，\n向有关机关反映，\n你自己未必是被害人。\n\n同一件事，\n“谁被侵害”\n决定你走哪一条。",
    "related": "你之所以\n分不清这三个词，\n是因为\n从来没有人\n用一句人话讲过。\n\n现在你会了：\n先问自己一句——\n“被侵害的人是我吗？”\n\n是我，走申诉或控告；\n不是我，走检举。",
    "action": "今天做一件小事：\n\n把这三个词\n写在备忘录里，\n各配一句你自己的话。\n\n下次有人问你\n“这事该找哪”，\n你能答上来。",
    "itchTrigger": "三个词听过很多次，一次也没弄清过区别",
