    "title": "举报会不会被知道是我——实名与保密",
    "frontText": "你想举报一件事。\n\n你知道领导\n在报销上做了手脚。\n你手里有截图。\n\n你打开举报页面，\n看到两个选项：\n\n“实名举报”\n“匿名举报”。\n\n你的手指停在屏幕上。\n\n你怕的不是举报，\n是被知道是谁举报的。",
    "quote": "“我怕的不是举报，\n是被人知道\n是我举报的。”",
    "knowledge": "纪检监察机关受理检举控告，\n实行\n实名举报优先办理、\n优先反馈；\n对举报人的姓名、\n工作单位、\n住址等信息\n应当严格保密；\n打击报复举报人的\n应当严肃处理。\n\n匿名举报\n同样会被受理，\n但因为无法联系，\n一般不能反馈结果。\n\n所以实名与匿名的区别是：\n实名能收到答复，\n匿名只能等结果。\n\n（依据：监察法、\n纪检监察机关\n处理检举控告工作规则）",
