    "title": "被公权力伤了——国家赔偿有专门的通道",
    "frontText": "你听说了一件事。\n\n有人被错抓了，\n关了几个月，\n后来证明没有犯罪。\n\n人放出来了，\n工作没了，\n身体也垮了。\n\n有人在旁边说：\n“算他倒霉。”\n\n你听着，\n想起了\n“个国家赔不赔”\n这个问题。",
    "quote": "“算他倒霉”——\n这四个字\n在法律里不成立。",
    "knowledge": "《国家赔偿法》：\n国家机关和国家工作人员\n违法行使职权\n侵犯公民合法权益\n造成损害的，\n受害人有取得国家赔偿的权利。\n\n常见情形包括：\n违法拘留、\n违法罚款或没收财物、\n违法查封扣押冻结财产、\n错捕错判等。\n\n怎么走：\n先向赔偿义务机关提出，\n也可以在申请复议、\n提起诉讼时一并提出；\n对赔偿决定不服的，\n可以申请复议\n或者向法院赔偿委员会申请。\n\n时效：\n请求国家赔偿的时效\n一般是两年。",
    "related": "国家赔偿\n听起来离你很远。\n\n它存在的意义\n不只是赔钱，\n是承认一件事：\n公权力也会错，\n错了要负责。\n\n你可以不记条号，\n但要记得\n有这条通道。",
    "action": "今天做一件小事：\n\n把这两个词\n写进备忘录：\n“国家赔偿”、\n“两年时效”。\n\n知道它存在，\n就已经不一样了。",
    "itchTrigger": "“算他倒霉”——这四个字听起来太顺了",
