    "frontText": "你替朋友打听。\n\n他被罚了款，\n不服，\n但一直在犹豫：\n\n“要不要申诉？”\n“会不会越弄越麻烦？”\n\n他犹豫了三个月。\n\n你帮他查完\n才发现一件事：\n\n有些门\n不是关了，\n是过了时间\n才关的。",
