    "title": "分手后的纠缠——不是“不甘心”，是违法",
    "frontText": "你和他分手了。\n分手一个月了。\n他还是每天发消息。\n\n“你在干嘛？”\n“今天去哪了？”\n“为什么不回我？”\n\n你拉黑了他。\n他换了个号继续发：\n“你以为拉黑我\n就找不到你了？”\n\n你开始害怕。\n出门会回头看。\n不敢发朋友圈。\n怕他知道你在哪。\n\n你跟朋友说。\n朋友说：\n“他就是不甘心，\n过一阵就好了。”\n\n可你已经怕了三个月。\n他还没“好”。",
    "quote": "“分手了”——\n不代表他还有权利\n继续出现在你的生活里。",
    "knowledge": "《治安管理处罚法》（2025年修订，\n2026年1月1日施行）第五十条：\n多次发送信息干扰他人正常生活，\n以及滋扰、纠缠、跟踪等行为，\n可以依法给予罚款、拘留，\n并可以责令禁止接触。\n\n《妇女权益保障法》第29条：\n禁止以恋爱、交友为由，\n或者在终止恋爱关系、离婚之后，\n纠缠、骚扰妇女。\n\n《反家庭暴力法》第37条：\n家庭成员以外共同生活的人之间\n实施的暴力行为，参照本法执行。\n\n🔹 案例：有女性在分手后被持续\n蹲守、跟踪、信息轰炸。\n她保存了聊天截图、蹲守照片，\n记下了每次的时间和地点，\n报警后由公安机关依法处理。\n处理结果因个案而异。",
    "related": "分手不是“同意你一直找我”。\n是我把我给你的那个位置，\n收回来了。\n\n你可以做的事有三条：\n报警；\n符合条件时申请人身安全保护令；\n就精神损害主张赔偿。\n\n他纠缠你，\n不是因为你值得被追，\n是因为他还需要一个\n随时能被他找到的人。\n那个人，不该是你。",
    "action": "保存，不要回。\n\n把消息截图，\n把时间、地点、次数记下来。\n不用今天做完全部，\n先把“记录”这件事开始。\n\n然后告诉一个人——\n家人、朋友、同事都行。\n有人知道，\n你就不是一个人。",
    "itchTrigger": "“他就是不甘心，过一阵就好了”——可你已经怕了三个月",
