    "title": "AI换脸——你的脸不是别人的素材",
    "frontText": "你刷手机的时候，\n看到一条视频。\n\n视频里是你。\n但不是你拍的。\n\n你的脸被换到了\n另一个人身上。\n那个人在做你\n从来没做过的事。\n\n视频在群里传。\n有人@你。\n有人笑。\n有人问“这是你吗”。\n\n你手在抖。\n你想删。\n但你删不掉——\n它已经传开了。\n\n你把自己关在房间里。\n觉得所有人都在看你。\n觉得这辈子完了。",
    "quote": "你的脸不是别人的素材库。",
    "knowledge": "《民法典》第1019条：\n任何组织或者个人\n不得以丑化、污损，\n或者利用信息技术手段伪造等方式\n侵害他人的肖像权。\n\n第1024条：民事主体享有名誉权。\n第1034条：自然人的个人信息受法律保护。\n\n《治安管理处罚法》（2025年修订）\n第五十条：\n公然侮辱、诽谤，散布他人隐私等行为，\n可以依法给予治安管理处罚。\n\n情节严重的，\n可能触及《刑法》第246条\n侮辱罪、诽谤罪。\n侮辱、诽谤案件一般\n由被害人向法院提起自诉。",
    "related": "这不是你的错。\n永远不是。\n\n该被追问的，\n是制作和传播的人。\n\n你可以同时走三条线：\n存证——截图、录屏，\n把链接和时间一起保存；\n下架——要求平台删除；\n追责——向公安机关报案。\n\n你不需要为\n别人的恶意感到羞耻。",
    "action": "如果你或者你认识的人\n遇到这件事，\n今天先做一件：\n把所有内容截图、录屏，\n记下链接和时间。\n\n不要删。\n存证是后面所有动作的地基。",
    "itchTrigger": "视频里的那个人是你，可那件事你从没做过",
    "contradiction": "“别理它，越理越传” vs 存证、下架、报案都有路径",
    "verifyTask": "把链接、时间和群聊截图，放进一个文件夹。",
    "imaginationPrompt": "如果今天就要把这件事交给一个机构，你会先给谁看这份证据？",
    "safetyNote": "不要单独联系制作、传播者；涉未成年人或涉色情内容优先报警。人身安全受威胁时拨打110，法律咨询可拨12348。",
    "source": "中华人民共和国民法典 / 中华人民共和国治安管理处罚法 / 中华人民共和国刑法 / 中华人民共和国个人信息保护法",
