    "title": "精神暴力——不动手，也可以是伤害",
    "frontText": "他从来不跟你吵架。\n他不打你。\n他不骂你。\n\n但你说什么，\n他都不回应。\n\n你问他今天吃什么，\n他看手机。\n你说孩子学校要开家长会，\n他说“哦”。\n你说我最近很累，\n他说“谁不累”。\n\n跟他说话，\n像对着一堵墙。\n\n你有时候想：\n“他是不是不爱我了？”\n可你又说不出\n他做错了什么。\n\n他没做错什么。\n他只是——\n让你一个人\n待在这段婚姻里。",
    "quote": "不吵架，不动手，\n也可以是伤害。",
    "knowledge": "《反家庭暴力法》第2条：\n家庭暴力是指家庭成员之间\n以殴打、捆绑、残害、限制人身自由\n以及经常性谩骂、恐吓等方式\n实施的身体、精神等侵害行为。\n\n精神暴力，\n也是家庭暴力的一种。\n\n但它比一条伤情更难讲清：\n长期漠视、拒绝沟通、\n经济控制、贬低羞辱，\n要落到具体行为上——\n讲得出时间、次数和后果。",
    "related": "冷暴力不是“性格不合”。\n不是“他不会表达”。\n\n你不需要等到\n他动手了\n才承认自己在受伤害。\n\n你的感受不需要\n他承认才算数；\n但这份感受\n将来要拿得出来，\n就得先落在纸上。",
    "action": "记三件事：\n发生了什么，\n你说了什么，\n他的反应是什么。\n\n一句话也算。\n写下来的那一刻，\n你就不是在“一个人想”。",
    "itchTrigger": "你说“我最近很累”，他说“谁不累”",
    "contradiction": "“他不打你就行” vs 精神侵害也是家庭暴力",
