    "dimension": "law",
    "title": "离婚的两条路——先分清，再害怕",
    "frontText": "你想离婚。\n\n你上网查了。\n有人说“冷静期30天”。\n有人说“第一次起诉不判离”。\n有人说“要等半年再起诉”。\n\n你越查越害怕。\n\n你想：\n“离个婚怎么这么难？”\n“是不是我这辈子\n都离不掉了？”\n“我是不是要困在这里了？”",
    "quote": "“离不掉”——\n这句话，你验证过吗？",
    "knowledge": "《民法典》第1077条：\n协议离婚有30天冷静期。\n冷静期只适用于协议离婚。\n\n第1079条：\n有下列情形之一，调解无效的，\n应当准予离婚——\n重婚或者与他人同居；\n实施家庭暴力或者虐待、\n遗弃家庭成员；\n有赌博、吸毒等恶习屡教不改；\n因感情不和分居满二年；\n其他导致夫妻感情破裂的情形。\n\n所以有家暴、有遗弃、\n有赌博这些情形，\n不是“等冷静期”的事，\n是可以直接起诉的。\n\n现实里“第一次没判离、\n六个月后再起诉”\n是常见路径，\n不是“永远离不掉”。",
    "related": "你不是困住了。\n你只是还没弄清楚\n自己要走的\n是哪一扇门。\n\n有家暴时，\n不要在没有安全安排的情况下\n跟对方坐下来谈协议离婚。\n\n协议谈不成，\n不等于你走不了。",
    "action": "今天只做一件事：\n把这件事\n写成两个选项——\n协议离婚，\n还是起诉离婚。\n\n分清了，\n你就知道该去民政局，\n还是去法院诉讼服务中心。",
    "itchTrigger": "你越查越怕，因为没人告诉你两条路的区别",
    "contradiction": "“第一次不判离就是离不掉” vs 法定情形应当准予离婚",
    "verifyTask": "写下你要走的是协议还是起诉，还缺哪样材料。",
    "imaginationPrompt": "如果今天就去窗口问一句，你最想问的是哪一句？",
    "safetyNote": "存在家庭暴力时优先安排人身安全，可申请人身安全保护令，并通过12338、12348或当地法律援助获得帮助；是否准予离婚由法院依法认定。",
