    "dimension": "law",
    "title": "抚养费——不是“他给不给”，是“他必须给”",
    "frontText": "你离婚了。\n孩子归你。\n他每个月给抚养费。\n\n第一个月，他给了。\n第二个月，他说\n“手头紧，下个月给”。\n第三个月，他没提。\n第四个月，你问他要。\n他说：\n“你又不缺这点钱。”\n\n你一个人带孩子。\n你要上班，要接送，\n要辅导作业，要付房租。\n\n你不缺这点钱吗？\n你缺。\n\n但更让你难受的是——\n他在用钱\n把你按在原地。",
    "quote": "他用“给不给”，\n决定你能不能站稳。",
    "knowledge": "《民法典》第1085条：\n离婚后，子女由一方直接抚养的，\n另一方应当负担\n部分或者全部抚养费。\n\n数额怎么定：\n有固定收入的，\n一般按月总收入的20%–30%；\n负担两个以上子女的，\n可以适当提高，\n但一般不超过月总收入的50%。\n（《民法典婚姻家庭编解释（一）》第49条）\n\n他不给，\n你可以向法院申请强制执行，\n也可以先申请支付令。",
    "related": "抚养费不是\n“他人好不好”的问题。\n是判决书、调解书\n或者离婚协议里写着的义务。\n\n你不需要求他，\n也不需要等他良心发现。\n\n法院可以依法查询、冻结、划扣，\n也可以依法采取限制措施——\n具体怎么做，由法院按个案决定。",
    "action": "第一步不是吵架，是留痕：\n把催告写成一条消息\n（微信、短信都行），\n把日期和回复保存下来。\n\n第二步：\n拿着判决书、调解书\n或离婚协议，\n去法院问一句：\n“强制执行怎么申请？”",
    "itchTrigger": "他说“你又不缺这点钱”，你知道你在缺什么",
    "contradiction": "“求他给” vs 判决书可以申请强制执行",
    "verifyTask": "写下第一条催告，注明日期，保存回复。",
