    "dow": "周六",
    "dimension": "law",
    "title": "生育自主——法律说的是哪一句",
    "frontText": "你35岁，未婚。\n你想要一个孩子。\n\n你去咨询。\n柜台后面的人\n看了你一眼：\n“结婚证呢？”\n\n你说：\n“我没结婚。”\n她说：\n“那不行。”\n\n你站在门口。\n你在想——\n我想当一个母亲，\n这需要另一个人\n签字同意吗？",
    "quote": "“结婚证呢？”\n法律说的是哪一句？",
    "knowledge": "《妇女权益保障法》第32条：\n妇女依法享有生育子女的权利，\n也有不生育的自由。\n\n《民法典》第1071条：\n非婚生子女享有\n与婚生子女同等的权利，\n任何组织或者个人\n不得加以危害和歧视。\n\n但要分清：\n“有生育权”\n不等于所有辅助生殖方式\n都能由你自行选择。\n辅助生殖技术另受\n人类辅助生殖技术管理\n和属地规定约束。",
    "related": "“必须结婚才能生孩子”——\n这句话你听过很多次。\n\n法律没有这样规定。\n非婚生子女的户籍登记、\n继承权，与婚生子女同等。\n\n但辅助生殖不是\n“想清楚了就能做”的事。\n有的门开着，\n有的门还关着。\n门在哪里，\n取决于你所在的地方\n现在的规定。",
    "action": "如果你正在想这件事，\n今天查两样：\n本地的生育登记怎么办；\n本地辅助生殖的受理条件。\n\n查到什么就是什么。\n先知道，再决定。",
    "itchTrigger": "“结婚证呢？”——你被一个词挡在门外",
    "contradiction": "“当妈妈要先结婚” vs 生育权的主体是妇女个人",
    "verifyTask": "查一次本地生育登记或辅助生殖的受理条件，记下出处。",
    "imaginationPrompt": "如果规则由你来问、由你来记，你还会站在门口吗？",
    "safetyNote": "辅助生殖技术的适用人群、机构资质与伦理审查以国家与所在地现行规定为准；本卡只做制度认知，不作承诺。",
