    "dimension": "law",
    "title": "这一周，那些“只能忍”的事，法律没同意",
    "frontText": "六件你以前都忍着的事。\n\n分手之后，他还在纠缠。\n你的脸被人换到别人身上。\n他不动手，但你像一个人\n住在婚姻里。\n你想离婚，却怕离不掉。\n他把抚养费当成手里的开关。\n你想生育，柜台先要看结婚证。\n\n这六件事放在一起——\n那些你以为只能忍的事，\n条文里都写了下一步。",
    "quote": "你不是只能忍。\n你只是还不知道\n那句话写在哪一页。",
    "knowledge": "这一周的六件工具：\n\n🧷 纠缠骚扰——可以报警，\n可以责令禁止接触\n🖼️ 换脸伪造——侵害肖像权、名誉权，\n情节严重可能涉刑\n🧱 精神暴力——也是家庭暴力，\n但要落到记录上\n🚪 离婚两条路——\n协议有冷静期，\n起诉看法定情形\n💰 抚养费——可以申请强制执行\n👶 生育自主——生育权主体是你，\n辅助生殖另有规定",
    "related": "这六条里，\n有几条今天还用不上。\n没关系。\n\n它们真正的用处是——\n哪天你真的需要，\n你不会以为\n自己只能忍。",
    "action": "给自己留一行：\n“如果有一天我需要，\n  我会先找______。”\n\n写完，\n把这一周里\n最戳你的那张卡\n单独存一份。\n\n等她开口的时候，\n你手里就有东西给她。",
    "itchTrigger": "六件事你都遇见过，只是以前以为“只能忍”",
    "contradiction": "“只能忍” vs 六条路都写着下一步",
    "verifyTask": "写下“我会先找______”，填上一个真实的入口。",
