    "title": "生育津贴——别把那张纸放到过期",
    "frontText": "你生了孩子。\n\n出院的时候，\n护士递给你一张纸：\n“生育津贴申领指南”。\n\n你看了看。\n你放进了包里。\n你回到家。\n你把那张纸放在了茶几上。\n\n然后你带孩子。\n你喂奶。\n你换尿布。\n你哄睡。\n\n你忘了那张纸。\n\n三个月后你收拾茶几，\n又看到了它。",
    "quote": "“生育津贴”——\n你听过。\n但你领了吗？",
    "knowledge": "《社会保险法》第56条：\n女职工生育享受产假等情形，\n可以按照国家规定\n享受生育津贴；\n生育津贴按照\n职工所在用人单位\n上年度职工月平均工资计发。\n\n它是“生育保险待遇”的一部分，\n不是单位发的福利，\n也不是“看你有没有提”。\n\n要留意两件事：\n一、申领时限——\n各地不同，\n有的按天算、有的按月算；\n二、入口——\n当地医保 APP、\n医保经办机构，\n或者12393。\n\n现在很多地方\n在生育登记、住院结算时\n可以直接办理。",
    "related": "你不是“忘了就算了”。\n\n那笔钱是按法律\n算给你的，\n只是需要有人\n在期限内提出。\n\n产后最忙的时候\n最容易被放下，\n把它交给一个人——\n让他去查、去问。",
    "action": "今天做一件小事：\n\n身边有人刚生完孩子，\n就打开手机搜：\n“你所在城市\n  + 生育津贴 申领”。\n\n只看一眼时限。\n就一眼。",
    "itchTrigger": "那张纸在茶几上放了三个月，你甚至不记得它写了什么",
    "contradiction": "“忘了就算了” vs 津贴有时限、也有入口",
    "verifyTask": "查一次本地的生育津贴申领时限，写下那个日期。",
    "imaginationPrompt": "如果那张纸出院那天就被看懂了，这笔钱会落到哪里？",
