    "title": "托育贵得不想上班——先看看有没有普惠的",
    "frontText": "你产假快结束了。\n你开始焦虑。\n\n孩子谁来带？\n你妈身体不好。\n你婆婆还没退休。\n他要上班。\n你也要上班。\n\n你查了托育机构。\n一个月三四千。\n\n你算了算你的工资。\n你发现你上班赚的钱，\n一半要交给托育。\n\n你想：\n“那我上班图什么？”",
    "quote": "“上班图什么”——\n先别急着算这笔账，\n先问一句：\n有没有别的价？",
    "knowledge": "普惠托育：\n国家在推动\n“方便可及、价格可承受、\n质量有保障”的\n托育服务。\n\n形式包括：\n社区托育点、\n用人单位办托、\n幼儿园开设托班、\n家庭托育点等。\n\n部分城市会发放\n托育消费券，\n或者对普惠机构\n给予运营补贴。\n\n价格、名额和申请方式\n各地差别很大，\n可以问社区、卫健委\n或者打12345。\n\n有的地方\n在“托育服务”小程序里\n能查到备案机构名单。",
    "related": "“一个月三四千”——\n这个价格是市场价，\n不一定是你唯一的选择。\n\n普惠托育的关键\n不是“更便宜”，\n是“政府认过的价”。\n\n问一句，\n不一定有；\n不问，一定没有。",
