    "frontText": "他请了陪产假。\n15天。\n\n他在家待了15天。\n他打了15天游戏。\n他睡了15天懒觉。\n\n你喂奶。\n你换尿布。\n你哄睡。\n你伤口还疼。\n你整夜没睡。\n\n你跟他说：\n“你能不能帮帮我？”\n他说：\n“我不是在陪你吗？”\n\n你看着他。\n你想说：\n“陪我不是坐在沙发上打游戏。”",
    "quote": "“陪产假”——\n是“陪”，\n还是“产”？",
    "knowledge": "陪产假（有的地方叫护理假、育儿假）：\n由各省、自治区、直辖市的\n人口与计划生育条例规定，\n天数各地不同，\n一般在7 到30天之间；\n部分地方还有\n夫妻共用的育儿假。\n\n它是法定假期——\n不是单位给的福利，\n也不是“申请了要谢谢领导”。\n\n想知道自己能休多少天，\n可以查当地人口与计划生育条例，\n或者打12333 问人社部门。\n\n单位不按规定给假，\n可以向人社部门或工会反映。",
    "related": "“我不是在陪你吗”——\n这句话\n把放假当成任务完成。\n\n假期解决的是\n“有时间”，\n分工解决的是\n“有没有做”。\n\n你可以把这两件事\n分开说：\n“这15天，\n  你负责哪几件事？”",
    "action": "今天做一件小事：\n\n查一次你所在省份的\n陪产假（护理假）天数，\n记下来。\n\n再列三件\n他可以独立做的事——\n换尿布、夜里拍嗝、\n带娃出门两小时。",
    "itchTrigger": "他“陪你”陪了15天游戏，你伤口还疼",
    "contradiction": "“我不是在陪你吗” vs 假期不等于分工",
    "verifyTask": "查清本省陪产假天数，写下三件他能独立完成的事。",
    "imaginationPrompt": "如果那15天你们提前分过工，夜里会不会不一样？",
    "safetyNote": "假期天数与工资待遇按当地人口与计划生育条例和人社部门规定执行；产后如出现情绪持续低落、失眠，建议及时就医或拨打12356心理援助热线。",
    "source": "地方人口与计划生育条例 / 人力资源和社会保障公共服务入口",
