    "frontText": "你是自由职业者。\n\n你没有公司。\n你没有单位。\n你自己接活。\n\n你每个月赚不固定。\n你没有社保。\n你没有公积金。\n\n你想过自己交。\n但你不知道怎么交。\n你不知道交多少。\n你不知道交了有什么用。\n\n你觉得“算了，以后再说”。\n你已经“以后再说”了三年。",
