    "title": "这一周，那些“只能自己扛”的事，都有安排",
    "frontText": "六件你以前都自己扛的事。\n\n生育津贴差点放到过期。\n托育贵得让人不想上班。\n陪产假的15天打了游戏。\n想创业不知道从哪开始。\n自由职业没有社保。\n租房越来越贵。\n\n说穿了——\n那些你以为\n“只能自己扛”的事，\n其实都有对应安排。\n只是这些从来没人一条条说过。",
    "quote": "不是“国家不管”，\n是你还没被告诉\n入口在哪。",
    "knowledge": "这一周的六个入口：\n\n💰 生育津贴——\n按单位上年度月平均工资计发，\n注意申领时限\n🧒 托育——\n普惠托育有政府认的价，\n问社区和卫健委\n👨‍👩‍👧 陪产假——\n地方条例规定，\n7 到30天不等\n🏪 创业——\n创业担保贷款、\n创业补贴、免费培训\n📱 灵活就业——\n可以个人身份参保\n🏠 住房——\n保障性租赁住房\n多数不设收入线",
    "related": "这六件事\n能收进同一页：\n\n它们都需要你\n先问一次。\n\n问，不花钱；\n不问，\n每一项都会\n继续变成“自己扛”。",
    "action": "发两张出去。\n\n一张给刚生完孩子的同事，\n一张给一个人接活的她。\n\n理由不用写，\n她们看得懂。",
    "itchTrigger": "六件事你以前都当成“自己扛”",
