    "title": "劳动仲裁——先别急着说“可能没用”",
    "frontText": "你被公司辞退了。\n\nHR 说：\n“你自己辞职吧。\n这样对你我都好。”\n\n你问：“为什么？”\nHR 说：\n“没有为什么。”\n\n你签了那张\n《自愿离职申请书》。\n\n走出公司大门，\n你才反应过来——\n好像不是我想走的。",
    "quote": "“你自己辞职吧”——\n这句话，是谁在替谁做决定？",
    "knowledge": "劳动争议调解仲裁法：\n劳动仲裁专门处理劳动争议。\n\n被违法辞退、拖欠工资、\n不缴社保、不签劳动合同——\n都可以申请劳动仲裁。\n\n时效：\n从知道权利被侵害之日起\n一年内。\n\n费用：\n劳动争议仲裁不收费。\n\n在压力下签的“自愿离职”，\n是不是有效，\n要看有没有真实的自愿，\n由仲裁或法院认定。",
    "related": "“自愿离职书”——\n如果是在压力下签的，\n它不一定是“自愿”。\n\n你不是“签了就完了”。\n你是“签了还能问一问”。\n\n先问。\n问不花钱。\n问了才知道\n自己有没有权利。",
    "action": "如果你最近被辞退，\n今天做一件小事：\n\n把劳动合同、工资条、\n聊天记录、离职文件\n收进一个文件夹。\n\n然后打12333 或者\n去劳动仲裁委问一句：\n“我这种情况能申请吗？”",
    "itchTrigger": "HR 说“你自己辞职吧，这样对你我都好”，你签了",
