    "title": "人民调解——不用打官司的那个中间选项",
    "frontText": "你和邻居吵架了。\n\n她家的空调外机\n装在你家窗户旁边。\n晚上吵得你睡不着。\n\n你跟她说了三次。\n她说：\n“我家空调装我家墙上，\n关你什么事。”\n\n你找了物业。\n物业说：\n“我们只能协调。”\n\n你想：\n“难道只能打官司？”",
    "quote": "“打官司太夸张”——\n你还有第三个选项。",
    "knowledge": "社区调解委员会：\n设在居委会、村委会。\n\n免费调解邻里纠纷、\n家庭矛盾、小额债务等。\n\n《人民调解法》：\n经调解达成的调解协议\n具有法律约束力，\n当事人应当按照约定履行；\n还可以申请法院司法确认。\n\n调解不成，\n也不影响你去起诉。",
    "related": "“打官司太夸张”——\n你说得对。\n\n但“只能忍着”\n也不对。\n\n社区调解就是为这种事设的：\n不收费，\n不用请律师，\n不用上法庭。\n\n坐下来谈不成的，\n再谈下一步。",
    "action": "今天只问一句：\n\n去居委会或者村委会，\n问：\n“咱们这儿\n  有人民调解委员会吗？”\n\n问一下，不花钱。",
    "itchTrigger": "说了三次没用，物业只会说“我们只能协调”",
    "contradiction": "“只能忍着或打官司” vs 有免费的人民调解可以先用",
