    "title": "诉讼服务中心——不会写起诉状，可以先问",
    "frontText": "你想起诉一个人。\n\n他欠你钱不还。\n你想去法院。\n但你真的不知道怎么去。\n\n你上网搜。\n有人说要写起诉状。\n有人说要先立案。\n有人说要交诉讼费。\n有人说要请律师。\n\n你关掉网页。\n你想：\n“我连第一句话都不知道\n  该写什么。”",
    "quote": "“不知道怎么起诉”——\n不是“不能起诉”。",
    "knowledge": "法院诉讼服务中心：\n提供立案咨询、诉讼引导、\n材料收转、费用缴纳等服务。\n\n你可以去窗口直接问：\n“我要起诉，需要什么材料？”\n\n起诉状有模板；\n诉讼费按《诉讼费用交纳办法》，\n符合条件的可以申请\n缓交、减交或者免交。\n\n是否符合条件、\n能不能立案，\n由受理法院依法认定。",
    "related": "你不是“不懂法律\n就不能维权”。\n\n你是还没去那个窗口。\n\n法院的诉讼服务中心\n本来就是为\n“不知道怎么写”的人\n准备的。",
    "action": "如果你有一件\n一直想告又不会告的事，\n今天做一件小事：\n\n把“我要起诉，\n  需要准备什么”\n先写在备忘录里。\n\n哪天顺路，\n去窗口问一次。",
    "itchTrigger": "搜索框里写满了“怎么起诉”，你却始终没走进那道门",
