    "title": "离婚不知道从哪问——先分清两条路",
    "frontText": "你想离婚。\n但你不知道\n该从哪里开始。\n\n你上网搜。\n有人说去民政局。\n有人说去法院。\n有人说要写协议。\n有人说要请律师。\n\n越搜越乱。\n你把手机扣在桌上。",
    "quote": "“我不知道从哪开始”——\n其实只有两条路。",
    "knowledge": "协议离婚：\n去民政局婚姻登记处。\n双方同意，\n有30天冷静期，\n期满后领取离婚证。\n\n诉讼离婚：\n去法院。\n一方不同意，\n或者存在家庭暴力、遗弃、\n赌博屡教不改、\n因感情不和分居满二年等情形，\n可以起诉，\n由法院判决或者调解。\n\n两个地方都有咨询窗口，\n可以先去问流程。",
    "related": "你不是“不知道怎么办”。\n\n你是不知道该去问谁。\n\n民政局——问协议离婚。\n法院——问起诉离婚。\n\n有家暴时，\n不要在没有安全安排的情况下\n跟对方坐下来谈协议离婚。",
    "action": "如果你在考虑这件事，\n今天先做一件事：\n\n写下你要走的是\n协议，还是起诉。\n\n分清了，\n你就知道\n该去哪一个窗口。",
