    "title": "法律援助——够不够条件，问一次就知道",
    "frontText": "家里因为一套老房子\n闹了两年。\n\n亲戚说：\n“你要争，\n就去请律师。”\n\n你去问了一次。\n律师说，\n咨询加代理\n要先付一笔钱。\n\n你算了算：\n要争的那一份\n还不够付律师费。\n\n你跟自己说：\n“算了，不折腾了。”\n\n你不知道的是——\n有一部法律\n专门为这句话写的。",
    "quote": "“算了，不折腾了”——\n有一部法律\n就是为这句话写的。",
    "knowledge": "《法律援助法》：\n符合条件的公民\n可以申请法律援助，\n由法律援助机构\n指派律师等人员\n提供法律咨询、代理、\n辩护等服务。\n\n经济困难标准\n由省、自治区、直辖市人民政府\n确定；\n部分事项\n不受经济困难条件限制，\n具体范围以当地规定为准。\n\n怎么申请：\n向办案机关所在地\n或者居住地的\n法律援助机构提出，\n带身份证明\n和经济困难说明；\n也可以先拨12348\n问清要带什么材料。\n\n符不符合条件，\n由法律援助机构审查。",
    "related": "“不划算”——\n这两个字\n劝退过很多该争的事。\n\n法律援助不是打折，\n是制度本来就\n留出来的那一份。\n\n你不需要先证明\n自己有多难，\n你只需要去问一次：\n够不够条件。",
    "action": "今天做一件小事：\n\n把12348\n和12338 放在一起\n存进通讯录。\n\n哪天真的需要，\n你不用再从头找。",
