    "frontText": "楼下贴了一张通知：\n\n“定于本周五下午三点，\n  召开居民议事会，\n  讨论小区东门改造。”\n\n你看了看时间。\n下午三点，\n你在上班。\n\n你把它拍下来\n发到群里。\n群里有人回：\n“又是这个时间。”\n\n会开了。\n你没去。",
