    "title": "发言的三句话——事实、诉求、建议",
    "frontText": "你终于去了一次会。\n\n主持人说：\n“还有谁有意见？”\n\n你举了手。\n你说：\n“东门太窄了，\n 婴儿车过不去，\n 很不方便。”\n\n你说完就坐下了。\n\n有人接着说了很多，\n但你那句话\n好像\n没有进入讨论。",
    "quote": "说了\n和\n进入讨论，\n是两件事。",
    "knowledge": "把发言写成三句：\n\n事实——\n“东门宽度不到1.2 米，\n婴儿车和轮椅过不去。”\n\n诉求——\n“希望把东门改宽，\n或者加一个缓坡。”\n\n建议——\n“可以先测量，\n放一个临时坡道试试。”\n\n三句话说完再坐下。\n\n事实让对方无法否认，\n诉求让它变成议题，\n建议让它能被执行。\n\n（宽度数字\n以现场测量为准。）",
    "related": "你以前\n把“说”当成“表达情绪”，\n所以说完就完了。\n\n“太窄了很不方便”\n是感受；\n“不到1.2 米、\n  轮椅过不去”\n是事实。\n\n换一个说法，\n同一件事\n就往前走了一步。",
    "action": "今天做一件小事：\n\n挑一件你一直想说的\n小区或单位的事，\n把它写成三句：\n事实、诉求、建议。\n\n写出来\n就不容易临场忘。",
    "itchTrigger": "说完了，却没有进入讨论，像没说过一样",
    "contradiction": "“我说了呀” vs 事实、诉求、建议三样才推得动",
