    "title": "谁不在场——会上只有几个人说话",
    "frontText": "你数了数。\n\n到场的十几个人里，\n说话的只有三个。\n\n一个是退休的老同志，\n一个是物业的人，\n一个是业主委员会主任。\n\n剩下的人\n都在听。\n\n你想：\n那白天上班的、\n上夜班的、\n一个人带孩子的，\n他们的事\n谁来替他们说？",
    "quote": "到场的代表不了\n没有到场的人，\n但结论会落在所有人身上。",
    "knowledge": "判断一场会\n有没有代表性，\n可以问三句：\n\n① 参会的人是怎么产生的？\n（自愿、推选，\n还是社区通知）\n② 讨论的事项\n影响到谁？\n那些人在场吗？\n③ 结论对不在场的人\n有没有约束力？\n\n如果答案是\n“影响了很多人，\n但到场只有几个人”，\n你可以建议：\n分批开会、\n线上征集意见、\n把未到场的意见\n带进记录。",
    "related": "你不是“没关系的人”。\n\n电梯广告的收入、\n维修基金的使用、\n停车位的分配，\n都和你有关系。\n\n不在场\n不等于不受影响，\n只等于\n没有人替你说话。",
    "action": "今天做一件小事：\n\n如果小区最近\n有一件事定了下来，\n问一句：\n“这件事\n  是怎么表决的？”\n\n听一下答案。",
    "itchTrigger": "十几个人到场，只有三个人说话，结论却算在所有人头上",
