    "frontText": "谈抚养费的时候，\n他说：\n\n“你又不缺这点钱。”\n\n这句话\n你已经听过\n好几次了。\n\n你每次\n都答不上来，\n因为你说的是道理，\n他说的是\n你的状态。",
