    "knowledge": "这类话的套路是：\n\n把“你该不该付”\n换成“你缺不缺”。\n\n接法是把话题\n拉回来：\n\n“缺不缺是我的事，\n  该不该给\n  是判决书上写的。”\n\n三句话原则：\n\n① 不回应对方的评价\n  （不解释你缺不缺）；\n② 回到规则——\n  判决书、\n  离婚协议、\n  法律条文；\n③ 给出动作——\n  “这周不结清，\n   我下周去法院\n   申请强制执行。”\n\n（是否申请执行、\n何时申请，\n由你根据情况决定。）",
