    "dimension": "action",
    "title": "说清楚，不等于撕破脸",
    "frontText": "你终于\n把话说了。\n\n说完之后\n两个人都沉默。\n\n你开始后悔：\n“是不是我\n 太直接了？”\n\n你甚至想\n补一句\n“我不是那个意思”。",
    "quote": "“我是不是太直接了”——\n这句话\n常常出现在\n你刚刚说清事实之后。",
    "knowledge": "说清楚和撕破脸，\n区别在三件事：\n\n① 说的是事，\n  不是人格\n  （“这件事没做”\n  ≠ “你这个人不行”）；\n② 给的是请求，\n  不是判决\n  （“我希望这周内办”\n  ≠ “你必须马上”）；\n③ 话里留了下一步\n  （“你考虑一下，\n   我们周日再谈”）。\n\n沉默\n不代表关系毁了，\n有时候是\n对方第一次\n意识到你认真了。\n\n真正的裂痕\n不是你说清楚了，\n是你\n一直没说。",
    "related": "你怕的是\n关系变冷。\n\n但一直不说\n的关系，\n不是暖的，\n是靠你\n一个人\n维持温度。",
    "action": "今天做一件小事：\n\n把你要说的话\n按三条检查一遍：\n事、请求、下一步。\n\n齐了就发出去。",
