    "title": "哪些事不能商量",
    "frontText": "你们在谈\n一件小事。\n\n谈着谈着，\n他说：\n“这不都是一家人\n 商量着来吗？”\n\n你点头。\n\n可你心里\n有个地方\n咯噔了一下：\n\n有些事\n好像\n不该是\n商量着来的。",
    "quote": "“商量着来”——\n这句话\n有它的适用范围。",
    "knowledge": "可以商量的：\n\n· 钱怎么花、\n  家务怎么分、\n  假期怎么安排；\n· 谁去接孩子、\n  周末去谁家。\n\n不能商量的：\n\n· 你的人身安全——\n  打人、\n  限制人身自由；\n· 你的身体和生育——\n  要不要孩子、\n  什么时候要；\n· 你的证件、\n  你的工资卡\n  由谁保管；\n· 你的社交与工作——\n  能不能上班、\n  能不能见朋友。\n\n这几件事\n不是“家务分工”，\n是权利。\n\n权利\n不进入谈判。",
    "related": "你以前\n把“一家人商量”\n当成美德。\n\n它是美德，\n但不是\n所有事\n都能放上桌。\n\n有些事，\n只有你自己\n能决定。",
    "action": "今天做一件小事：\n\n在纸上写一行：\n“这几件我不商量：__”。\n\n写下来\n就是给自己\n划了一条线。",
