    "title": "1995：四个字第一次被公开说出口",
    "frontText": "1995年，北京。\n\n世界妇女大会\n在北京召开。\n\n在那之前，\n家里挨打这件事\n只有一个说法：\n“家务事”。\n\n那一年，\n有人把它拿出来，\n放到全世界的桌面上，\n写上了一个新名字——\n家庭暴力。",
    "quote": "给它起名字，\n是让它离开“家务事”的第一步。",
    "knowledge": "据公开史料记载：\n1995年，\n联合国第四次世界妇女大会\n在北京召开，\n“家庭暴力”\n作为议题\n被带进中国的公共讨论。\n\n在这之前，\n这件事大多\n被归入“家务事”，\n不进派出所，\n不进法院。\n\n一个词被说出口，\n意味着\n有人开始\n把它当成\n需要被处理的事。",
    "related": "你今天说\n“他打我”\n这四个字很自然。\n\n但“家暴”这个词\n在中文里被承认，\n只有三十年。\n\n在那之前，\n很多人挨了打，\n却连\n该怎么说都不知道。",
