    "dow": "周二",
    "dimension": "history",
    "title": "2001：婚姻法里第一次写进“禁止”",
    "frontText": "2001年。\n\n《婚姻法》修改，\n其中一条写着：\n\n“禁止家庭暴力。”\n\n这是\n“家庭暴力”\n四个字\n第一次\n写进中国的法律。\n\n同一次修改里，\n还有一条：\n遭受家暴的，\n可以请求\n损害赔偿。",
    "quote": "从被议论\n到被写进法律，\n用了六年。",
    "knowledge": "2001年，\n《婚姻法》修改，\n首次在法律中写明\n“禁止家庭暴力”，\n并规定\n因家庭暴力导致离婚的，\n无过错方\n有权请求损害赔偿。\n\n同一时期的\n司法解释进一步明确，\n家庭暴力包括\n殴打、捆绑、残害、\n限制人身自由\n等手段。\n\n从1995年\n把它说出口，\n到2001年\n把它写进法律，\n用了六年。",
    "related": "“法律不是早就管了吗”——\n没有。\n\n在2001年之前，\n家暴\n不是一项\n法律明确定义的行为。\n\n你现在的底气，\n是从这一行字\n开始长出来的。",
    "action": "今天做一件小事：\n\n把这三年排成一行：\n1995 说出口、\n2001 写进法律、\n2016 专门立法。\n\n三个年份，\n三步路。",
