    "title": "第40条：你的信，别人不能拆",
    "frontText": "你回老家，\n在抽屉里看到\n一叠信。\n\n信封是开着的。\n\n你妈说：\n“当年你爸\n 都拆开看过。”\n\n她说得很平常，\n像在说一件\n理所当然的事。",
    "quote": "“都是一家人，\n 看看怎么了”——\n这句话，\n法律不认。",
    "knowledge": "《宪法》第40条：\n中华人民共和国公民的\n通信自由和通信秘密\n受法律的保护。\n\n除因国家安全\n或者追查刑事犯罪的需要，\n由公安机关或者检察机关\n依照法律规定的程序\n对通信进行检查外，\n任何组织或者个人\n不得以任何理由\n侵犯公民的\n通信自由和通信秘密。\n\n《刑法》第252条\n还规定了\n侵犯通信自由罪：\n隐匿、毁弃或者\n非法开拆他人信件，\n情节严重的，\n处一年以下有期徒刑\n或者拘役。",
    "related": "“都是一家人”——\n这四个字\n在很多家里\n等于“没有隐私”。\n\n但宪法写的\n不是“家人除外”。\n\n你的信、你的手机、\n你的聊天记录，\n都不是\n谁想看就能看的。",
    "action": "今天做一件小事：\n\n把这句记下来：\n“通信自由和通信秘密\n  受法律保护。”\n\n哪天有人要翻你的手机，\n你可以先想起它。",
    "itchTrigger": "“都是一家人，看看怎么了”——这句话你听过很多次",
    "contradiction": "“一家人没有隐私” vs 宪法写着通信秘密受保护",
    "verifyTask": "写下宪法第40条的第一句，记住它。",
    "imaginationPrompt": "如果这句话你妈年轻时就听说过，那些信会不一样吗？",
    "safetyNote": "本卡为制度认知科普；通信检查的法定程序以现行法律为准。涉及家庭纠纷时注意人身安全。",
