    "title": "检查床上的边界——你有权知道谁在场",
    "frontText": "你去医院做妇科检查。\n\n医生问诊完，\n说：“需要做个内检。”\n\n你躺在检查床上。\n门没锁。\n你听到外面有人走动。\n帘子没拉严。\n\n医生叫了一个实习生进来。\n说：“你也来看看。”\n\n你愣住了。\n你想说“我不想”。\n但你没说。\n\n你躺着。\n你觉得你不是一个人。\n你是一个“教学工具”。",
    "quote": "躺在检查床上，\n你的身体边界\n就消失了吗？",
    "knowledge": "《基本医疗卫生与健康促进法》第32条：\n公民接受医疗卫生服务，\n对病情、诊疗方案、风险、费用等，\n依法享有知情同意的权利。\n\n《民法典》第1219条：\n需要实施手术、特殊检查、特殊治疗的，\n医务人员应当及时向患者说明\n医疗风险、替代医疗方案等情况，\n并取得其明确同意。\n\n🔹 案例：有女性在妇科检查中\n被实习人员参与检查，事先没有被告知；\n她提出投诉后，由医院按程序处理。\n处理结果因个案而异。",
    "related": "你有权利知道——\n谁来操作。\n有几个人在。\n实习人员是否参与。\n这项检查的必要性是什么。\n\n你有权利拒绝\n任何让你不适的在场人员，\n也有权利在任何时候\n撤回同意。\n\n你不是“教学工具”。\n你是一个有尊严的人。",
    "action": "下次检查前，\n问一句：\n“这个检查是谁来做？\n有实习人员参与吗？”\n\n你有权利问。\n医务人员有义务说明。\n\n问不出口也没关系，\n先把这句话记住。",
