    "title": "医美失败——不是“你期望太高”",
    "frontText": "你去做了一个医美项目。\n\n咨询的时候，咨询师说：\n“这个项目效果特别好，\n做完年轻十岁。”\n\n你心动了。\n你交了钱。\n你上了手术台。\n\n做完之后，你看着镜子。\n不是“年轻十岁”。\n是“肿了十岁”。\n\n你去找他们。\n他们说：\n“恢复期，正常的。”\n“是你自己期望太高了。”\n\n你回家。\n他说：“我早就说你别去做。”\n你妈说：“花那冤枉钱。”\n\n你一个人坐在房间里。\n你觉得是自己的错。",
