    "knowledge": "《医疗美容服务管理办法》：\n医疗美容是医疗行为，\n机构应当取得《医疗机构执业许可证》，\n主诊医师应当具备执业医师资格。\n\n《消费者权益保护法》第8条：\n消费者享有知悉\n其购买、使用的商品\n或者接受的服务的\n真实情况的权利。\n\n如果宣传和实际不符，\n并构成消费欺诈，\n还可以主张惩罚性赔偿——\n是不是欺诈，\n由主管部门或者法院认定。",
    "related": "你不是“期望太高”。\n你是被承诺了\n他们做不到的事。\n\n医美是医疗行为，\n不是普通美容，\n也不是普通服务。\n\n你有权利知道：\n谁给你做，\n他有没有资质，\n用的是什么产品，\n有什么风险。",
