    "title": "租房被拒——住的权利不分性别",
    "frontText": "你在找房子。\n\n看到一个房源：\n位置好，价格合适。\n你打电话过去。\n\n房东问：“你是女生？”\n你说：“是。”\n他说：\n“不好意思，\n这个房子只租给男的。”\n\n你挂了电话。\n你在想——\n我连租房子的资格，\n都要和性别有关吗？\n\n你找了下一家。\n这一家倒是租给女生——\n但房租比同小区的\n贵了两百。\n\n房东说：\n“女生爱干净，\n我的房子保养好。”\n\n你觉得哪里不对。\n但你说不出来。",
    "quote": "住的权利，\n不分性别。",
    "knowledge": "现行法律里，\n没有一条专门写着\n“租房不得因性别加价”。\n\n但《民法典》第14条：\n自然人的民事权利能力一律平等。\n《妇女权益保障法》：\n国家保障妇女享有\n与男子平等的权利。\n以性别为由拒租或者加价，\n与这些原则相冲突。\n\n一些地方的住房租赁管理规定，\n已经把“不得以性别等为由\n拒绝出租或者提高租金”写了进去。\n具体以当地现行规定为准。\n\n🔹 案例：有女性因“只租给男生”被拒租，\n她保存了招租信息和通话录音，\n向住建部门反映后\n按当地规定处理。\n处理结果因个案而异。",
    "related": "“女生事多”\n“女生爱干净所以贵”\n\n这两句话\n都不该由房东\n替你写进租金里。\n\n你不需要因为\n自己是女性，\n就多付一份房租，\n或者被关在\n一扇门之外。",
    "action": "下次遇到“仅限男性”\n或者“女性加价”，\n先把招租信息截图，\n把通话录音保存下来。\n\n然后打12345，\n或者向住建部门反映。\n\n不需要吵架，\n你只要把这句话\n说出去一次。",
