    "contradiction": "“房东说了算” vs 性别不该写进租金里",
    "verifyTask": "查一次你所在城市住房租赁管理规定里有没有这一条。",
    "imaginationPrompt": "如果这句话你替下一个租房的人问出来，会改变什么？",
