    "title": "联名购房——写谁的名字，就是谁的权利",
    "frontText": "你们一起买的房子。\n你出了大头。\n\n但房产证上\n写的是他的名字。\n\n你问：\n“怎么不写我的名字？”\n\n他说：\n“反正咱俩是一起的，\n写谁不一样。”\n他说：\n“下次再买就写你的。”\n他说：\n“你不信任我吗？”\n\n你信了。\n\n后来你们分开了。\n他说：\n“房子是我的。\n房产证上写的我的名字。”",
    "quote": "爱情是信任。\n房产证是证据。\n这两个不矛盾。",
    "knowledge": "《民法典》第209条：\n不动产物权的设立、变更、\n转让和消灭，\n经依法登记，发生效力；\n未经登记，不发生效力，\n法律另有规定的除外。\n\n第297条：\n不动产或者动产\n可以由两个以上组织、个人共有。\n\n所以：\n出资不等于登记。\n没写名字的一方，\n要靠转账记录、聊天记录\n证明共同出资的合意。\n\n🔹 案例：有女性联名购房\n但只登记在对方名下，\n分开后对方主张房屋归其个人所有；\n她提交了转账记录和沟通记录，\n由法院依证据认定处理。\n结果因个案而异。",
    "related": "“写谁不一样”——\n这句话，\n在法律上是错的。\n\n写在房产证上的人，\n就是权利人。\n没写的人，\n需要靠证据\n才能证明权利。\n\n这不是“不信任”。\n这是把信任的后果\n先讲清楚。",
    "action": "如果你已经与人联名购房，\n检查一下\n房产证上有没有你的名字。\n\n把每一笔出资的\n转账记录留存，\n备注写“共同购房出资款”。\n\n如果还没买，\n签字之前先问一句：\n“房产证上写谁？”",
