    "dimension": "law",
    "title": "彩礼——习俗的边界，法律划在哪",
    "frontText": "订婚那天，\n他们家送来了彩礼。\n你爸妈收了。\n\n说：“这是传统。”\n说：“不给彩礼\n就是不重视你。”\n\n你看着那个红包。\n你在想——\n这是重视，\n还是一个价码？\n\n后来你们要离婚了。\n他们家说：\n“把彩礼还回来。”\n你爸妈说：\n“哪有退的道理。”\n\n你夹在中间。\n你成了一个筹码。",
    "quote": "彩礼不是卖身钱。\n也不是离婚时的赎身费。",
    "knowledge": "《民法典》第1042条：\n禁止包办、买卖婚姻\n和其他干涉婚姻自由的行为，\n禁止借婚姻索取财物。\n\n最高人民法院关于审理涉彩礼\n纠纷案件适用法律若干问题的规定\n（2024年2月1日施行）：\n可以请求返还的情形有三种——\n未办理结婚登记；\n已登记但确未共同生活；\n婚前给付并导致给付人生活困难。\n\n已经共同生活的，\n一般不支持返还，\n或者只返还一部分；\n还要看共同生活时间、孕育情况、\n双方过错和彩礼实际使用情况。\n\n🔹 案例：有女性婚后共同生活一段时间\n后提出离婚，男方要求全额返还彩礼；\n法院结合共同生活时间、\n彩礼用途和过错情况作出认定。\n结果因个案而异。",
    "related": "彩礼是习俗。\n但习俗的边界，\n法律已经划清楚了。\n\n它不是“离婚时的赎身费”，\n也不是谁能拿来\n反复要价的东西。\n\n你不需要为了\n“懂事”两个字，\n把自己当成一个\n中间人。",
    "action": "如果你或你身边的人\n正在彩礼这件事里，\n今天记住一条：\n\n把彩礼的使用凭证留好——\n装修、家电、日常开销，\n票据和转账都算。",
    "itchTrigger": "红包收下了，离婚时它变成了一张账单",
    "contradiction": "“不退才是规矩” vs 返还与否有明确的法定情形",
    "verifyTask": "写下彩礼花在哪几件事上，找出对应的凭证。",
    "imaginationPrompt": "如果这笔钱一开始就记在纸上，你还会夹在中间吗？",
    "safetyNote": "彩礼纠纷常伴随家庭矛盾，注意人身安全；具体返还条件和比例由法院结合证据认定，建议咨询律师或12348。",
    "source": "中华人民共和国民法典 / 最高人民法院关于审理涉彩礼纠纷案件适用法律若干问题的规定",
