    "title": "财产约定——把边界提前说清楚",
    "frontText": "你婚前有一套房子。\n你婚后开了一家公司。\n\n有一天，\n他的生意出了问题。\n债权人上门。\n\n他们指着你的房子说：\n“这是夫妻共同财产。”\n指着你的公司说：\n“这个也要拿来抵债。”\n\n你站在自己的房子面前。\n你在想——\n这是我婚前的房子。\n这是我一手创办的公司。\n凭什么？",
    "quote": "你辛苦攒下的，\n不应该替别人还债。",
    "knowledge": "《民法典》第1065条：\n男女双方可以约定\n婚姻关系存续期间所得的财产\n以及婚前财产\n归各自所有、共同所有，\n或者部分各自所有、部分共同所有。\n约定应当采用书面形式。\n\n夫妻约定婚姻关系存续期间\n所得的财产归各自所有的，\n夫或者妻一方对外所负的债务，\n相对人知道该约定的，\n以该方个人财产清偿。\n\n第1064条：\n夫妻共同债务，\n以共同签名、共同意思表示，\n或者用于共同生活、共同生产经营为限。\n\n约定婚前可以签，\n婚后也可以签。\n书面约定、公证，\n证明力更强。",
    "related": "财产约定不是“不信任”。\n是“把边界提前\n说清楚”。\n\n尤其适用于——\n一方创业。\n一方负债。\n再婚家庭。\n继承安排。\n\n你攒下的房子和公司，\n不该因为一张结婚证\n就变成别人的偿债工具。",
    "action": "如果你有婚前财产\n或者自己经营的公司，\n今天先做一件小事：\n\n搜一次\n“财产约定公证 需要什么材料”，\n或者问一次12348。\n\n不用今天去办，\n先知道有这条路。",
