    "frontText": "你怀孕了。\n\n你算了算产检要花多少钱。\n一项一项列下来，\n你有点慌。\n\n你妈说：\n“我们那时候\n哪有这么多检查。”\n同事说：\n“产检很烧钱的，\n做好准备。”\n\n你去了社区\n卫生服务中心。\n护士问你：\n“建卡了吗？”\n\n你才知道，\n怀孕之后\n先要去建档。",
    "quote": "“产检很烧钱”——\n这句话，你核过吗？",
    "knowledge": "国家基本公共卫生服务项目里\n有一项是孕产妇健康管理：\n孕早期、孕中期、孕晚期\n健康管理，\n产后访视，\n产后42天健康检查。\n\n部分地区的免费项目\n包括血常规、尿常规、\n肝肾功能、\n艾滋病与梅毒乙肝筛查等；\n增补叶酸预防神经管缺陷\n也多由社区免费发放。\n\n清单里没有的检查，\n仍然要自费。\n哪些免费、哪些自费，\n以当地的项目清单为准。",
    "related": "你不需要“花冤枉钱”，\n也不需要\n把每一项都当成必须。\n\n你可以问一句：\n“这一项是必须的吗？\n  在免费项目里吗？”\n\n你有权利知道\n每一项检查是为了什么。",
    "action": "如果你怀孕了，\n或者身边有人刚怀上，\n今天做一件小事：\n\n去社区卫生服务中心\n问一句：\n“孕产妇免费检查有哪些？”\n\n只问，不用马上做。",
    "itchTrigger": "账单一列出来就慌，却没人告诉你哪些本来不用自己付",
    "contradiction": "“产检都是自费” vs 基本公共卫生服务里有免费项目",
    "verifyTask": "问一次社区卫生服务中心的免费项目清单，记下三项。",
    "imaginationPrompt": "如果这张清单你早就看过，怀孕那几个月会松一点吗？",
    "safetyNote": "免费项目清单由各地基本公共卫生服务实施方案确定，机构与项目可能不同；有异常症状及时就医，紧急情况拨打120。",
