    "title": "临时庇护——有一个地方可以先住下",
    "frontText": "那天晚上你没有回家。\n\n你从家里出来的时候，\n只拿了手机和身份证。\n你站在楼下，\n不知道去哪里。\n\n你不想让爸妈知道。\n你不想住酒店\n——怕他找到。\n你不想麻烦朋友。\n\n你在手机上\n搜“被打了我能去哪”。\n搜出来一堆\n你不敢点开的东西。",
    "quote": "不是“无路可走”。\n是你还不知道\n路在第几个电话里。",
    "knowledge": "《反家庭暴力法》第18条：\n县级或者设区的市级人民政府\n可以单独或者依托\n救助管理机构\n设立临时庇护场所，\n为家庭暴力受害人\n提供临时生活帮助。\n\n（法条只写“临时生活帮助”，\n具体提供住宿、饮食、\n医疗或心理支持中的哪几项，\n由当地庇护场所安排。）\n\n去哪里问：\n12338 妇联热线\n可以咨询当地庇护信息；\n社区、民政部门也可以问。\n\n能不能入住、能住多久，\n由当地庇护场所\n按规定安排。",
    "related": "“家丑不可外扬”——\n这句话你听过很多次。\n\n但那天晚上\n你需要的不是面子，\n是一张床、\n一扇能锁的门、\n一段没人能找到你的时间。\n\n这些不是“麻烦别人”，\n是被制度安排好的位置。",
    "action": "今天只做一件事：\n把12338 和110\n存进通讯录。\n\n不用打。\n存着就行。\n\n如果你身边有人\n正在危险里，\n把这两个号码\n发给她。",
    "itchTrigger": "你站在楼下，手机里只有一句搜不出来的话",
    "contradiction": "“家丑不可外扬” vs 有临时庇护可以先去",
    "verifyTask": "把12338和110存进通讯录，写下最近的一个妇联或社区电话。",
    "imaginationPrompt": "如果那天晚上你知道有这个地方，你会不会走得更早一点？",
    "safetyNote": "先保证人身安全：有正在发生的危险立即拨打110，伤情及时就医并留下病历。庇护场所的设立、入住条件与期限以当地民政、妇联口径为准；紧急时不要为了取证留在危险现场。",
