    "dimension": "policy",
    "title": "招聘被问婚育——这个问题本来不该问",
    "frontText": "你去面试。\n\n前面聊得都挺好。\n最后面试官\n看了你一眼，\n问：\n“有男朋友吗？”\n“打算什么时候结婚？”\n“要孩子吗？”\n\n你笑了。\n你答了。\n\n回家路上你才想：\n我有没有结婚，\n跟这份工作\n有什么关系？",
    "quote": "那个问题\n本来不该被问出来。",
    "knowledge": "《妇女权益保障法》第43条：\n用人单位在招录（聘）过程中，\n除国家另有规定外，\n不得实施下列行为：\n\n（一）限定为男性\n  或者规定男性优先；\n（二）除个人基本信息外，\n  进一步询问或者调查\n  女性求职者的婚育情况；\n（三）将妊娠测试\n  作为入职体检项目；\n（四）将限制结婚、生育\n  或者婚姻、生育状况\n  作为录用条件。\n\n《就业促进法》第3条：\n劳动者依法享有平等就业的权利，\n不因民族、种族、性别、\n宗教信仰等不同而受歧视。\n\n投诉渠道：\n12333 劳动保障监察、\n当地人社局、\n妇联12338。",
    "related": "你不是“太敏感”。\n是这个问题\n被写进了法律里，\n当成一件不该做的事。\n\n你不需要\n“先找到新工作”\n才能投诉。\n\n你也不需要\n当场翻脸——\n先保存招聘信息、\n把当时的问法记下来，\n就够了。",
    "action": "如果你正在找工作，\n今天做一件小事：\n\n把招聘页面截图保存，\n把被问到的原话\n记在备忘录里。\n\n不是为了马上投诉，\n是为了你以后\n不再只能笑笑。",
    "itchTrigger": "面试聊得挺好，最后那句问的却是你打算什么时候要孩子",
    "contradiction": "“公司也是为你好” vs 招录禁止问婚育",
    "verifyTask": "保存一条招聘信息，把被问到的原话记下来。",
    "imaginationPrompt": "如果每个人都把这句话记下来，它还会不会再被问？",
