    "title": "带孩子不是一个人的事——这条写进了法律",
    "frontText": "孩子的家长会\n又是你去的。\n\n老师问：\n“孩子爸爸呢？”\n你说：\n“他上班。”\n\n家长群里的通知，\n永远发给你。\n填表的“家长签名”栏，\n永远是你。\n\n有一次你加班，\n老师说：\n“那孩子怎么办？”\n\n你愣了一下。\n你在想——\n为什么默认是“我”？",
    "quote": "为什么默认是“我”？",
    "knowledge": "《家庭教育促进法》第十七条：\n家庭教育要\n“亲自养育，加强亲子陪伴”，\n“共同参与，\n发挥父母双方的作用”。\n\n第二十条：\n父母分居或者离异的，\n应当相互配合\n履行家庭教育责任，\n任何一方不得\n拒绝或者怠于履行。\n\n也就是说，\n“带孩子”\n不是母亲一个人的事，\n是父母共同的责任。\n\n你可以：\n把学校通知的\n另一位联系人\n写成他。",
    "related": "“他忙”“他不会”“他不懂”——\n这些理由\n你已经替他找了很久。\n\n法律用的词是\n“共同参与”，\n不是“帮忙”。\n\n帮忙可以拒绝，\n责任不能。",
    "action": "今天做一件很小的事：\n\n把家长群的通知、\n学校的表格，\n改成两个联系人。\n\n或者只跟老师说一句：\n“以后也请他一份。”",
    "itchTrigger": "老师问“孩子爸爸呢”，你脱口而出“他上班”",
