    "frontText": "你在社区群里\n看到有人组织\n“妈妈互助群”。\n\n你想参与。\n你也想过\n自己发起一个。\n\n但你想到：\n场地哪里来？\n谁听我的？\n万一没人来呢？\n\n你把那条消息\n划过去了。",
    "quote": "“我一个人做不了什么”——\n这句话，你验证过吗？",
    "knowledge": "《中国妇女发展纲要（2021—2030年）》\n提出支持女性社会组织发展，\n为妇女参与社会治理\n创造条件。\n\n能接住这类小项目的地方：\n各级妇联——\n支持女性社会组织和女性社群；\n社区社会组织孵化中心——\n提供场地、培训和资源对接；\n部分地方设有\n公益创投或小额资助。\n\n哪些支持能用，\n要问当地妇联和社区。",
    "related": "你不是“没有能力”。\n你是不知道\n可以去找谁。\n\n一个人组织不起来的事，\n往往缺的不是人，\n是一个场地、\n一次培训、\n一笔很小的启动支持。\n\n这些不是“求人”，\n是现成的入口。",
    "action": "如果你有一个\n一直想做的小项目，\n今天只做一件事：\n\n去社区问一句：\n“咱们这儿\n  有社会组织孵化的支持吗？”\n\n或者打12338，\n问妇联有没有\n支持女性社群的项目。",
    "itchTrigger": "你想发起一个群，先想到的是“场地哪里来、谁听我的”",
    "contradiction": "“一个人做不了什么” vs 有场地、培训和资助的入口",
    "verifyTask": "问一次社区或妇联有没有支持女性社群的项目，记下答复。",
    "imaginationPrompt": "如果场地和培训有人替你解决，你会先做哪一件小事？",
    "safetyNote": "各地妇联与社区的支持项目、申请条件不同，以当地口径为准；涉及募资和对外收费的活动，先了解相关管理规定。",
    "source": "中华人民共和国妇女权益保障法 / 妇联组织与12338妇女维权公益服务热线",
