    "title": "这一周，有些钱本来不用你自己出",
    "frontText": "六件本来不用你一个人出的力。\n\n婚前可以先做一次免费体检。\n怀孕之后建档，\n有些检查不用自己掏钱。\n被打的那天晚上，\n有一个地方可以先住下。\n面试被问婚育，\n那个问题本来不该问。\n带孩子不是一个人的事。\n想做点自己的事，\n有人可以申请支持。\n\n你大概已经察觉——\n有些钱、有些力气，\n本来不用你一个人出。",
    "quote": "不是“运气好”。\n是本来就写在制度里。",
    "knowledge": "这一周的六件事：\n\n🧾 免费婚检——多地可做，\n自愿，也可以知道\n🏥 孕产妇健康管理——\n清单内免费，清单外自费\n🏠 临时庇护——\n12338 可以问到哪里住\n💼 招录禁止问婚育——\n12333 可以投诉\n👨‍👧 家庭教育——共同参与，\n不是“帮忙”\n🤝 社会组织支持——\n场地、培训、小额资助",
    "related": "这六件事里，\n有几件你这辈子\n可能都用不上。\n\n没关系。\n\n它们的用处是——\n当你或者身边的人\n遇到的时候，\n你不会以为\n只能自己扛。",
    "action": "把这张卡发给三个人：\n\n在算产检钱的同事，\n被问了婚育的朋友，\n一个人带孩子的邻居。\n\n发完就关掉手机。",
    "itchTrigger": "产检账单、请假扣的工资、被问的那句话，以前都算在你头上",
