    "dow": "周一",
    "dimension": "organization",
    "title": "培训班跑路——钱是预付的服务费",
    "frontText": "你给孩子报了一个培训班。\n交了半年的钱，六千八。\n\n上了三次课。\n第四次去的时候，\n门锁了。\n\n玻璃门上贴了张纸：\n“暂停营业。”\n\n你站在门口。\n你看了看手机里的家长群。\n群里炸了。\n有人说“刚交了一万”。\n有人说“老板跑了”。\n有人说“算了，就当买个教训”。\n\n你站在那里。\n你想：\n“我也要‘算了’吗？”",
    "quote": "“买教训”——\n这个教训，\n为什么要你花钱？",
    "knowledge": "校外培训机构归教育局管，\n预收费也有监管要求：\n学科类培训机构\n不得一次性收取\n超过3个月或者60 课时的费用。\n（具体适用范围和标准\n以当地现行规定为准。）\n\n机构跑路，可以走三条线：\n向教育局投诉；\n向市场监管部门投诉；\n向法院起诉。\n\n12345 也可以打，\n它会把工单转给主管部门。",
    "related": "你不是“只能算了”。\n\n你交的钱，\n不是“买教训”，\n是预付的服务费。\n服务没了，\n钱就该退。\n\n你要做的不是吵架，\n是把缴费记录、\n合同、聊天记录\n先截下来——\n投诉要用证据说话。",
    "action": "今天做一件小事：\n把缴费记录和合同截图，\n存进一个文件夹。\n\n如果身边有家长\n正在经历同样的事，\n告诉她：\n“别只在群里骂，\n  去12345 或者教育局。”",
    "itchTrigger": "你站在锁着的玻璃门前，群里有人说“就当买个教训”",
    "contradiction": "“花钱买教训” vs 预付费是服务合同，钱该退",
    "verifyTask": "把缴费记录和合同截图存好，写下投诉要用的那三个信息。",
    "imaginationPrompt": "如果先去投诉而不是先在群里骂，结果会不一样吗？",
    "safetyNote": "退费能否实现取决于机构资产和个案处理，本卡不承诺结果；集体维权的家长可以推选代表，保留统一口径的证据清单。",
    "source": "中华人民共和国消费者权益保护法 / 校外培训机构预收费监管相关规定 / 中华人民共和国民法典",
