    "title": "物业费涨价——不是物业说涨就能涨",
    "frontText": "你住的小区物业费涨了。\n从两块涨到三块。\n\n物业说：“成本涨了。”\n\n你看了看小区的卫生。\n垃圾没人收。\n路灯坏了不修。\n保安天天在岗亭里刷手机。\n\n你觉得这钱花得不值。\n你想投诉。\n你不知道找谁。\n\n你想“算了，\n反正也改变不了”。",
    "quote": "“算了”——\n你每个月多交的那笔钱，\n就这么算了？",
    "knowledge": "《民法典》第278条：\n下列事项由业主共同决定——\n制定和修改业主大会议事规则；\n制定和修改管理规约；\n选举或者更换业主委员会成员；\n选聘和解聘物业服务企业；\n使用和筹集维修资金；\n改建、重建建筑物及附属设施；\n改变共有部分的用途等。\n\n物业费标准的调整，\n通常属于需要业主共同决定\n或者按合同约定的范围。\n没经过该走的程序，\n物业不能自己说涨就涨。",
    "related": "你不需要成为\n物业问题的专家。\n\n你只需要问三句话：\n这次涨价\n有没有经过业主大会\n或者业主共同决定？\n有没有书面公示？\n服务标准变了吗？\n\n问不出来，\n就把问题交给主管部门。",
