    "title": "延期交房——“不可抗力”不是万能挡箭牌",
    "frontText": "你买了一套新房。\n开发商延期交房半年。\n\n你租着房子等。\n你每个月交房租。\n你每个月还房贷。\n\n你去问开发商。\n开发商说：\n“疫情影响，不可抗力。”\n\n你想要违约金。\n你不知道怎么要。\n你不知道合同里写了什么。\n你不知道去哪里投诉。",
    "quote": "“不可抗力”——\n这四个字，\n可以一直用吗？",
    "knowledge": "《民法典》第577条：\n一方不履行合同义务\n或者履行不符合约定的，\n应当承担继续履行、\n采取补救措施\n或者赔偿损失等违约责任。\n\n第585条：\n约定的违约金\n低于造成的损失的，\n可以请求增加；\n过分高于造成的损失的，\n可以请求适当减少。\n\n不可抗力确实可以部分或者\n全部免除责任，\n但需要证明\n它和延期之间有因果关系，\n而且通常要及时通知对方。\n\n购房合同里一般\n都写了延期交房的违约金标准，\n先把它找出来。",
    "related": "你不需要懂工程，\n也不需要懂不可抗力\n的全部理论。\n\n你只需要做两件事：\n找到合同里那一行\n“延期交房”的约定；\n问一句\n“延期的时间\n  和影响之间\n  是什么关系？”\n\n问不出来的部分，\n交给住建部门或者法院。",
    "action": "如果这件事发生\n在你或亲友身上，\n今天做一件小事：\n\n把购房合同里\n关于交房日期\n和违约金的条款\n拍下来存好。\n\n然后打12345，\n问一句该找哪个部门。",
    "itchTrigger": "房租和房贷同时在扣，“不可抗力”四个字挡在前面",
    "contradiction": "“不可抗力就能免责” vs 违约要看约定与因果关系",
    "verifyTask": "拍下合同里的交房日期与违约金条款，写下缺失的那一项。",
    "imaginationPrompt": "如果合同那一页你早看过，这半年你会不会少等一点？",
    "safetyNote": "不可抗力是否成立、违约金如何调整由法院依个案认定；联合其他业主维权时保留各自的合同与付款凭证。",
