    "title": "预付卡遇上“店转让”——你的权利跟着店走",
    "frontText": "你在美容院办了一张卡。\n三千。\n做了两次脸。\n\n第三次去的时候，\n门关着。\n\n你打电话给老板。\n老板说：\n“店转让了，\n你找新老板。”\n\n你找新老板。\n新老板说：\n“你的卡不是在我这办的。”\n\n你站在门口，\n看着那张卡。\n你想：\n“三千块就这么没了？”",
    "quote": "“店转让了”——\n你的卡就没人管了吗？",
