    "related": "你不是“认栽”。\n\n你手里那张卡，\n是一份已经付过钱的合同。\n\n换老板、换店名，\n都不会让它\n凭空消失。\n\n你要做的第一件事\n不是生气，\n是把付款记录找出来。",
    "action": "如果你家里\n有在用的预付卡，\n今天做一件小事：\n\n翻出付款记录和卡，\n拍一张照存好。\n\n顺便看一眼余额——\n你自己记的账，\n比店里的系统\n更靠得住。",
