    "title": "买到假货——一百多块也可以主张",
    "frontText": "你在网上买了一个东西。\n收到之后发现是假货。\n\n你申请退货。\n卖家说：\n“你拆了包装，不能退。”\n\n你说：\n“不拆怎么知道是假货？”\n\n卖家说：\n“那是你的问题。”\n\n你找平台。\n平台说：\n“我们只能协调。”\n\n你看着那个假货。\n你想：\n“算了，就一百多块钱。”",
