    "title": "这一周，这些事都有一个窗口可以敲",
    "frontText": "六件烦心事，各有各的窗口。\n\n培训班跑路了。\n物业费自己涨了。\n楼上漏水不认。\n开发商延期交房。\n美容院办了卡就关门。\n网购买到假货。\n\n再想一层——\n这些事都不是“只能算了”，\n它们各自有一个\n可以敲的窗口。",
    "quote": "不是没有门，\n是还没有人\n把门牌号告诉你。",
    "knowledge": "这一周的六个窗口：\n\n🏫 培训机构——教育局，\n预收费有监管标准\n🏢 物业费——住建部门，\n涨价要走程序\n💧 楼上漏水——物业协调、\n社区调解、法院起诉\n🏗️ 延期交房——住建部门，\n合同里有违约金条款\n💳 预付卡——12315，\n市场监管部门\n🛒 假货——12315，\n欺诈可以主张三倍赔偿",
    "related": "这一周你最容易记住的\n其实不是条文，\n是顺序：\n\n先留证据，\n再找对窗口，\n一次不行就再问一次。\n\n金额不大、事情不大，\n都不构成\n你应该把它咽下去。",
    "action": "写一行：\n“这件事该找______。”\n\n把这一周里\n你最可能遇到的那一件\n填进去。\n\n再把这张卡\n留在家长群里——\n那个说\n“就当买个教训”的人，\n会看见。",
    "itchTrigger": "六件事你都遇过，以前都以为只能自己扛",
    "contradiction": "“算了” vs 每件事都有主管部门",
    "verifyTask": "写下你最近这件烦心事该找的那个窗口。",
    "imaginationPrompt": "如果把“找谁”写下来贴在家里，你会先解决哪一件？",
    "safetyNote": "本卡为制度认知科普，不构成法律意见；投诉、调解、诉讼的受理与结果由主管部门和法院依法认定。",
