    "frontText": "你去社区服务中心交材料。\n\n上二楼的时候，\n你看见走廊尽头一扇门上贴着：\n“妇女之家”。\n\n里面有人说话，有人笑。\n有张桌子上摊着图片和手工。\n\n你在门口站了两秒。\n你心里想的是——\n“那是给闲人准备的吧。”\n\n然后你下楼了。",
