    "frontText": "你跟朋友吃饭，\n想提一句今天打电话的事。\n\n话到嘴边，变成：\n“今天我去了趟社区。”\n\n她问：“干什么？”\n\n你说：“没什么，就问问事。”\n\n你发现自己\n把“我去了妇女之家”\n这句话咽了回去。",
