    "knowledge": "有些地方带着标签，\n说出口会引出评价。\n\n一个处理办法是：\n只说你带走的东西，\n不说你去的地方。\n\n“我问到了托育的事”——\n这就够了。",
    "related": "你不需要替这个场地辩护，\n也不需要把它藏起来。\n\n你只需要决定：\n这件事，对谁说、说多少。",
    "action": "把“我去了哪儿”换成\n“我问到了什么”，\n对着镜子说一遍。",
    "itchTrigger": "话到嘴边，你把“我去了妇女之家”咽了回去",
