    "day": 192,
    "week": 28,
    "dow": "周三",
    "dimension": "action",
    "title": "算账：三张清单",
    "frontText": "谈钱最难。\n\n你说“不公平”，\n他说“我出的也多”。\n\n两个人\n各说各的，\n越说越气。\n\n因为你们\n看的是\n不同的账。",
    "quote": "“不公平”\n吵一百遍，\n不如\n把三张清单\n摆在一起。",
    "knowledge": "三张清单：\n\n① 钱的清单——\n  收入、支出、\n  房贷、存款、债务，\n  各自多少；\n② 时间的清单——\n  接送、做饭、\n  辅导、陪护，\n  各花多少小时；\n③ 机会成本的清单——\n  谁为了这个家\n  少上了班、\n  推了机会、\n  停了社保。\n\n第三张\n最常被漏掉，\n也最难用嘴说清。\n\n写下来，\n它们就\n可以被讨论。\n\n（家务劳动的价值\n在离婚补偿时\n有法律依据，\n见第18天。）",
