    "frontText": "她读过的书，\n最后变成了一份工。\n\n1910年代前后，\n女教员、女护士、女接线员\n开始出现在城市里。\n\n她们要起得很早，\n走很远的路，\n在别人家的堂屋、\n医院的病房、\n电话局的机台前\n待上一整天。\n\n那是她们第一次\n用自己的时间\n换到钱。",
