    "frontText": "1953年，\n新中国第一部选举法施行。\n\n1954年，宪法公布，\n里面写着：\n\n妇女在政治的、\n经济的、文化的、\n社会的和家庭的\n生活各方面，\n享有同男子平等的权利。\n\n门不是突然开的。\n它先被写在纸上，\n再被一扇一扇推开。",
    "quote": "写在纸上不等于\n明天就能走进去，\n但没写下来，\n永远推不开。",
    "knowledge": "1953年《选举法》施行，\n明确男女有平等的\n选举权和被选举权。\n\n1954年《宪法》规定，\n妇女在政治的、经济的、\n文化的、社会的\n和家庭的生活各方面，\n享有同男子平等的权利。\n\n今天，\n《妇女权益保障法》\n第十三条写着：\n妇女有权通过各种途径和形式，\n依法参与管理国家事务、\n管理经济和文化事业、\n管理社会事务。\n\n从“允许出门”\n到“有权参与”，\n中间隔着这一步。",
    "related": "你嘴里那句“我算老几”，\n是从哪里学来的？\n\n反正不是从法律上。\n\n法律上的写法\n一直是\n“享有同男子平等的权利”。\n\n差的那一段，\n不在纸上，\n在没人告诉过你。",
