    "frontText": "你在谈离婚。\n\n他说：\n“养老金是我的，\n 跟你没关系。”\n\n你想：\n这些年\n家里的开销\n大多是我出的，\n他每个月\n交的那部分社保，\n难道\n跟我一点关系也没有？",
