    "reviewNote": "2026-10-11 第31周按作者新稿归位（原稿标第二十周）：补消法第25条例外情形与运费承担规则；未终审。",
    "carryIn": "你知道了签收不是终点；衣柜里那件没退的衣服还挂着。",
