    "dow": "周四",
    "dimension": "law",
    "title": "亲戚借钱没打借条——转账记录也算证据",
    "frontText": "你亲戚找你借钱。\n他说：“急用，\n一个月就还。”\n\n你借了。两万。\n没打借条。\n\n因为你不好意思。\n你觉得\n“亲戚之间，\n打借条太见外”。\n\n一个月过去了。\n两个月过去了。\n半年过去了。\n\n你问他。\n他说：\n“哎呀，最近手头紧，\n再等等。”\n你再问。\n他说：\n“你又不缺这点钱。”",
    "quote": "“亲戚之间”——\n这三个字，\n成了他不还钱的理由。",
    "knowledge": "《民法典》第667条：\n借款合同是借款人\n向贷款人借款，\n到期返还借款\n并支付利息的合同。\n\n第679条：\n自然人之间的借款合同，\n自贷款人提供借款时成立。\n\n没有借条，\n不等于没有证据：\n转账记录、\n微信或短信里\n关于“借”“还”的对话，\n都可以作为证据。\n\n但要注意：\n主张还款有诉讼时效，\n一般是三年，\n从约定的还款期限届满\n或者你催告后\n对方仍不还时起算。",
    "related": "“打借条太见外”——\n这句话\n在借钱的那一刻\n很温暖，\n在要不回来的时候\n很贵。\n\n以后借钱，\n你可以写一句：\n“几月几号，\n  借多少，\n  什么时候还。”\n\n这不是不信任，\n是让关系\n少一个坏掉的借口。",
    "action": "如果你有笔\n一直没要回来的钱，\n今天做一件小事：\n\n把转账记录找出来，\n把聊天里\n提到“借”“还”的对话\n截图存好。\n\n先存，\n不一定要现在撕破脸。",
    "itchTrigger": "“你又不缺这点钱”——借出去的钱成了不能提的事",
    "contradiction": "“亲戚之间不用写” vs 转账记录也是证据",
    "verifyTask": "找出那笔转账记录，写下借款日期和金额。",
    "imaginationPrompt": "如果当时多写那一行字，今天开口会容易多少？",
    "safetyNote": "是否超过诉讼时效、证据能否被采纳由法院依个案认定；大额借贷建议保留书面借条并注明还款日期，必要时咨询12348。",
