    "dimension": "law",
    "title": "“合同里没写”——看不懂就是他说了算？",
    "frontText": "你装修房子。\n\n你找了一家装修公司。\n签了合同。交了首付。\n\n开工后，工长说：\n“这个项目合同里没写，\n要加钱。”\n\n你说：“合同里写了啊。”\n他说：\n“合同里写的是基础款，\n你要的是升级款。”\n\n你看着合同。\n你看不懂。\n你不知道\n“基础款”和“升级款”\n差在哪里。\n\n你怕停工。\n你怕耽误时间。\n\n你加了钱。",
    "quote": "“合同里没写”——\n你看不懂合同，\n就是他说了算吗？",
    "knowledge": "《民法典》第470条：\n合同的内容由当事人约定，\n一般包括\n当事人的姓名或者名称和住所、\n标的、数量、质量、\n价款或者报酬、\n履行期限、地点和方式、\n违约责任、\n解决争议的方法等条款。\n\n第543条：\n当事人协商一致，\n可以变更合同。\n\n也就是说：\n加钱属于变更合同，\n要双方同意，\n不是工长一句话。\n\n你可以要求：\n“请把这一项\n  写清楚：\n  做什么、多少钱、\n  按什么标准验收。”",
    "related": "看不懂合同\n不丢人。\n\n丢人的是\n“看不懂就签字”。\n\n你可以只做一件事：\n在签字之前，\n让对方把每一项\n“做什么、多少钱”\n写成一张清单。\n\n写得出来的，\n才是合同。",
    "action": "如果你正在装修、\n或者准备签一份\n自己看不懂的合同，\n今天做一件小事：\n\n把看不懂的那几行\n圈出来，\n发消息问一句：\n“这一条是什么意思？\n  请写清楚一点。”",
    "itchTrigger": "工长一句“合同里没写”，你怕停工就加了钱",
    "contradiction": "“看不懂就认了” vs 加价要双方协商一致",
    "verifyTask": "圈出合同里你最看不懂的那一行，写下要问的问题。",
