    "title": "“今天最后一天”——这是一句话术",
    "frontText": "你去做美容。\n\n美容师说：\n“你这个斑，\n我们有个项目\n效果特别好。”\n\n你说：“多少钱？”\n她说：“今天活动价，\n只要3980。”\n\n你说：“太贵了。”\n她说：“你可以办分期。”\n你说：“我不想办。”\n她说：\n“那你先体验一次，\n体验价398。”\n\n你躺下了。\n她给你做了半张脸。\n然后她说：\n“你看，这边效果多好。\n另一边不做就不对称了。”\n\n她说：\n“今天最后一天活动，\n明天就恢复原价了。”\n\n你刷了卡。",
    "quote": "“最后一天活动”——\n今天是最后一天，\n明天也是。",
    "knowledge": "《消费者权益保护法》：\n消费者享有\n自主选择商品或者服务的权利\n和公平交易的权利。\n\n《明码标价和禁止价格欺诈规定》：\n虚构原价、虚假折扣、\n谎称“最后一天”“马上涨价”\n等，\n属于法律禁止的价格欺诈行为。\n\n也就是说：\n“最后一天”\n不是催你的理由，\n而是一句\n可以被投诉的话术。\n\n你可以：\n说“我今天不办”，\n然后离开；\n把宣传页和报价拍下来。",
    "related": "你不需要\n在别人的“最后一天”里\n做决定。\n\n你只需要记住一句话：\n“我今天不办，\n  我考虑一下。”\n\n这句话不用解释，\n也不用道歉。\n\n真正的活动，\n不会只给你三分钟。",
    "action": "今天做一件小事：\n\n把这一句\n写进备忘录：\n\n“我今天不办，\n  我考虑一下。”\n\n下次被人催的时候，\n直接念出来。",
