    "dimension": "law",
    "title": "这一周，那些“算了”的事都有一条规则",
    "frontText": "六件“小事”，背后都有一条规则。\n\n事故现场有人说“就是你追尾”。\n快递显示签收，文件不见了。\n网购色差大，运费比衣服贵。\n亲戚借钱没打借条。\n装修公司说“合同里没写”。\n美容院说“今天最后一天”。\n\n往前一步看——\n这些事看起来都是\n“只能算了”，\n其实每一件\n背后都有一条规则。",
    "quote": "不是“你太好说话”，\n是没有人\n把规则念给你听过。",
    "knowledge": "这一周的六条规则：\n\n🚗 交通事故——\n先报警，责任由事故认定书认定，\n不服三日内申请复核\n📦 快递丢失——\n12305 申诉，\n保价才是赔偿依据\n🛍️ 七天无理由——\n不需要理由，\n但要注意例外和运费\n🧾 借钱——\n转账记录也是证据，\n但有三年诉讼时效\n📝 合同变更——\n加钱要双方同意\n💄 价格欺诈——\n“最后一天”\n是可以投诉的话术",
    "related": "这一周最该记住的\n其实是顺序：\n\n先留凭证，\n再说“不”，\n最后才是投诉和起诉。\n\n钱不多、事也不大，\n但都不该由你\n你应该把它咽下去。",
    "action": "这句话，写下来：\n\n“下次遇到这件事，\n  我先存______。”\n\n把这周里\n你最可能再遇到的一件\n填进去。\n\n存好之后\n在群文件里放一份——\n那个说“就当买教训”的人\n也在那个群。",
    "itchTrigger": "六件事你都遇过，以前每一件都算了",
