    "title": "“推荐过去”不等于“录用了”",
    "frontText": "窗口给你推荐了三家。\n\n你跑了两家。\n\n第一家说\n“这个岗位\n  上周就满了”。\n第二家说\n“我们在等\n  总部批编制”。\n\n你有点泄气。\n\n推荐和录用之间，\n还隔着\n一道门，\n门不在你这边。",
    "quote": "推荐是把门推开一条缝，\n进去还要\n对面点头。",
    "knowledge": "公共就业服务\n和职业中介\n做的是同一类事里的不同部分：\n\n它们对接的是\n岗位信息和供求匹配，\n不是替你录用。\n\n而中介这一头，\n法律划了红线。\n\n《就业促进法》第四十一条：\n职业中介机构不得\n提供虚假就业信息、\n为无合法证照的用人单位\n提供职业中介服务、\n伪造涂改转让职业中介许可证、\n扣押劳动者的居民身份证\n和其他证件，\n或者向劳动者收取押金。\n\n所以\n“先交押金”\n“身份证放我们这儿”\n这两句一出来，\n这件事\n就不对。",
    "related": "“跑了两家都黄了”——\n这不代表\n这件事走不通。\n\n它只说明\n推荐是匹配，\n录用是对面的决定。\n\n你要盯的\n是匹配有没有在做，\n而不是\n每次都猜自己的错。",
    "action": "今天做一件小事：\n\n记住两句话，\n下次一听到\n就可以停下：\n\n“先交押金。”\n“身份证\n  先放我们这儿。”",
    "itchTrigger": "“我们这边先收个押金”——这句话本身就是警报",
    "contradiction": "“先交钱才好办事” vs 法律明令禁止收押金、扣证件",
    "verifyTask": "写下职业中介机构不得做的两件事。",
    "imaginationPrompt": "如果这两句话人人都知道，有多少人不会走那一段弯路？",
    "safetyNote": "本卡为政策认知科普；遇到扣押证件、收取押金等情况可向人社部门反映，注意保存聊天与收据。",
