    "title": "同一张工牌，不同的合同",
    "frontText": "同一个前台。\n\n有人拿的是\n正式合同；\n有人签的是\n“劳务派遣”；\n有人是\n“非全日制”。\n\n工牌一样，\n制服一样，\n早会一起开。\n\n但加班怎么算、\n能不能随时走、\n出了事谁负责——\n三张纸\n写的是三件事。",
    "quote": "看上去是同一种工作，\n纸面上是三种关系。",
    "knowledge": "《劳动合同法》第六十八条：\n\n非全日制用工，\n指以小时计酬为主，\n劳动者在同一用人单位\n一般平均每日工作时间\n不超过四小时，\n每周工作时间累计\n不超过二十四小时的\n用工形式。\n\n第七十二条：\n非全日制用工小时计酬标准\n不得低于用人单位所在地\n人民政府规定的\n最低小时工资标准；\n劳动报酬结算支付周期\n最长不得超过十五日。\n\n用工形式\n直接决定\n你能主张什么。",
    "related": "你以前\n只看工资数，\n不看那一栏\n“用工形式”。\n\n现在你知道\n那一栏\n决定了\n加班费怎么算、\n社保怎么交、\n离开的时候\n有没有补偿。\n\n签字之前\n先看它。",
