    "frontText": "窗口的人\n问你一句：\n\n“你之前\n  有没有申请过\n  就业困难人员认定？”\n\n你说没有。\n\n她说：\n“那先办这个。”\n\n你没听懂\n这两个字\n有什么分量。\n\n后来才知道，\n它是一个\n写在法律里的\n入口。",
