    "title": "公告栏上并排贴着三张纸",
    "frontText": "你在小区门口\n等外卖。\n\n公告栏上\n并排贴着三张纸：\n\n一张养老服务的，\n一张托育的，\n一张临时救助的。\n\n三张纸都写着\n“详情请咨询\n  社区服务中心”。\n\n你看了两分钟，\n没记住\n任何一串电话。",
    "quote": "纸贴在那儿，\n不等于\n你能用上。",
    "knowledge": "社区公告栏\n通常不是一份文件，\n而是三四种不同的东西：\n\n有的是\n社区自己办的服务；\n有的是\n上级部门放下来\n由社区转达的；\n有的只是\n“有问题去问谁”的提示。\n\n《城市居民委员会组织法》\n第十条\n把居民委员会的职责\n列了九项，\n其中包括：\n\n· 办理本社区居民的\n  公共事务和公益事业，\n  开展便民利民的社区服务活动，\n  关心关爱老年人、儿童、\n  残疾人和困难居民；\n· 调解民间纠纷；\n· 协助维护社会治安，\n  协助处理信访事项，\n  协调化解矛盾纠纷；\n· 向人民政府或者街道办事处\n  反映居民的意见和要求。",
    "related": "你以前\n把社区\n当成一个\n“有事就去问”的地方。\n\n现在你知道\n它是一份\n有清单的职责：\n\n哪几件事它自己办，\n哪几件事它只能帮着转。\n\n分清这两类，\n你就不会\n白跑。",
