    "title": "上门登记的那张表",
    "frontText": "社区的人\n来敲门。\n\n拿着一台手机，\n说：\n“登记一下，\n  常住人口。”\n\n你报了姓名、\n身份证号、\n电话、\n家里几口人。\n\n她走后\n你才想起来：\n\n这些信息\n给谁看？\n存到哪儿？\n\n你没问。",
    "quote": "登记是正常的事，\n问一句\n也是正常的事。",
    "knowledge": "《个人信息保护法》第六条：\n\n处理个人信息\n应当具有\n明确、合理的目的，\n并应当与处理目的\n直接相关，\n采取对个人权益\n影响最小的方式。\n\n收集个人信息，\n应当限于\n实现处理目的的\n最小范围，\n不得过度收集个人信息。\n\n所以“登记常住人口”\n和“顺便问问\n你家里有没有人生病”\n不是同一件事。\n\n你可以问一句：\n\n“这一项\n  是用来做什么的？”",
    "related": "你怕的是\n被当成\n“不配合的那个”。\n\n问一句用途\n不是不配合。\n\n法律写的是\n最小范围，\n问清楚\n刚好帮着\n把范围\n框回最小。",
    "action": "今天做一件小事：\n\n记住一句话，\n下次登记时可以说：\n\n“这一项\n  是用来做什么的？”",
