    "frontText": "你把那部法律\n找出来看。\n\n第十条，九项职责，\n一条一条读过去。\n\n读到后面几项\n你停住了：\n\n“协助人民政府\n  或者街道办事处\n  做好与居民利益有关的\n  其他工作”；\n\n“向人民政府\n  或者街道办事处\n  反映居民的意见、要求\n  和提出建议”。\n\n原来\n“反映”这件事\n写在这儿。",
    "quote": "你以为是“麻烦别人”，\n法律里\n写着“反映意见”。",
