    "frontText": "这一周，\n你把“有事找社区”\n这句话，\n拆成了几块：\n\n它自己办的；\n它只能协助的；\n它负责反映的；\n它必须问你用途的。\n\n拆开以后\n你再出门，\n包里\n多了一个文件袋，\n嘴上\n多了一句\n“那我该找谁”。",
