    "frontText": "你在整理家里的旧文件。\n\n抽屉最底下\n压着一张发黄的房契。\n\n上面一个名字\n被一团墨盖住了，\n只留一个姓，\n勉强看得清。\n\n你妈看了一眼，说：\n“以前都这样，\n  女人的名字\n  不上这种纸。”",
