    "frontText": "你们想办一场\n社区亲子运动会。\n\n报名的人\n越来越多，\n群里有人说：\n“这么多人，\n 要不要报批？\n 万一出事谁负责？”\n\n这句话\n让组织者\n一晚上没睡好。",
