    "frontText": "你在新闻里\n看到有人上街。\n\n你想到\n宪法第35条里\n那三个词：\n\n集会、游行、示威。\n\n你以为\n那是\n“别人国家的事”。\n\n其实\n这三个词\n也写在\n我们的宪法里。",
