    "dow": "周一",
    "dimension": "law",
    "title": "外卖里吃出异物——一份差评不够",
    "frontText": "你点了一份外卖。\n饿了。\n\n你打开盒子。\n你吃了一口。\n\n然后你看到了\n一个不该看到的东西。\n\n你放下筷子。\n你胃里翻了一下。\n\n你拿起手机。\n你拍了照。\n你打开客服对话框。\n\n但你又想：\n“算了，\n也没吃进去。\n给个差评就行了。”\n\n你关掉了对话框。\n你给了一个差评。\n然后你继续饿着。",
    "quote": "你留下的那个差评，\n下一份外卖还会照旧。",
    "knowledge": "《食品安全法》第148条：\n消费者因不符合\n食品安全标准的食品\n受到损害的，\n可以要求赔偿损失，\n并可以向生产者或者经营者\n要求支付\n价款十倍或者损失三倍的\n赔偿金；\n增加赔偿的金额\n不足一千元的，为一千元。\n\n例外是：\n食品的标签、说明书\n存在不影响食品安全、\n也不会误导消费者的瑕疵。\n\n也就是说：\n吃到异物，\n可以主张的赔偿起点\n是一千元。\n\n投诉渠道：\n12315、外卖平台正式投诉。",
    "related": "给差评是发泄，\n不是维权。\n\n差评只影响它的评分，\n投诉才进入它的记录。\n\n你不需要为了\n一顿二十块的外卖\n打一场官司，\n但你可以花三分钟\n把照片和订单\n一起提交上去。",
    "action": "今天做一件小事：\n\n把这条记住：\n“吃到异物，\n  赔偿起点一千元。”\n\n下一次不用吵架，\n拍好照、\n直接走平台投诉\n或者12315。",
    "itchTrigger": "“也没吃进去，给个差评就行”——你就这样放过了",
    "contradiction": "“给差评就算了” vs 食安法有惩罚性赔偿",
