    "frontText": "你入职了一家新公司。\n试用期三个月。\n\n你干得很好。\n没人说你不行。\n\n第三个月快结束时，\n领导叫你进去。\n说：\n“试用期不合格，\n你明天不用来了。”\n\n你问：“哪里不合格？”\n他说：\n“不合适就是不合适。”\n\n你收拾东西。\n你走出大楼。\n\n你想起你为了这份工作\n放弃了另外两个 offer。",
    "quote": "“试用期不合格”——\n这句话，\n就可以随便说吗？",
    "knowledge": "《劳动合同法》第21条：\n在试用期中，\n除劳动者有第39条\n和第40条第1项、第2项\n规定的情形外，\n用人单位不得解除劳动合同；\n在试用期解除劳动合同的，\n应当向劳动者说明理由。\n\n第39条第一项：\n在试用期间\n被证明不符合录用条件的。\n\n关键词是\n“被证明”和“说明理由”——\n不是一句“不合适”。\n\n公司要拿得出\n录用条件和考核记录。\n\n有争议可以申请劳动仲裁。",
