    "title": "退租扣押金——正常磨损不该算在你头上",
    "frontText": "你退租了。\n\n房子打扫得干干净净。\n你拍了照。\n你把钥匙交给了房东。\n\n房东说：\n“行，押金过两天退你。”\n\n两天过去了。\n一周过去了。\n两周过去了。\n\n你问房东。\n他说：\n“墙上有个钉子眼，要扣200。”\n“地板有划痕，要扣500。”\n“窗帘有点旧了，要扣300。”\n\n你算了算。\n押金两千。\n他能扣掉一千。",
    "quote": "“正常使用痕迹”——\n什么时候\n变成了扣钱的理由？",
    "knowledge": "《民法典》第710条：\n承租人按照约定的方法\n或者根据租赁物的性质\n使用租赁物，\n致使租赁物受到损耗的，\n不承担赔偿责任。\n\n第733条：\n租赁期限届满，\n承租人应当返还租赁物；\n返还的租赁物\n应当符合按照约定\n或者根据租赁物的性质\n使用后的状态。\n\n也就是说：\n正常居住造成的磨损\n不是扣押金的理由；\n只有超出正常使用的损坏\n才可能要赔。\n\n入住和退租\n各拍一次视频，\n是最省事的证据。",
    "related": "“那你扣吧”——\n这句话你说过，\n因为你怕麻烦。\n\n但押金不是他的，\n是你先放在他那里的。\n\n你可以平静地说：\n“这几处是正常使用痕迹。\n  有超出正常使用的，\n  请给维修单据。”",
    "action": "今天做一件小事：\n\n正在租房子的话，\n现在拍一段视频：\n墙面、地板、家电、\n水表电表。\n\n存进一个文件夹，\n名字写日期。\n\n退租那天再拍一次。",
    "itchTrigger": "钉子眼、划痕、旧窗帘，两千押金被扣掉一半",
