    "title": "楼上噪音——把时间记下来，比吵架管用",
    "frontText": "你楼上邻居\n每天晚上十一点开始拖椅子。\n\n吱——吱——吱——\n\n你刚睡着。\n你被吵醒。\n你翻来覆去。\n第二天你顶着黑眼圈上班。\n\n你上楼敲门。\n他说：\n“我在我家拖椅子，\n关你什么事？”\n\n你找物业。\n物业说：“我们只能提醒。”\n\n你报警。\n警察来了。\n他说：“我以后注意。”\n\n第二天晚上，又开始拖。",
    "quote": "“关你什么事”——\n你的睡眠，\n和他拖椅子，有关。",
    "knowledge": "《民法典》第288条：\n不动产的相邻权利人\n应当按照\n有利生产、方便生活、\n团结互助、公平合理的原则，\n正确处理相邻关系。\n\n《治安管理处罚法》第八十八条：\n社会生活噪声\n经基层组织、业委会、\n物业和有关部门\n劝阻、调解、处理\n仍不停止，\n继续干扰他人\n正常生活、工作和学习的，\n可以处拘留或者罚款。\n\n你要做的第一件事\n不是理论，\n是记录：\n每天几点开始、\n持续多久、\n你录到的声音。\n\n时间、次数和录音\n比“他太吵了”有用得多。",
    "related": "“我在我家拖椅子”——\n这句话听起来有理，\n但它少了一句：\n“前提是不影响别人。”\n\n你不需要\n跟邻居变成仇人。\n\n你只需要\n把这件事\n从“生气”\n变成“有记录”。",
    "action": "今天做一件小事：\n\n准备一个备忘录，\n从今晚开始记：\n日期、开始时间、结束时间。\n\n能录就录30秒。\n\n连着记一周，\n再去找物业、社区\n或者报警。",
