    "frontText": "你接到一个电话。\n\n对方说：\n“我是 XX 银行的，\n你有一张信用卡逾期了。”\n\n你说：\n“我没有你们银行的卡。”\n对方说：\n“那可能是别人\n冒用了你的身份。”\n\n你说：“那怎么办？”\n对方说：\n“你把身份证号和\n银行卡号报一下，\n我帮你查。”\n\n你正要报。\n你突然觉得哪里不对。",
    "quote": "“我是XX银行的”——\n这句话，\n就是真的吗？",
    "knowledge": "记住三条：\n\n① 银行、公安、医保\n不会在电话里\n让你报验证码、\n密码、完整的银行卡号；\n② 不存在\n“安全账户”“资金核查账户”；\n③ 有疑问，\n自己挂掉，\n拨银行卡背面的官方客服号\n或者96110 咨询。\n\n《个人信息保护法》：\n处理个人信息\n应当取得个人同意；\n《反电信网络诈骗法》：\n任何单位和个人\n不得为诈骗提供帮助。\n\n已经报出去信息或转了钱，\n立即打110\n并联系银行止付。",
    "related": "“他连我逾期都知道”——\n信息被泄露\n不是他可信的理由。\n\n你要做的事只有一件：\n挂掉，\n自己拨官方号码。\n\n真的银行\n不会怕你挂电话。",
    "action": "今天做一件小事：\n\n把96110\n存进通讯录。\n\n再跟家里人约定一句：\n“谁在电话里\n  要验证码，\n  就先挂掉，\n  再打给我们。”",
    "itchTrigger": "对方连你逾期都能说出来，你差点把身份证号报出去",
    "contradiction": "“他知道我的信息所以是真的” vs 官方不会电话索要信息",
    "verifyTask": "把96110存进通讯录，写下你和家人的那句约定。",
    "imaginationPrompt": "如果家里老人接到这个电话，你希望他先想起哪一句？",
    "safetyNote": "任何索要验证码、要求转账到“安全账户”的都是诈骗；已转账立即拨打110并联系银行止付，同时保留通话与转账记录。",
