    "frontText": "你带孩子去游乐场。\n\n孩子玩滑梯时摔了下来。\n手臂肿了。\n\n你带他去医院。\n拍了片子。骨折。\n\n你回到游乐场。\n你说：\n“你们的滑梯有安全隐患。”\n\n经理说：\n“我们贴了\n‘家长须看护’的告示。”\n\n你说：\n“贴了告示就不管了吗？”\n\n他说：\n“孩子是您没看好。”",
    "quote": "“家长须看护”——\n这五个字，\n能免除所有责任吗？",
    "knowledge": "《民法典》第1198条：\n宾馆、商场、银行、车站、\n机场、体育场馆、娱乐场所等\n经营场所、公共场所的\n经营者、管理者\n或者群众性活动的组织者，\n未尽到安全保障义务，\n造成他人损害的，\n应当承担侵权责任。\n\n第506条：\n造成对方人身损害的\n免责条款无效。\n\n也就是说：\n一句“家长须看护”的告示，\n不能免除\n场地本身的安全责任；\n责任怎么分，\n要看设施有没有隐患、\n提示是否到位\n和双方各自的过错。",
    "related": "“是不是真的是我的错？”——\n你会先这样问自己，\n因为他们这么说。\n\n但“家长看护”\n和“场地安全”\n是两件事，\n不是二选一。\n\n你要做的第一件事\n是把现场拍下来。",
