    "title": "这一周，都是些“小事”，也都有条文",
    "frontText": "六件很小、却都有条文的事。\n\n外卖里吃出异物。\n试用期被辞退。\n退租被扣押金。\n楼上噪音吵得睡不着。\n接到诈骗电话。\n孩子在游乐场摔伤。\n\n一件一件数过来——\n这些事都很小，\n小到你觉得\n“不值得较真”，\n可它们每一件\n后面都站着一条规则。",
    "quote": "“事情太小”——\n不是不较真的理由，\n是它本来\n就有便宜的做法。",
    "knowledge": "这一周的五条规则：\n\n🍜 食品异物——\n十倍或三倍赔偿，\n不足一千按一千\n👔 试用期——\n解除要说明理由、\n要能证明不符合录用条件\n🔑 退租押金——\n正常使用损耗不承担赔偿\n🔇 邻里噪音——\n先记录时间和次数，\n再找物业、社区或报警\n☎️ 诈骗电话——\n不报验证码，\n挂掉打官方号或96110\n🎢 游乐场——\n“家长须看护”\n不免除场地安全责任",
    "related": "这一周你最容易记住的\n不是条文，\n是两句话：\n\n“请说明依据。”\n“请给我书面记录。”\n\n这两句话\n几乎能用在\n这一周所有的事上。",
    "action": "留一行字：\n\n“事情小，\n  但我不打算\n  再算了。”\n\n退租被扣押金的同事，\n孩子摔伤的朋友——\n把这一页\n给他们各看一眼。",
