    "title": "旧信封里的缴费凭证",
    "frontText": "你替长辈\n收拾柜子。\n\n一个旧信封里\n装着一沓纸：\n\n参保凭证、\n缴费记录、\n一张\n字迹褪色的对账单。\n\n长辈在旁边说：\n“这些留着\n  有什么用？\n  我又看不懂。”\n\n你把它们\n一张一张\n按年份排开。",
    "quote": "看不懂，\n不等于\n可以丢掉。",
    "knowledge": "这些纸\n不是纪念品。\n\n《社会保险法》第十六条：\n参加基本养老保险的个人，\n达到法定退休年龄时\n累计缴费满十五年的，\n按月领取基本养老金。\n\n不足十五年的，\n可以缴费至满十五年，\n也可以转入\n城乡居民基本养老保险，\n按规定享受相应待遇。\n\n第十九条：\n个人跨统筹地区就业的，\n基本养老保险关系\n随本人转移，\n缴费年限累计计算。\n\n“缴过多少年”\n是算出来的，\n不是记得出来的。",
    "related": "你家长辈\n可能换过好几份工，\n中间断过几年。\n\n那些断掉的年份\n不会自己消失，\n也不会自己补上。\n\n它们躺在\n这些纸里。\n\n先收好，\n再谈别的。",
    "action": "今天做一件小事：\n\n如果家里有长辈的\n参保或缴费凭证，\n按年份排一次，\n拍照存一份。\n\n不做判断，\n先排序。",
