    "title": "“以后谁来照顾”这句话",
    "frontText": "长辈说得很轻：\n\n“老了\n  要是动不了，\n  谁来管我。”\n\n没人接话。\n\n过了一会，\n桌子上\n所有人的眼睛\n都往你这边\n瞟了一下。\n\n你是女儿。\n\n你说不出\n“我不行”，\n也说不出\n“就我来”。",
    "quote": "所有人的眼睛\n同时看向同一个人——\n这不是商量，\n这是默认。",
    "knowledge": "《老年人权益保障法》第十四条：\n\n赡养人应当履行\n对老年人经济上供养、\n生活上照料\n和精神上慰藉的义务，\n照顾老年人的特殊需要。\n\n赡养人\n是指老年人的子女\n以及其他\n依法负有赡养义务的人。\n\n赡养人的配偶\n应当协助赡养人\n履行赡养义务。\n\n第十九条：\n赡养人不得\n以放弃继承权\n或者其他理由，\n拒绝履行赡养义务。\n\n义务是明确的，\n但怎么分工\n没写。",
    "related": "法律写的是\n“赡养人应当履行”，\n不是\n“女儿应当履行”。\n\n所以那句话\n不该由\n桌上的一道眼神\n来决定。\n\n该由\n一份说出口的分工\n决定。",
    "action": "今天做一件小事：\n\n把“以后谁来照顾”\n这句话\n写在纸上，\n下面留几行空白。\n\n先不填，\n先让这句话\n有张纸。",
    "itchTrigger": "“你是女儿”——一道眼神就把这件事定了",
    "contradiction": "“照顾老人靠良心” vs 法律写的是赡养人应当履行",
