    "frontText": "你帮长辈\n查缴费记录。\n\n她年轻时\n在三个城市做过活：\n\n纺织厂、\n餐馆、\n后来\n又打了几年零工。\n\n她最担心的是\n中间断过的那几年：\n\n“是不是\n  断了就\n  白干了？”\n\n你打开手机，\n准备一条一条\n算给她听。",
