    "title": "“常回家看看”是有出处的",
    "frontText": "表填到一半，\n有人小声说：\n\n“我在外地，\n  实在回不来。”\n\n你没接话。\n\n你想起\n以前听过\n一句被笑了很久的话——\n\n“常回家看看，\n  写进法律了”。\n\n你决定\n把它找出来，\n看清它\n到底怎么写。",
    "quote": "被当成玩笑的那一句，\n在条文里\n是认真的。",
    "knowledge": "《老年人权益保障法》第十八条：\n\n家庭成员应当\n关心老年人的精神需求，\n不得忽视、冷落老年人。\n\n与老年人分开居住的\n家庭成员，\n应当经常看望或者问候老年人。\n\n用人单位\n应当按照国家有关规定\n保障赡养人探亲休假的权利。\n\n注意最后一句：\n条文没有只对子女说，\n它也让用人单位\n承担了一份。\n\n所以“回不来”\n不全是\n一个人的问题。",
    "related": "你以前\n觉得\n“经常看望”\n是一句\n没办法执行的道德话。\n\n看清楚之后\n才发现：\n\n它旁边\n还站着\n一条\n关于探亲假的义务。",
    "action": "今天做一件小事：\n\n打一个电话，\n就问问\n“最近睡得好吗”。\n\n这不叫完成任务，\n这叫\n把这条条文\n用一次。",
    "itchTrigger": "“常回家看看还写进法律了？”——它真的写了，而且不只对子女说",
    "contradiction": "“回不来是我的错” vs 条文同时给用人单位派了义务",
    "verifyTask": "写下“经常看望或者问候老年人”写在第几条。",
    "imaginationPrompt": "如果探亲假真的能用上，你家里谁最先回得来？",
    "safetyNote": "本卡为法律认知科普；探望与探亲休假的具体安排以现行法律和单位制度为准。",
