    "frontText": "这一周，\n你把一堆凭证排成了年份，\n把一句“谁来照顾”\n摊到了桌上，\n把“外人”两个字\n换成了“协助”，\n把断掉的年限\n问清楚了，\n把照护\n画成了四栏，\n还找到\n“经常看望”\n写在第几条。\n\n“以后”\n开始有了形状。",
    "quote": "不是把老年\n安排妥当，\n是把它\n从沉默里\n拿出来。",
    "knowledge": "养老与照护这一周的五个点：\n\n一、缴费：\n累计满十五年\n按月领取基本养老金；\n跨地区就业\n缴费年限累计计算\n（《社会保险法》第十六、\n十九条）\n\n二、谁是赡养人：\n子女及其他依法\n负有赡养义务的人；\n赡养人的配偶\n应当协助\n（《老年人权益保障法》\n第十四条）\n\n三、服务怎么配：\n以居家为基础、\n社区为依托、\n机构为支撑\n（第五条、第十三条）\n\n四、看望：\n分开居住的家庭成员\n应当经常看望或者问候\n（第十八条）\n\n五、经济困难的老年人，\n地方应当逐步给予\n养老服务补贴\n（第三十七条）\n\n五点连起来，\n就是一张\n可以谈的表。",
    "related": "你以前\n觉得\n“养老”\n是一个\n要等到那一天\n才面对的词。\n\n现在它\n是四栏表、\n五个条文、\n一份\n按年份排好的凭证。\n\n能被写下来的事，\n就没那么吓人。",
    "action": "把这一页收好：\n\n凭证的年份 /\n赡养人和协助 /\n服务的方式 /\n看望 /\n补贴。\n\n然后在下面\n写下\n你打算\n先跟谁\n开这个口。",
