    "title": "投诉一个“普遍现象”——还有人替你起诉",
    "frontText": "你在网上看到一条新闻。\n某个地方的招聘广告\n写着“限男性”。\n\n你想起你自己求职的时候\n也遇到过。\n你想起你朋友\n因为“已婚未育”被拒了。\n\n你想投诉。\n但你不知道\n投诉一个“普遍现象”\n有什么用。\n\n你觉得\n“一个人投诉\n  也改变不了什么”。\n\n你关掉了新闻。",
    "quote": "“一个人投诉改变不了什么”——\n如果投诉的\n不是一个人呢？",
    "knowledge": "《妇女权益保障法》第七十七条：\n侵害妇女合法权益，\n导致社会公共利益受损的，\n检察机关可以发出检察建议；\n对侵害妇女平等就业权益等\n法定情形，\n检察机关可以依法\n提起公益诉讼。\n\n也就是说：\n当歧视是系统性的、\n不是针对你一个人的，\n你不需要一个人扛。\n\n你能做的是：\n把自己遇到的那一次\n记下来——\n时间、岗位、原话、截图，\n交给12338 或者\n当地检察院的控告申诉窗口。",
    "related": "“一个人投诉没用”——\n这句话很可能是真的。\n\n但“一个人”\n和“一条线索”\n是两件事。\n\n你不需要打赢一场仗，\n你只需要让这件事\n进入记录。\n\n很多改变，\n就是从一条记录开始的。",
    "action": "如果你或者身边的人\n遇到过招聘歧视，\n今天做一件小事：\n\n把当时看到的招聘信息\n截图存好，\n把时间、岗位、原话\n写在备忘录里。\n\n然后打12338 问一句：\n“这种情况可以往哪里反映？”",
    "itchTrigger": "“限男性”的招聘广告不是第一次见，你关掉就没再想",
    "contradiction": "“一个人改变不了什么” vs 系统性歧视可以走公益诉讼",
