    "title": "楼道堆物——离你最近的那个“管事的人”",
    "frontText": "你家楼道里堆满了杂物。\n\n纸箱。\n旧家具。\n电动车。\n\n你每次经过都要侧身。\n你觉得不安全。\n你怕着火。\n\n你跟物业说了。\n物业说：\n“我们贴过通知了，没人清。”\n\n你跟邻居说了。\n邻居说：\n“别人都堆，\n你管得着吗？”\n\n你站在楼道里。\n你不知道找谁。",
    "quote": "“反正不是我家门口”——\n如果着火了，\n烧的是整栋楼。",
    "knowledge": "社区网格员：\n每个社区划分为若干网格，\n每个网格配备网格员。\n\n网格员负责：\n巡查安全隐患、\n调解邻里纠纷、\n收集社情民意、\n协助居民解决问题。\n\n楼道堆物、消防隐患、\n邻里矛盾，\n都可以找网格员。\n\n找不到人，可以问：\n社区居委会、\n物业公示栏、\n或者直接打12345。",
