    "title": "医保卡“被盗刷”——先挂，再打12393",
    "frontText": "你接到一个电话。\n\n对方说：\n“你的医保卡\n在外地被盗刷了。”\n“你需要配合调查。”\n“你的银行账户要冻结。”\n\n你心里一紧。\n你问：“那怎么办？”\n\n对方说：\n“你把钱转到一个\n安全账户。”\n\n你正要操作。\n家里人说：\n“这是诈骗。”\n你说：\n“人家知道我的医保卡号。”",
    "quote": "“他知道我的医保卡号”——\n所以就是真的吗？",
    "knowledge": "记住三条，\n比记住话术更有用：\n\n① 公安机关、医保部门\n不会在电话里\n让你转账、\n不会要你的验证码；\n② 不存在\n所谓“安全账户”；\n③ 医保卡有疑问，\n挂掉电话自己拨官方号码。\n\n官方渠道：\n12393 医保服务热线、\n12333人社服务热线，\n或者直接去\n当地医保经办机构窗口。\n\n《反电信网络诈骗法》\n明确禁止为诈骗\n提供帮助，\n转账前多问一句，\n就是最好的防线。",
    "related": "“他知道我的信息”——\n这不是可信的证据，\n这恰恰是诈骗的日常。\n\n你不是“好骗”，\n你只是被吓了一跳。\n\n遇到这种电话，\n你唯一要做的事是：\n挂掉，\n然后自己拨官方号码。",
    "action": "今天做一件小事：\n\n把12393和12333\n存进通讯录，\n备注“医保 / 人社”。\n\n再跟家里老人说一句：\n“钱被骗了\n  不是你笨，\n  是他们的脚本\n  在升级。”",
    "itchTrigger": "对方说得头头是道，你差点把钱转到“安全账户”",
    "contradiction": "“他说得出我的卡号” vs 医保部门不会用电话教你转账",
    "verifyTask": "把12393存进通讯录，和家人约一句只有你们懂的口令。",
    "imaginationPrompt": "如果在按下转账前多等十秒，家里会少什么故事？",
    "safetyNote": "已经转账的，立即拨打110报警并联系银行止付；保留通话记录、短信和转账凭证。任何人索要验证码、要求转入“安全账户”的都是诈骗。",
