    "title": "被罚了不服气——行政复议这道门",
    "frontText": "你被行政处罚了。\n\n你开的小店被罚了两万。\n你觉得冤枉。\n你觉得不该罚这么多。\n\n你想申诉。\n你不知道找谁。\n\n你觉得\n“政府部门说了算”。\n你觉得\n“一个老百姓\n  能改变什么”。\n\n你把罚款交了。\n你把委屈咽下去了。",
    "quote": "“政府说了算”——\n如果你觉得不对，\n有没有地方可以说？",
    "knowledge": "《行政复议法》：\n公民、法人或者其他组织\n认为行政机关的行政行为\n侵犯其合法权益的，\n可以申请行政复议。\n\n申请期限：\n一般自知道该行政行为\n之日起60日内。\n\n复议机关：\n按现行《行政复议法》\n（2024年1月1日施行）确定，\n多由县级以上地方人民政府\n统一受理。\n\n对复议决定不服，\n还可以依法提起诉讼。\n\n配套的\n《行政复议法实施条例》\n已于2026年7月1日\n起施行修订版。",
    "related": "“政府部门说了算”——\n这句话在交罚款的时候\n是对的。\n\n但在行政复议里，\n你不是求情，\n你是行使\n一个法定的救济权利。\n\n你觉得处罚有问题，\n就可以依法说一次。",
    "action": "今天做一件小事：\n\n如果身边有人\n被行政处罚过，\n提醒他一句：\n“不服可以申请行政复议，\n  一般60天内。”\n\n这句话本身，\n可能就是他要找的门。",
