    "title": "残疾不等于不能工作",
    "frontText": "你去面试。\n\nHR 看了你一眼。\n说：\n“我们这个岗位\n可能不太适合你。”\n\n你问：“哪里不适合？”\n他说：\n“你自己应该知道。”\n\n你心里堵得慌。\n\n你不知道\n是不是因为残疾被拒。\n你不知道能不能投诉。\n你不知道找谁。",
    "quote": "“你自己应该知道”——\n残疾不等于“不能工作”。",
    "knowledge": "《残疾人保障法》：\n国家保障残疾人劳动的权利。\n《就业促进法》：\n用人单位招用人员，\n不得歧视残疾人。\n\n残联\n（中国残疾人联合会及其地方组织）：\n可以提供就业服务、\n法律咨询和维权支持。\n\n用人单位未按规定\n安排残疾人就业的，\n应当缴纳\n残疾人就业保障金——\n也就是说，\n“不想招”不是没成本的。",
    "related": "“你自己应该知道”——\n这句话不是理由，\n是把判断\n推给你自己。\n\n岗位能不能胜任，\n看的是岗位要求和\n有没有合理便利，\n不是一眼看过去\n“像不像”。\n\n你可以问：\n“具体是哪一条要求\n  我不符合？”",
    "action": "如果你或身边的人\n遇到过这种情况，\n今天做一件小事：\n\n把面试的时间、公司、\n那句原话记下来。\n\n然后打当地残联\n或12333 问一句：\n“这种情况能不能反映？”",
    "itchTrigger": "“你自己应该知道”——你不知道该问谁",
    "contradiction": "“岗位不适合” vs 就业促进法禁止歧视",
