    "title": "“为你好”的调岗——孕期不该这样被安排",
    "frontText": "你怀孕了。\n\n领导把你\n从核心项目里调出来了。\n说：\n“你现在不方便出差。\n这个项目要经常出差。”\n\n你说：“我可以协调。”\n他说：“为你好。”\n\n你被调到了一个闲职。\n你觉得不对。\n\n你不知道\n能不能说“不”。\n你不知道找谁。\n你不知道工会能不能帮你。",
    "quote": "“为你好”——\n谁的好？",
    "knowledge": "《女职工劳动保护特别规定》第6条：\n女职工在孕期\n不能适应原劳动的，\n用人单位应当根据\n医疗机构的证明，\n予以减轻劳动量\n或者安排其他劳动。\n\n《妇女权益保障法》第四十八条：\n不得因女职工怀孕、产假、哺乳\n降低工资和福利待遇，\n限制晋职、晋级、评聘职称，\n或者辞退女职工、\n单方解除劳动合同。\n\n能不能调岗，\n要看是不是\n“不能适应原劳动”、\n有没有医疗机构的证明、\n工资有没有被降低。",
    "related": "“为你好”\n听起来像体贴。\n\n但如果它同时\n把你从核心项目挪走、\n把工资降下来、\n把晋升机会拿走，\n那它就不是体贴。\n\n你可以提三条：\n我要书面的调岗依据；\n工资不变；\n产后再回来。",
    "action": "如果你正在经历这件事，\n今天做一件小事：\n\n把调岗通知、\n岗位说明\n和之前的工资条\n收好。\n\n然后问一句：\n“这次调整\n  有没有书面依据？”",
