    "title": "群里那句抱怨——可以变成一条议题",
    "frontText": "社区群里又在吵。\n\n有人发了一句话：\n“小区后面那条路\n  晚上太黑了，\n  孩子放学不安全。”\n\n下面跟着三条回复：\n“是挺黑的。”\n“说了也没用。”\n“找谁啊？”\n\n然后就没有然后了。\n\n你看着屏幕。\n你也觉得黑。",
    "quote": "一句抱怨\n和一条议题之间，\n隔着一件事：\n把它说清楚。",
    "knowledge": "《妇女权益保障法》第13条：\n妇女有权通过各种途径和形式，\n依法参与管理国家事务、\n管理经济和文化事业、\n管理社会事务。\n\n把抱怨变成议题，\n只要补三样：\n\n① 具体地点——\n哪一段路、几号到几号；\n② 具体事实——\n什么时候黑、\n出过什么事、\n影响到谁；\n③ 具体诉求——\n希望装几盏灯、\n找哪个部门。\n\n补完这三样，\n它就可以发到\n12345、\n社区网格员\n或者居民议事会上，\n而不是只留在群里。",
    "related": "“说了也没用”——\n这句话\n在群里出现得最多。\n\n但它通常不是结论，\n是“还不知道找谁”\n的另一种说法。\n\n你要做的不是说服群里的人，\n是先把那三样补上。",
    "action": "今天做一件小事：\n\n如果你所在的群里\n有一个悬着的问题，\n把它补成一条\n带地点、事实和诉求的\n话，发出去。\n\n就一条。",
