    "dimension": "participation",
    "title": "“我也觉得”——联名是怎么长出来的",
    "frontText": "你在群里\n回了四个字：\n“我也觉得黑。”\n\n发出去之后\n你有点后悔。\n你怕别人觉得你多事。\n你怕被点名。\n\n过了一会儿，\n有人回：\n“我也觉得。”\n又有人回：\n“我孩子也走那条路。”\n\n到晚上，\n那条消息下面\n跟了十几个人。",
    "quote": "一个人说叫意见，\n十几个人说叫材料。",
    "knowledge": "参与不等于“负责”。\n参与可以只是——\n“我也觉得”\n“我支持”\n“算我一个”。\n\n当十几个人\n在同一件事上留言，\n它就从“个人抱怨”\n变成了一份\n可以提交给社区的记录。\n\n可以这样用：\n把群里的回复截图，\n按时间顺序整理，\n标注人数和诉求，\n一起交给\n社区网格员、\n12345 或者居民议事会。\n\n联名反映不需要谁牵头，\n需要的是\n把散落的意见收在一起。",
    "related": "你以前觉得\n“参与”就得站出来、\n就得当那个出头的人。\n\n不是的。\n\n回一句“我也觉得”，\n也是在把答案\n往前推一格。\n\n一个人的意见\n会被当成情绪，\n十个人的意见\n会被当成数据。",
    "action": "今天做一件小事：\n\n这两天在群里\n看到自己认同的抱怨，\n回一句：\n\n“我也遇到过。”\n\n就这一句。",
    "itchTrigger": "回完那四个字你就后悔了，怕别人说你多事",
