    "title": "学校要交两百块——家长有权问依据",
    "frontText": "家长群里\n又吵起来了。\n\n学校要搞活动，\n每个家长交两百块。\n\n有人说：\n“太贵了。”\n有人说：\n“别人都交，你不交？”\n有人说：\n“不交孩子会被说。”\n\n你看着那两百块。\n你不是交不起。\n你只是想知道\n它花在哪。",
    "quote": "“别人都交”\n不是收费依据。",
    "knowledge": "《义务教育法》：\n学校不得违反国家规定\n收取费用。\n\n《消费者权益保护法》：\n消费者享有\n公平交易的权利，\n有权询问\n商品或者服务的真实情况。\n\n也就是说：\n家长有权问一句\n“这个收费\n  有没有文件依据？”\n\n可以问的渠道：\n先问班主任或学校；\n问不到，\n向教育局反映，\n或者打12345。\n\n收费应当公开透明；\n自愿参加的收费，\n不可以变成变相强制。",
    "related": "“不交孩子会被说”——\n这句话\n不是收费的理由，\n是压力的理由。\n\n问依据\n不是跟老师过不去，\n是让每一笔钱\n都说得清。\n\n你问出来，\n群里其他家长\n也会松一口气。",
    "action": "今天做一件小事：\n\n下一次孩子带回\n一张收费通知，\n先看两样：\n有没有写明项目和依据，\n有没有写“自愿”。\n\n少一样，就问一句。",
    "itchTrigger": "两百块你不是交不起，只是不知道为什么交",
    "contradiction": "“别人都交” vs 收费要有依据、要写自愿",
    "verifyTask": "找出一张收费通知，看看有没有写项目和“自愿”。",
    "imaginationPrompt": "如果第一个问的人是你，群里会有几个家长跟着问？",
    "safetyNote": "学校收费的合规性由教育行政部门认定；询问时建议在班级或家长群公开提出，避免针对具体老师。",
    "source": "中华人民共和国义务教育法 / 中华人民共和国消费者权益保护法",
