    "frontText": "在湖南江永，\n从前有一种字，\n只有女人写、\n女人认。\n\n男人站在旁边，\n也看不懂。\n\n它被写在\n扇面上、手帕上、\n绣进带子里，\n用来诉说、\n唱歌、写心事。\n\n一种字，\n只在女人之间传，\n是因为\n别的地方\n没给她们留位置。",
    "quote": "没有地方写，\n就自己造一种字。",
