    "frontText": "你查地方志。\n\n在“人物”那一卷，\n男人的条目里\n写着他做过什么官、\n办过什么事、\n留下什么文章。\n\n女人也有条目，\n但大多是\n一种：\n\n守节的、\n殉夫的、\n苦熬一辈子的。\n\n她们的手艺、\n她们怎么把日子过起来，\n一个字都没有。",
