    "frontText": "1990年代。\n\n一批研究者\n背着录音机\n去敲普通人的门。\n\n问的不是名人，\n是纺织女工、\n农村妇女、\n退休教师。\n\n问她们：\n你小时候什么样？\n你怎么决定嫁不嫁？\n你第一个月的工资\n花在哪儿了？\n\n那些回答\n后来成了书。",
