    "frontText": "你决定\n把家里老人的话\n记下来。\n\n先别急着按录音键。\n\n四件事\n要先说清楚：\n\n为什么记、\n给谁看、\n用不用真名、\n她随时可以喊停。\n\n记下来是好事，\n但记的是\n别人的人生。",
