    "title": "《民法典》第1035条：同意不是客气",
    "frontText": "那四条规矩里，\n“先征得同意”\n不是口头客气。\n\n《民法典》\n第一千零三十五条写着：\n\n处理个人信息，\n应当遵循\n合法、正当、必要原则，\n并要征得\n本人或者其监护人同意，\n还要\n明示目的、方式\n和范围。\n\n记录别人的人生，\n就是处理\n别人的信息。",
    "quote": "同意不是一句\n“她不介意吧”，\n是要说清\n用来做什么。",
    "knowledge": "《民法典》第一千零三十五条：\n\n处理个人信息的，\n应当遵循\n合法、正当、必要原则，\n不得过度处理，并符合：\n\n（一）征得该自然人\n或者其监护人同意；\n（二）公开处理信息的规则；\n（三）明示处理的\n目的、方式和范围；\n（四）不违反法律、行政法规\n的规定和双方的约定。\n\n所以“我记下来\n存着”\n和“我记下来\n发到网上”，\n需要的是\n两次不同的同意。",
    "related": "你可能会想：\n家里人的事，\n用得着这么正式吗？\n\n用得着。\n\n因为“家里人”\n是最容易被\n默认同意的一群人。\n\n问一句，\n不伤感情；\n不问，\n才可能伤。",
    "action": "今天做一件小事：\n\n如果你手机里\n存着别人的聊天截图，\n今天看一眼：\n\n发出去之前，\n你问过她吗？\n\n没问过的，\n先别发。",
