    "dimension": "constitution",
    "title": "一部法律怎么诞生",
    "frontText": "你在网上\n看到一条公告：\n\n“某某法律草案\n 公开征求意见，\n 截止到某月某日。”\n\n你点开看了看。\n\n一条一条，\n很长。\n\n你关掉了。\n\n你想：\n“跟我说了\n 也没用。”",
