    "knowledge": "一部法律\n一般要过这几关：\n\n· 提案；\n· 全国人大常委会\n  审议，\n  一般要经过三次审议；\n· 重要的法律草案\n  公开征求意见，\n  公众可以提意见；\n· 表决通过后\n  由国家主席签署公布。\n\n你说的一条意见\n不会直接变成法条，\n但会被汇总、\n进入审议参考，\n有时\n直接推动了修改。\n\n提意见的门槛很低：\n写清“第几条、\n为什么、\n建议怎么改”。",
