    "frontText": "你在社区\n听到一件事：\n\n公交站台\n没有遮雨棚，\n老人下雨天\n只能站在雨里。\n\n有人说：\n“找谁都没用。”\n\n有人回：\n“可以找代表\n 提个建议。”\n\n你不知道\n建议\n是怎么走的。",
