    "knowledge": "人大代表\n在会议期间\n可以提出\n对各方面工作的\n建议、批评和意见\n（通常叫“代表建议”）。\n\n流程大致是：\n\n① 代表提出，\n  写明情况和诉求；\n② 由人大常委会\n  交有关机关、组织办理；\n③ 承办单位\n  在规定期限内答复，\n  并说明采纳情况；\n④ 代表对答复不满意的，\n  可以要求\n  重新办理或者说明。\n\n所以建议\n有交办、有答复、\n有期限，\n不是说完就完了。",
