    "title": "“份额”两个字，不是随口说的",
    "frontText": "“那我到底能分多少？”\n\n法律给的第一句是：\n\n同一顺序的继承人，\n继承遗产的份额，\n一般应当均等。\n\n后面还跟着三种情形：\n\n生活有特殊困难、\n又缺乏劳动能力的，\n应当照顾；\n尽了主要扶养义务的，\n可以多分；\n有能力尽义务而不尽的，\n应当不分或者少分。",
    "quote": "“一般均等”是起点，\n不是结论。",
    "knowledge": "《民法典》第一千一百三十条：\n\n同一顺序继承人\n继承遗产的份额，\n一般应当均等。\n\n对生活有特殊困难\n又缺乏劳动能力的继承人，\n分配遗产时，应当予以照顾。\n\n对被继承人尽了主要扶养义务\n或者与被继承人共同生活的，\n可以多分。\n\n有扶养能力和有扶养条件\n而不尽义务的，\n应当不分或者少分。\n\n继承人协商同意的，\n也可以不均等。",
