    "frontText": "这一周，\n你听了那句\n“我们家一直这样分”，\n然后一路问到了窗口。\n\n顺序：\n子女同在一列，不分男女。\n份额：\n一般均等，看照料看能力。\n遗嘱：\n要签名、日期、见证人。\n共同财产：\n先分一半给配偶。\n\n惯例在饭桌上，\n条文在纸上。\n\n你两边都看见了。",
