    "title": "一个人带孩子——帮扶不是一个词",
    "frontText": "你一个人带孩子。\n你离婚了。\n孩子归你。\n\n他不给抚养费。\n你一个人扛。\n你要上班。\n你要接送。\n你要做饭。\n你要辅导作业。\n\n你每天像打仗。\n你觉得自己快撑不住了。\n\n你想找人帮忙。\n你不知道找谁。\n\n你觉得\n“单亲妈妈只能靠自己”。",
    "quote": "“单亲妈妈只能靠自己”——\n真的吗？",
    "knowledge": "可以申请的几类支持：\n\n最低生活保障——\n家庭人均收入\n低于当地低保标准可以申请，\n由民政部门审核；\n\n临时救助——\n因突发事件导致\n基本生活暂时困难的，\n可以向乡镇、街道申请；\n\n教育救助——\n子女可申请助学金、\n减免相关费用；\n\n住房救助——\n公租房、保障性租赁住房\n对符合条件的家庭有优先或倾斜；\n\n妇联帮扶——\n不少地方有\n“单亲困难母亲”\n援助项目，可打12338 问。\n\n条件、标准各地不同。",
    "related": "“只能靠自己”——\n这句话\n你已经说了很久。\n\n帮扶不是“要饭”，\n是用你已经交过、\n或者制度本来就\n为你准备的那部分。\n\n先把能申请的三项\n写在纸上，\n你会发现\n自己不是只有一个人。",
    "action": "今天做一件小事：\n\n给12338 打一个电话，\n或者去社区问一句：\n“咱们这儿\n  对单亲家庭\n  有哪些帮扶？”\n\n把答复记下来。",
    "itchTrigger": "“单亲妈妈只能靠自己”，你连问都没问过",
    "contradiction": "“开口就是示弱” vs 帮扶本来就是制度的一部分",
    "verifyTask": "打一次12338或问一次社区，写下你能申请的项目。",
    "imaginationPrompt": "如果每月多一份支持，你的一周会松哪一块？",
    "safetyNote": "低保、临时救助等需经民政部门按家庭收入和财产状况审核，本卡不承诺结果；抚养费问题可另行向法院申请强制执行。",
    "source": "社会救助暂行办法 / 妇联组织与12338妇女维权公益服务热线",
    "sourceUrl": "https://www.gov.cn/",
