    "title": "“嫁出去的媳妇，没有你的份”——新法不这么写",
    "frontText": "你是农村户口。\n你嫁到了邻村。\n你户口没迁。\n\n村里征地拆迁。\n补偿款按人头分。\n\n你去问。\n村委会说：\n“你嫁出去了，\n没有你的份。”\n\n你站在村委会门口。\n你想起你从小\n在这个村长大。\n你想起你爸妈\n还在这个村。\n你想起你的地\n还在这个村。\n\n但他们说\n你不是这个村的人了。",
    "quote": "“嫁出去的女儿\n泼出去的水”——\n法律认这句话吗？",
    "knowledge": "《农村集体经济组织法》\n2025年5月1日起施行。\n\n第十二条：\n因成员生育而增加的人员，\n应当确认为成员；\n因结婚、收养或者政策性移民\n增加的人员，\n一般应当确认为成员。\n\n第十八条：\n成员不因离婚、丧偶等原因\n丧失成员身份。\n\n第八条：\n不得以妇女未婚、结婚、\n离婚、丧偶、户无男性等为由，\n侵害妇女在该组织中的权益。\n\n《妇女权益保障法》第五十六条\n也有规定：\n村规民约和村民会议决定，\n不得以妇女未婚、结婚、\n离婚、丧偶、户无男性等为由，\n侵害其各项权益。\n\n遇到这种情况：\n先要一份书面答复，\n再向乡镇政府（街道）、\n农业农村部门反映，\n必要时起诉。",
    "related": "“你不是这个村的人了”——\n这句话\n在他们嘴里很顺，\n在法律上\n要先看两样：\n你的户籍，\n和你的成员身份记录。\n\n你不需要吵架，\n你需要一句：\n“请给我一份书面答复。”",
