    "title": "女儿考上大学——学费不止一条路",
    "frontText": "你女儿成绩很好。\n她想考大学。\n她想读研究生。\n\n你算了算学费。\n你算了算生活费。\n你看着那个数字。\n\n你觉得你供不起。\n\n你跟女儿说：\n“要不你别读那么多了。”\n\n女儿没说话。\n她回房间了。\n\n你坐在客厅。\n你觉得自己很没用。",
    "quote": "“供不起”——\n有没有人\n可以帮你一起供？",
    "knowledge": "国家助学体系\n不只一种：\n\n国家助学贷款——\n本专科、研究生都可以申请，\n在校期间利息\n由财政补贴，\n毕业后开始还本付息，\n还款期限和方式\n可以协商；\n\n国家助学金——\n面向家庭经济困难学生，\n按学年评定发放；\n\n国家奖学金、励志奖学金——\n成绩和家庭情况兼看；\n\n绿色通道——\n开学时先报到、\n后办理缴费；\n\n勤工助学——\n校内岗位有报酬。\n\n办理入口：\n学校学生资助管理中心、\n国家开发银行\n生源地信用助学贷款。\n\n标准和额度\n以当年国家和当地政策为准。",
    "related": "“供不起”——\n这三个字\n让孩子把话\n咽了回去。\n\n但助学贷款不是借钱丢人，\n是国家专门\n为这句话设的制度。\n\n你可以跟女儿说：\n“你只管考，\n  钱我们一起想办法。”",
    "action": "今天做一件小事：\n\n搜一句：\n“生源地信用助学贷款\n  申请条件”。\n\n或者打学校电话，\n问“学生资助管理中心”\n的电话。\n\n先把入口找出来。",
