    "title": "总觉得累——12356，不是“想太多”",
    "frontText": "你最近总觉得累。\n\n不是身体累。\n是那种\n什么都不想做的累。\n\n你睡不好。\n你不想说话。\n你不想见人。\n\n他说：“你就是想太多。”\n你妈说：“你就是太闲了。”\n朋友说：“出去玩玩就好了。”\n\n你去了。\n你玩了。\n你回来还是累。\n\n你觉得自己“不正常”。\n但你不知道\n去哪里找人问问。",
    "quote": "“心情不好”\n和“心理生病”\n是两件事。",
    "knowledge": "12356——\n全国统一心理援助热线，\n2025年5月1日起全国统一使用，\n提供心理咨询、心理疏导\n和心理危机干预。\n\n它不需要你先\n“证明自己病了”：\n“我最近睡不好”\n也可以打。\n\n如果出现持续的\n情绪低落、兴趣减退、\n失眠、食欲改变\n超过两周，\n建议去正规医院的\n精神科或心理科门诊，\n而不是硬扛。\n\n紧急情况\n（有伤害自己的念头）\n立即拨打110 或120。",
