    "frontText": "你邻居在打孩子。\n\n你听到哭声。\n你听到骂声。\n你听到摔东西的声音。\n\n你站在门口。\n你想敲门。\n你又不敢。\n\n你怕多管闲事。\n你怕人家说\n“我管自己孩子\n  关你什么事”。\n\n你站了十分钟。\n你回屋了。\n\n你坐在沙发上。\n你听着隔壁的哭声。\n你觉得自己很没用。",
    "quote": "“别人家的事”——\n如果那个孩子\n需要帮助呢？",
    "knowledge": "《反家庭暴力法》第14条\n确立了强制报告：\n学校、幼儿园、医疗机构、\n居民委员会、村民委员会、\n社会工作服务机构、\n救助管理机构、福利机构\n及其工作人员，\n发现未成年人\n遭受或者疑似遭受\n家庭暴力的，\n应当及时向公安机关报案。\n\n你可以做的：\n拨打110；\n或打12345、12338\n反映。\n\n可以匿名。\n不需要留下姓名，\n也不需要你去敲门。",
    "related": "“多管闲事”——\n这四个字\n让很多孩子\n多挨了几年。\n\n你不需要\n冲进去制止，\n你只需要\n让一个有能力介入的人\n知道这件事。\n\n一个电话，\n就是一次干预。",
    "action": "今天做一件小事：\n\n把110\n和12338\n放在同一个备注里：\n\n“如果邻居家一直在哭。”\n\n不用今天用。\n存着。",
    "itchTrigger": "你站在门口十分钟，最后回屋关上了门",
    "contradiction": "“别人家的事” vs 强制报告制度要求有人报案",
    "verifyTask": "把110和12338存好，写下你愿意拨打的那一个。",
    "imaginationPrompt": "如果那十分钟你用了一个电话，隔壁的孩子会少经历什么？",
    "safetyNote": "如孩子正处于危险中立即拨打110；不要与施暴方正面冲突。报告可以匿名，社区儿童主任、学校也属于应当报告的主体。",
