    "title": "“你们太过分了”之后，没有下一句",
    "frontText": "你写了一段话。\n\n写了很长，\n写得很痛快。\n\n“你们太过分了，\n  拖了两个月，\n  没人管，\n  还有没有王法。”\n\n你读了两遍。\n\n然后你停住了：\n\n这段话\n要对方\n做什么？\n\n你自己\n也答不上来。",
    "quote": "愤怒是真的，\n但它不是\n一个请求。",
    "knowledge": "投诉里的情绪\n不用删掉，\n但要和请求分开。\n\n一段能往下走的文字\n通常有三个动作：\n\n一、说事实：\n这件事\n什么时候发生的；\n\n二、说已经做过的：\n我联系过谁、\n拿到过什么；\n\n三、说请求：\n我希望\n在哪一天之前\n得到什么形式的答复。\n\n《信访工作条例》\n对信访事项的\n受理、办理、\n复查、复核\n作了规定，\n它的用法\n就是\n让请求\n落在这些环节上。\n\n“太过分了”\n没有环节可以落。",
    "related": "你以前\n觉得写得越狠，\n越显得\n这事严重。\n\n其实\n越具体，\n越显得\n这事\n是能办的。\n\n情绪留在第一句，\n请求放在最后一句。",
