    "frontText": "社区通知\n周六开议事会。\n\n你想去。\n\n但你周六\n要带孩子。\n\n你在群里问：\n“能带孩子去吗？”\n\n没人回。\n\n你想了想，\n还是没去。\n\n会上定了\n儿童活动区的方案。",
    "quote": "去不了\n不代表\n你的意见不重要。",
    "knowledge": "《妇女权益保障法》第13条：\n妇女有权通过各种途径和形式，\n依法参与管理国家事务、\n管理经济和文化事业、\n管理社会事务。\n\n社区议事会的\n时间、地点、形式，\n应当尽量方便\n不同群体参与。\n\n所以“去不了”\n可以变成建议：\n\n① 能不能\n改到晚上或周末；\n② 能不能\n线上参加\n或者线上征求意见；\n③ 能不能\n带孩子参加、\n或者同时开个儿童看护间；\n④ 能不能\n接受书面意见。\n\n建议提出后，\n可以请社区\n把采纳情况\n写进纪要。",
    "related": "你以前把\n“去不了”\n理解成\n“我没资格”。\n\n不是的。\n\n参与的门槛\n是可以谈的——\n谈的人多了，\n它就会低一点。",
    "action": "今天做一件小事：\n\n下次看到会议通知，\n如果时间不合适，\n发一条消息：\n“能不能线上参加，\n  或者接受书面意见？”\n\n就一句。",
    "itchTrigger": "“能带孩子去吗？”没人回答，你就没去",
    "contradiction": "“去不了就是没资格” vs 时间地点形式本来就该考虑不同人",
    "verifyTask": "把“能不能线上开／能不能带孩子”写成一条建议发出去。",
    "imaginationPrompt": "如果下一次会议有线上通道，你会不会真的发言？",
    "safetyNote": "议事形式的调整由召集方结合实际情况决定；未成年人参加活动时注意看护与安全。",
