    "frontText": "你参加了\n这次议事会。\n\n讨论到\n儿童活动区的时候，\n你发现\n自己说了一句：\n\n“我们的孩子\n 放学没地方去。”\n\n你愣了一下。\n\n以前你说的是：\n“他们这个小区……”。",
