    "knowledge": "参与最难的一步\n不是说话，\n是把自己算进去。\n\n可以这样开始：\n\n· 社区的事\n → 我们小区的事\n· 村里的事\n → 我们家的事\n· 单位的事\n → 我们部门的事\n\n进了那个屋子，\n你就是利益相关方；\n你的经验\n就是最一线的信息。\n\n而《宪法》第2条写的\n正是这件事：\n人民依照法律规定，\n通过各种途径和形式，\n管理国家事务、\n管理经济和文化事业、\n管理社会事务。\n\n“我们”\n就是那条途径。",
    "related": "你以前觉得\n公共事务\n是别人的事。\n\n直到有一天\n你发现\n门口的路、\n楼下的灯、\n孩子的活动区，\n全是公共事务。\n\n它们早就\n是你的事，\n只是你\n还没坐进去。",
    "action": "今天做一件小事：\n\n把一句你常说的\n“他们……”，\n改成\n“我们……”。\n\n写下来，\n说给自己听一遍。",
    "itchTrigger": "你一直说“他们那个小区”，好像自己只是路过",
