    "title": "这一周，自治是把公共的事接过来",
    "frontText": "六件你每天路过、却从没问过的事。\n\n居委会、村委会\n是选出来的。\n业主大会和业委会\n本来就该管事。\n村务公开\n是有频次要求的。\n开会表决\n要提前通知。\n参与的门槛\n可以提意见。\n“他们的事”\n可以改成“我们的事”。\n\n把这几件事并排放——\n基层自治不是口号，\n是这些\n很具体的东西。",
    "quote": "自治不是让你当官，\n是让公共的事\n有人接、有人问。",
