    "frontText": "1994年。\n\n《中华人民共和国\n母婴保健法》\n通过，\n1995年6月1日\n施行。\n\n法律里写着：\n国家发展母婴保健事业，\n提供必要条件和\n医疗保健服务。\n\n产前检查、\n婚前保健\n这些词，\n第一次\n有了法律的身份。",
