    "frontText": "朋友说要结婚了。\n\n她挑完婚纱，\n忽然发来一句：\n\n“钱的事，\n  怎么跟他说清楚？”\n\n不是不信任。\n是她说不上来\n自己有什么、\n对方有什么、\n以后算谁的。\n\n婚礼可以在三个月后办，\n这张表\n现在就得开始画。",
