    "knowledge": "婚姻里的钱，\n先分成三类看，\n事情就清楚一半：\n\n一、婚前就有的\n——原则上还是各自的\n（《民法典》第一千零六十三条）；\n\n二、婚后挣的、挣来的\n——原则上共同所有\n（第一千零六十二条）；\n\n三、两个人另外说定的\n——按约定走，\n但要用书面形式\n（第一千零六十五条）。\n\n先分类，\n再谈怎么安排。",
    "related": "你身边一定有人\n说过：\n\n“谈钱\n  多伤感情。”\n\n可真正伤感情的，\n往往是\n什么都没有说，\n事情来了\n才发现\n两个人的算法不一样。",
    "action": "今天做一件小事：\n\n拿一张纸\n画三栏：\n\n婚前的 / 婚后的 / 说定的。\n\n先不用填，\n把栏画出来\n就算开始了。",
    "itchTrigger": "“谈钱伤感情”——可不谈，伤的是以后",
    "contradiction": "“结了婚就是一家人，分那么清干什么” vs 法律本来就分三类",
    "verifyTask": "写下婚姻财产的三类，各对应哪一条。",
    "imaginationPrompt": "如果这张表在领证前就画好，后面会少掉哪些误会？",
