    "title": "“房子在他名下”意味着什么",
    "frontText": "她最担心的是房子。\n\n“房本上只有他名字。”\n\n名字写谁，\n当然重要。\n\n但更关键的是两件事：\n\n这房子\n是什么时候买的；\n\n钱\n是从哪儿来的。\n\n婚前全款买的，\n和婚后两个人一起还贷，\n不是一回事。",
    "quote": "名字是第一眼，\n钱从哪儿来\n才是关键。",
    "knowledge": "《民法典》第一千零六十二条：\n\n婚姻关系存续期间所得的\n工资奖金、\n生产经营投资收益、\n知识产权收益等，\n为夫妻共同财产，\n归夫妻共同所有。\n\n同一款还写着：\n“夫妻对共同财产，\n有平等的处理权。”\n\n第一千零六十三条：\n一方的婚前财产、\n因人身损害获得的赔偿、\n遗嘱或赠与合同中\n确定只归一方的财产等，\n为个人财产。\n\n所以“写在他名下”\n和“与你无关”，\n不是同一句话。",
    "related": "“反正都是一家人，\n  写谁名字\n  有什么关系。”\n\n这句话\n在买房那天听着很暖，\n在算账那天\n就不好用了。\n\n不是要防着谁，\n是要知道\n法律在问什么。",
    "action": "今天做一件小事：\n\n如果家里有房，\n找出三个信息：\n\n买的年份、\n首付是谁出的、\n贷款是用谁的账户还的。",
    "itchTrigger": "“一家人写谁名字都一样”——算账那天就不一样了",
