    "title": "债找上门时，先问两个问题",
    "frontText": "真正让人措手不及的\n不是房，\n是债。\n\n有人上门，\n说他欠了钱。\n\n先别急着点头，\n也别急着翻脸。\n\n问两个问题：\n\n第一，\n借条上有我的签名吗？\n\n第二，\n这笔钱\n用在哪儿了？\n\n两个问题\n背后各站着一个条文。",
    "quote": "不是“他欠的我都要还”，\n也不是“他的债\n跟我无关”。",
    "knowledge": "《民法典》第一千零六十四条\n把债务分成两头：\n\n属于共同债务的——\n双方共同签名，\n或者一方事后追认；\n以及一方以个人名义\n为家庭日常生活需要\n所负的债务。\n\n不属于共同债务的——\n一方以个人名义\n超出家庭日常生活需要\n所负的债务；\n但债权人能证明\n用于共同生活、\n共同生产经营，\n或者基于双方共同意思表示的，\n除外。\n\n所以“谁签的”和“用在哪”，\n是两个要分开看的问题。",
    "related": "“我不签\n  就显得不信任他。”\n\n签字是把你\n也放进了\n这张借条里。\n\n信任可以给他，\n签名\n最好还是自己决定。",
    "action": "今天做一件小事：\n\n记住这两句话，\n下次有人上门时\n先问出口：\n\n“借条上有我签名吗？”\n“这笔钱用在哪儿了？”",
