    "title": "写下来，比说清楚更管用",
    "frontText": "她问：\n“那我们要不要\n  写点什么？”\n\n可以写。\n\n法律给这件事\n留了名字：\n\n约定财产制。\n\n两个人可以约定\n婚后所得的财产\n归各自所有、\n共同所有，\n或者一部分各自、\n一部分共同。\n\n但有一句话\n是硬的：\n应当采用书面形式。",
    "quote": "口头说好的，\n换一个日子\n就可能变成\n“我没说过”。",
    "knowledge": "《民法典》第一千零六十五条：\n\n男女双方可以约定\n婚姻关系存续期间\n所得的财产以及婚前财产\n归各自所有、共同所有，\n或者部分各自所有、\n部分共同所有。\n\n约定应当采用书面形式。\n没有约定或者约定不明确的，\n适用第一千零六十二条、\n第一千零六十三条。\n\n夫妻对财产约定的，\n对双方具有法律约束力。\n\n一句要点：\n没写下来的约定，\n在法律上\n接近没约定。",
