    "frontText": "“万一有一天\n  真的分开呢？”\n\n法律不是\n一句话说“平分”。\n\n它先说：\n两个人可以协议；\n协议不成，\n由法院\n根据财产的具体情况，\n按照照顾子女、女方\n和无过错方权益的原则判决。\n\n共同债务，\n也是共同偿还的。\n\n这不是偏袒，\n是把\n谁更弱一些\n写进了规则里。",
