  // 每周维度以卡片为准：取该周卡片维度的众数，没有卡片的周退回七维轮换。
  // 判定口径只在 lib/week-dimensions.mjs 定义一次，
  // scripts/check-week-dimensions.mjs 会校验本文件与它始终一致。
  const buildWeekDimensions = function (days) {
    const counts = {};
    days.forEach(function (day) {
      const week = Number(day && day.week);
      const id = day && day.dimension;
      if (!week || !id || id === 'overview') return;
      counts[week] = counts[week] || {};
      counts[week][id] = (counts[week][id] || 0) + 1;
    });
    const map = {};
    Object.keys(counts).forEach(function (key) {
      const bucket = counts[key];
      let best = '';
      let bestCount = -1;
      DIMENSION_IDS.forEach(function (id) {
        const count = bucket[id] || 0;
        if (count > bestCount) { best = id; bestCount = count; }
      });
      if (best) map[key] = best;
    });
    for (let week = 1; week <= 52; week += 1) {
      if (!map[week]) map[week] = DIMENSION_IDS[(week - 1) % DIMENSION_IDS.length];
    }
    map[53] = 'overview';
    return map;
  };
  weekDimensions = buildWeekDimensions(completeDays);
